insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('渋温泉', 'onsen', 36.734444, 138.433056, '渋温泉（しぶおんせん）は、長野県下高井郡山ノ内町にある温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Shibu-onsen02s3200.jpg/960px-Shibu-onsen02s3200.jpg', 'Wikipedia', 'wikipedia'),
  ('光泉寺', 'other', 36.622278, 138.595056, '光泉寺（こうせんじ）は、群馬県吾妻郡草津町にある真言宗豊山派の寺院である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/Kosen-ji_%28Kusatsu%29_Main_Hall.JPG/960px-Kosen-ji_%28Kusatsu%29_Main_Hall.JPG', 'Wikipedia', 'wikipedia'),
  ('白根神社', 'other', 36.624667, 138.596250, '白根神社（しらねじんじゃ）は、群馬県吾妻郡草津町に所在する神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/Shirane_Shrine_in_Kusatsu_town.jpg/960px-Shirane_Shrine_in_Kusatsu_town.jpg', 'Wikipedia', 'wikipedia'),
  ('渋峠', 'pass', 36.666505, 138.534492, '群馬と長野の県境に位置する絶景峠', 'seed_auto', 'LiwcRm4lcB4', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/%E6%B8%8B%E5%B3%A0_%E5%9B%BD%E9%81%93%E6%9C%80%E9%AB%98%E5%9C%B0%E7%82%B9_20130708_-_panoramio.jpg/960px-%E6%B8%8B%E5%B3%A0_%E5%9B%BD%E9%81%93%E6%9C%80%E9%AB%98%E5%9C%B0%E7%82%B9_20130708_-_panoramio.jpg', '690 Noda / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('渋峠ホテル', 'pass', 36.666167, 138.534083, '渋峠ホテル（しぶとうげホテル）は、長野県下高井郡山ノ内町と群馬県吾妻郡中之条町の境にある渋峠に位置するホテルである。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/Shibu-toge02n4272.jpg/960px-Shibu-toge02n4272.jpg', 'Wikipedia', 'wikipedia'),
  ('丸池観光ホテル', 'viewpoint', 36.718000, 138.488500, '丸池観光ホテル（まるいけかんこうホテル、 MARUIKE KANKO HOTEL）は、長野県下高井郡山ノ内町の志賀高原にあった観光ホテル。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Maruike_%28Yamanouchi%2C_Nagano%29_survey.jpg/960px-Maruike_%28Yamanouchi%2C_Nagano%29_survey.jpg', 'Photographed by Qurren (talk), with IXY Digital 10 compact digital camera. / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('志賀高原ホテル', 'viewpoint', 36.719286, 138.487853, '志賀高原ホテル（しがこうげんホテル）は、長野県下高井郡山ノ内町大字平穏の上信越高原国立公園志賀高原地域にかつて存在したホテルである。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/83/2024-10-22_J%C5%8Dshin%27etsu-k%C5%8Dgen_National_Park_08.jpg/960px-2024-10-22_J%C5%8Dshin%27etsu-k%C5%8Dgen_National_Park_08.jpg', 'Alexkom000 / CC BY 4.0 / Wikimedia Commons', 'commons'),
  ('日本国道最高地点', 'viewpoint', 36.660650, 138.535220, '標高2,172mの碑があり絶景が広がるスポット', 'seed_auto', '46fx021RPSg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/%E6%97%A5%E6%9C%AC%E5%9B%BD%E9%81%93%E6%9C%80%E9%AB%98%E5%9C%B0%E7%82%B9%E3%81%8B%E3%82%89%E8%8A%B3%E3%83%B6%E5%B9%B3%E3%81%AE%E7%9C%BA%E3%82%81_-_panoramio.jpg/960px-%E6%97%A5%E6%9C%AC%E5%9B%BD%E9%81%93%E6%9C%80%E9%AB%98%E5%9C%B0%E7%82%B9%E3%81%8B%E3%82%89%E8%8A%B3%E3%83%B6%E5%B9%B3%E3%81%AE%E7%9C%BA%E3%82%81_-_panoramio.jpg', '高橋文武 / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('日本国道最高地点碑', 'viewpoint', 36.660650, 138.535220, '標高2,172mの日本最高地点', 'seed_auto', 'LiwcRm4lcB4', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Kusatsu_town_seen_from_near_Shibutoge_%28Gunma%2C_Japan%29_02.jpg/960px-Kusatsu_town_seen_from_near_Shibutoge_%28Gunma%2C_Japan%29_02.jpg', '小石川人晃 / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('木戸池スキー場', 'viewpoint', 36.699722, 138.491111, '木戸池スキー場（きどいけスキーじょう）は、長野県下高井郡山ノ内町にあったスキー場である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Kidoike.jpg/960px-Kidoike.jpg', 'Photographed by Qurren (talk), with IXY Digital 10 compact digital camera. / CC BY-SA 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:志賀草津高原ルート'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('やまなみハイウェイ', '別府・由布院から阿蘇へと伸びる九州を代表する絶景ロード。由布岳の麓からダイナミックな草原風景へと変化する素晴らしい景観が広がります。
注意: 休日や観光シーズンは混雑 / 観光シーズン中の交通量増加や速度超過取締りに注意 / 観光シーズンの渋滞、冬季閉鎖・チェーン規制注意 / 標高が高く天候が急変しやすい（霧や低温に注意）。 / 冬季の路面凍結 / 休日・行楽シーズンの観光渋滞 / 冬季路面凍結注意、観光シーズンの渋滞 / 冬期は路面凍結や積雪に注意 / 観光渋滞に注意 / 冬季凍結注意 / 冬季凍結注意、観光シーズンの渋滞 / 冬季は凍結・積雪注意 / 2月に野焼きが行われるため時期によって風景が変わる。冬場は凍結に注意。 / 峠部分は霧や急カーブ、土砂崩れ等による規制に注意 / 観光シーズン（GWや紅葉期）は交通量が増加する / 観光シーズン中の交通量増加、冬期積雪・凍結注意 / 休日・観光シーズンの混雑、冬季の凍結・積雪に注意 / 冬季凍結注意・観光シーズン混雑 / 観光シーズンは交通量が多い / 観光シーズン（ゴールデンウィークや秋など）は阿蘇方面にかけて混雑・渋滞が発生しやすい / 冬季の積雪・凍結注意 / 観光シーズンの混雑、冬季凍結注意 / 秋～冬の凍結注意、観光シーズンの渋滞 / 冬季の路面凍結・積雪に注意 / 冬季は積雪・路面凍結に注意 / 冬季凍結・積雪注意 / 冬季凍結・積雪注意、観光シーズンの混雑 / 観光シーズン中の混雑、冬場の積雪・凍結 / 冬季路面凍結・積雪注意 / 冬季積雪・凍結注意 / 観光シーズンは交通量が増加 / 悪天候時は濃霧が発生しやすい / 観光シーズンや休日は混雑しやすい / 冬季の積雪や路面凍結（ブラックアイスバーン）に注意 / 冬期積雪・路面凍結注意 / 冬季は路面凍結に注意 / 冬期の積雪・凍結注意 / 冬期の積雪・路面凍結注意 / 早朝や冬季の凍結・濃霧に注意
