insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('dACjwpoWfkU', 'https://www.youtube.com/watch?v=dACjwpoWfkU', 'たった一日で九州をバイクでまわる天才的な方法を思いついたｗｗ', 'CABHEY RIDE ON!!', 4202098, '09:27'),
  ('mqq_Z3808eQ', 'https://www.youtube.com/watch?v=mqq_Z3808eQ', '自走で九州まで!!5万円縛り250CCで行く1週間の九州バイク旅【総集編】', 'しょうたろうモトブログ -Shotaro_Motovlog-', 1224894, ''),
  ('0dfjZJMDbW0', 'https://www.youtube.com/watch?v=0dfjZJMDbW0', '九州ツーリング行ってよかったベスト５', 'SV650で行くツーリング日記', 312270, ''),
  ('wbK8lpRHsU8', 'https://www.youtube.com/watch?v=wbK8lpRHsU8', 'バイク女子泣く、九州ひとり旅で人生観変わった…', '【元保育士】モトべはつこのmotovlog', 272298, '11:30'),
  ('OyGbKl2nAU8', 'https://www.youtube.com/watch?v=OyGbKl2nAU8', '九州の雄大さに圧倒された日〈大分～阿蘇〉｜30代女子の休日バイク Vlog', 'しーまん  | seaman bike & life vlog', 153704, '01:58'),
  ('Pm96O2-cojY', 'https://www.youtube.com/watch?v=Pm96O2-cojY', '絶景の連続！阿蘇くじゅうの大自然を駆け抜ける爽快ライド【沸騰大分】', '沸騰大分【おんせん県おおいた観光チャンネル】', 116860, '01:30'),
  ('VuPXhwEw3yM', 'https://www.youtube.com/watch?v=VuPXhwEw3yM', '知らないともったいない！ 九州・阿蘇へ行くなら景色最強なおすすめバイクツーリングコース', 'TabiQ', 95623, '06:34'),
