insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('寒の地獄温泉', 'onsen', 33.113470, 131.227110, '寒の地獄温泉（かんのじごくおんせん）は、九重連山の登山口、大分県玖珠郡九重町（旧国豊後国）にある温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Kan_no_Jigoku_Onsen.jpg/960px-Kan_no_Jigoku_Onsen.jpg', 'Wikipedia', 'wikipedia'),
  ('湯平温泉', 'onsen', 33.192280, 131.325420, '湯平温泉（ゆのひらおんせん）は、大分県由布市湯布院町湯平（旧国豊後国速見郡）にある温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Oita_yunohira1.jpg/960px-Oita_yunohira1.jpg', 'Wikipedia', 'wikipedia'),
  ('長者原温泉', 'onsen', 33.116640, 131.228220, '長者原温泉（ちょうじゃばるおんせん）は、大分県玖珠郡九重町長者原（旧国豊後国）にある温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/%E5%9D%8A%E3%81%8C%E3%81%A4%E3%82%8B%E8%AE%83%E6%AD%8C%E7%A2%91.jpg/960px-%E5%9D%8A%E3%81%8C%E3%81%A4%E3%82%8B%E8%AE%83%E6%AD%8C%E7%A2%91.jpg', 'Ueda Tsunehisa / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('椎矢峠', 'pass', 33.158930, 131.361112, 'コメントでおすすめの林道として言及', 'seed_auto', '0dfjZJMDbW0', 'https://i.ytimg.com/vi/0dfjZJMDbW0/hqdefault.jpg', 'YouTube', 'youtube'),
  ('佐多岬', 'viewpoint', 33.158930, 131.361112, '佐多岬ロードパークの先にある本土最南端の絶景スポット', 'seed_auto', '0dfjZJMDbW0', 'https://i.ytimg.com/vi/0dfjZJMDbW0/hqdefault.jpg', 'YouTube', 'youtube'),
  ('長者原', 'viewpoint', 33.118683, 131.229566, 'くじゅう連山を見渡す名物ストレート', 'seed_auto', 'ENf28jLcIv4', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/%E9%95%B7%E8%80%85%E5%8E%9F_20130815_-_panoramio.jpg/960px-%E9%95%B7%E8%80%85%E5%8E%9F_20130815_-_panoramio.jpg', '690 Noda / CC BY 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:やまなみハイウェイ'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

