insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('土小屋', 'rest', 33.548125, 133.252151, 'UFOラインの起点側にある休憩スポット', 'seed_auto', 'JM122avTh1k', 'https://i.ytimg.com/vi/JM122avTh1k/hqdefault.jpg', 'YouTube', 'youtube'),
  ('大川嶺', 'viewpoint', 33.548125, 133.252151, '視聴者コメントでおすすめされた絶景スポット', 'seed_auto', 'lYIq8Ujd9yo', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Mt.Okawamine_and_Mt.Kasatoriyama.jpg/960px-Mt.Okawamine_and_Mt.Kasatoriyama.jpg?utm_source=ja.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia', 'wikipedia'),
  ('高屋神社', 'viewpoint', 33.548125, 133.252151, '天空の鳥居として人気の絶景スポット', 'seed_auto', 'n4JDvKe9bdo', 'https://i.ytimg.com/vi/n4JDvKe9bdo/hqdefault.jpg', 'YouTube', 'youtube')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:ufoライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

