insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('西巌殿寺', 'other', 32.931611, 131.079250, '西巌殿寺（さいがんでんじ）は、熊本県阿蘇市黒川にある天台宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Asosan_Saigandenji.jpg/960px-Asosan_Saigandenji.jpg', 'Wikipedia', 'wikipedia'),
  ('阿蘇火山博物館', 'other', 32.885278, 131.051944, '阿蘇火山博物館（あそかざんはくぶつかん）は、熊本県阿蘇市にある博物館。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Aso_Volcano_Museum.jpg/960px-Aso_Volcano_Museum.jpg', 'Wikipedia', 'wikipedia'),
  ('道の駅阿蘇', 'rest', 32.936472, 131.080944, '道の駅阿蘇（みちのえき あそ）は、熊本県阿蘇市にある国道57号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Michinoeki_Aso_2011.JPG/960px-Michinoeki_Aso_2011.JPG', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:阿蘇パノラマライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

