insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('伊豆大上のおはぎ', 'food', 35.012658, 139.027064, '山の中にある人気のおはぎ店', 'seed_auto', 'DhVNYuhWFHg', 'https://i.ytimg.com/vi/DhVNYuhWFHg/hqdefault.jpg', 'YouTube', 'youtube'),
  ('峠の茶屋', 'food', 34.962851, 139.036049, 'ホルモン定食が人気。予約が必要', 'seed_auto', '4AC1cfnZzp8', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/20141201_%E5%B3%A0%E3%81%AE%E8%8C%B6%E5%B1%8B_03.jpg/960px-20141201_%E5%B3%A0%E3%81%AE%E8%8C%B6%E5%B1%8B_03.jpg', 'Ozawajun / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('白岩温泉', 'onsen', 34.963583, 138.986333, '白岩温泉（しらいわおんせん）は静岡県伊豆市（旧中伊豆町）にある温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/Sekino%2C_Izu%2C_Shizuoka_Prefecture_410-2504%2C_Japan_-_panoramio_%282%29.jpg/960px-Sekino%2C_Izu%2C_Shizuoka_Prefecture_410-2504%2C_Japan_-_panoramio_%282%29.jpg', '運転太郎 / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('伊豆実成寺', 'other', 34.950000, 139.000000, '實成寺（じつじょうじ）は、静岡県伊豆市柳瀬にある日蓮宗の本山（由緒寺院）。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/Izuhonzanjitsushoji.jpg/960px-Izuhonzanjitsushoji.jpg', 'Wikipedia', 'wikipedia'),
  ('亀石峠', 'pass', 35.022583, 139.041694, '亀石峠（かめいしとうげ）は、静岡県伊東市と伊豆の国市を結ぶ峠。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Izu_Peninsula_3D_2012.jpg/960px-Izu_Peninsula_3D_2012.jpg', 'Wikipedia', 'wikipedia'),
  ('山伏峠', 'pass', 35.048861, 139.033806, '山伏峠（やまぶしとうげ）は、静岡県伊豆の国市と熱海市を結ぶ峠で、上を伊豆スカイラインが交差する。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Izu_Peninsula_3D_2012.jpg/960px-Izu_Peninsula_3D_2012.jpg', 'Wikipedia', 'wikipedia'),
  ('湯河原峠', 'pass', 35.168056, 139.027833, '湯河原峠（ゆがわらとうげ）は、静岡県田方郡函南町桑原と神奈川県足柄下郡湯河原町宮上の峠。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/Shizuoka_Route_20_-02.jpg/960px-Shizuoka_Route_20_-02.jpg', 'Aimaimyi / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('鹿路庭峠', 'pass', 34.905056, 139.052972, '鹿路庭峠（ろくろばとうげ）は、静岡県伊東市と伊豆市を結ぶ峠。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Izu_Peninsula_3D_2012.jpg/960px-Izu_Peninsula_3D_2012.jpg', 'Wikipedia', 'wikipedia'),
  ('亀石スカイポート', 'rest', 35.024305, 139.043933, '視聴者コメントでソフトクリームが名物として挙げられているPA', 'seed_auto', 'IFUgHtm93DM', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Chojagahara%2C_Izunokuni%2C_Shizuoka_Prefecture_410-2312%2C_Japan_-_panoramio_%284%29.jpg/960px-Chojagahara%2C_Izunokuni%2C_Shizuoka_Prefecture_410-2312%2C_Japan_-_panoramio_%284%29.jpg', '運転太郎 / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('姫の沢公園', 'viewpoint', 35.117647, 139.050497, '姫の沢公園（ひめのさわこうえん）は、静岡県熱海市の北西部に位置する市営の総合公園である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/14/%E7%AC%B9%E5%B0%BB%E4%BA%A4%E5%B7%AE%E7%82%B9_-_panoramio.jpg/960px-%E7%AC%B9%E5%B0%BB%E4%BA%A4%E5%B7%AE%E7%82%B9_-_panoramio.jpg', 'kizitora / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('玄岳', 'viewpoint', 35.081667, 139.028056, '玄岳（くろたけ）は、静岡県の伊豆半島北東部の山稜にある山である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Mount_Kuro_20120821.jpg/960px-Mount_Kuro_20120821.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:伊豆スカイライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

