insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('芦ノ湖スカイライン', 'other', 35.197250, 138.992167, '芦ノ湖スカイライン（あしのこスカイライン）は、神奈川県と静岡県にまたがる一般自動車道事業による有料道路。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Ashinokoskyline_tollgate.jpg/960px-Ashinokoskyline_tollgate.jpg', 'Wikipedia', 'wikipedia'),
  ('駒形神社', 'other', 35.187417, 139.021611, '駒形神社（こまがたじんじゃ）は、神奈川県足柄下郡箱根町箱根に所在する神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Komagata_Shrine_in_Hakone_tawn.jpg/960px-Komagata_Shrine_in_Hakone_tawn.jpg', 'Wikipedia', 'wikipedia'),
  ('湖尻峠', 'pass', 35.230917, 138.978694, '湖尻峠（こじりとうげ）は、静岡県裾野市と神奈川県足柄下郡箱根町との境界、箱根山の外輪山にある標高850mの峠である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/SSW_view_from_Hakone_Volcano_in_1965.jpg/960px-SSW_view_from_Hakone_Volcano_in_1965.jpg', 'H. Grobe / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('箱根峠', 'pass', 35.181900, 139.013900, '箱根峠（はこねとうげ）は、神奈川県足柄下郡箱根町と静岡県田方郡函南町の境に位置する峠。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Lake_Ashi_from_Mt.Komagatake_03-2.jpg/960px-Lake_Ashi_from_Mt.Komagatake_03-2.jpg', 'Wikipedia', 'wikipedia'),
  ('バイカーズパラダイス南箱根', 'rest', 35.166762, 139.027953, 'ソフテイルサンダー250をレンタルした拠点', 'seed_auto', 'hM1X4PdiN2k', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/Shizuoka_Route_20_-02.jpg/960px-Shizuoka_Route_20_-02.jpg', 'Aimaimyi / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('道の駅箱根峠', 'rest', 35.186780, 139.015500, '道の駅箱根峠（みちのえき はこねとうげ）は、神奈川県足柄下郡箱根町にある国道1号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/%E9%81%93%E3%81%AE%E9%A7%85%E7%AE%B1%E6%A0%B9%E5%B3%A0_20150331_140913.jpg/960px-%E9%81%93%E3%81%AE%E9%A7%85%E7%AE%B1%E6%A0%B9%E5%B3%A0_20150331_140913.jpg', 'Wikipedia', 'wikipedia'),
  ('三国山', 'viewpoint', 35.220000, 138.980000, '三国山（みくにやま）は、神奈川県足柄下郡箱根町と静岡県裾野市とをまたぐ標高1,101.8mの山である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Hakone_Ashinoko_lake_dsc05463.jpg/960px-Hakone_Ashinoko_lake_dsc05463.jpg', 'Wikipedia', 'wikipedia'),
  ('大涌谷', 'viewpoint', 35.243601, 139.019730, '黒たまごを食べて寿命が7年延びると言われる観光スポット', 'seed_auto', 'hNeJ7sSK6X8', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Hakone_20220423122650_%2852267799889%29.jpg/960px-Hakone_20220423122650_%2852267799889%29.jpg', 'inunami / CC BY 2.0 / Wikimedia Commons', 'commons'),
  ('恩賜箱根公園', 'viewpoint', 35.196389, 139.025917, '恩賜箱根公園（おんしはこねこうえん）は、神奈川県足柄下郡箱根町元箱根にある神奈川県立の都市公園（風致公園）。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/View_of_Mount_HakoneKomagatake_from_Onshi-Hakone-Koen_Park.jpg/960px-View_of_Mount_HakoneKomagatake_from_Onshi-Hakone-Koen_Park.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:芦ノ湖スカイライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('八幡平アスピーテライン', '秋田と岩手を跨ぎ、八幡平の雄大な自然を貫く日本屈指の山岳ワインディングロード。初夏の雪解け「ドラゴンアイ」や壮大な山並みの絶景が楽しめます。
注意: 11月上旬〜4月中旬は冬季通行止め。紅葉シーズンは強い渋滞・混雑が発生する。 / 冬季閉鎖あり / 冬季閉鎖・開通直後の凍結注意 / 冬季閉鎖あり、春先の雪の回廊時期は路面凍結注意 / 冬季閉鎖あり。山頂付近は濃霧が発生しやすい / 冬季閉鎖（11月上旬〜4月下旬） / 冬季閉鎖（11月上旬〜4月中旬） / 冬季閉鎖あり。初夏でも残雪や急な悪天候・視界不良に注意。 / 冬季閉鎖（11月上旬〜4月下旬頃）、凍結注意 / 冬季閉鎖、濃霧発生注意 / 悪天候時の濃霧・急激な気温低下、冬季閉鎖あり / 冬季閉鎖（11月上旬～4月中旬） / 冬季通行止め、夜間通行止めあり / 冬季閉鎖あり（11月上旬〜4月中旬） / 冬季全面通行止め（例年11月上旬〜4月下旬） / 冬季全面通行止め（例年11月上旬〜4月中旬） / 冬季閉鎖（11月上旬〜4月下旬）。春先は凍結や強霧、急激な気温低下に注意。 / 冬季閉鎖あり（4月中旬開通）、スリップ注意 / 冬季閉鎖あり（例年11月上旬〜4月中旬） / 冬季閉鎖、凍結注意 / 冬季閉鎖あり。春は雪の回廊。
