insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('W9YUPPmC8ac', 'https://www.youtube.com/watch?v=W9YUPPmC8ac', 'お知らせとお願いがあります！', 'こつぶちゃんねる', 240143, ''),
  ('rPs1VDzZYM0', 'https://www.youtube.com/watch?v=rPs1VDzZYM0', '東北ツーリング 感動した道 BEST30', 'パナイモン [Rebel1100]', 175344, ''),
  ('utTgOhUmbeQ', 'https://www.youtube.com/watch?v=utTgOhUmbeQ', '【王道】東北の絶景ドライブ•ツーリングスポット13コース[永久保存版]', 'スバル車で行く東北わんこ旅『アッキー and Ten2』', 168505, ''),
  ('Pw-Cp460esk', 'https://www.youtube.com/watch?v=Pw-Cp460esk', 'バイクで東北一人旅。岩手県ツーリング中予想外の出来事に敗北する女', 'こつぶちゃんねる', 141572, ''),
  ('MR7kxFr_5bA', 'https://www.youtube.com/watch?v=MR7kxFr_5bA', 'GW東北一周ツーリング 東北の名道を楽しみ尽くす5日間【VOICEROID車載】', 'ゆかどろ', 30330, '09:06'),
  ('5a46UywEF_E', 'https://www.youtube.com/watch?v=5a46UywEF_E', '【絶景ドライブ】まるで絵画のような日本の美しい道10選｜一度は走りたい絶景ロード', 'Holiday Ideas', 22484, '09:38'),
  ('Azfco1YfXpU', 'https://www.youtube.com/watch?v=Azfco1YfXpU', '#5【東北】絶景ツーリグルートあるある 霧でなにも見えない八幡平 | 岩手・秋田・宮城 | SV650', 'STOMP', 14629, ''),
  ('q0eI9G_hpxo', 'https://www.youtube.com/watch?v=q0eI9G_hpxo', '【ジクサー250】快走路だらけの 山形・秋田・岩手 ツーリング！', 'へいぞうバイク旅', 9100, ''),
  ('LtSXrew3caE', 'https://www.youtube.com/watch?v=LtSXrew3caE', '【岩手県にある癒しの絶景】八幡平にある日本一長い雪の回廊と岩手山を望む大自然の絶景を巡るツーリング！秋田まで足を延ばし秋扇湖の幻想的な水没林も満喫しました【HONDA Gold Wing/モトブログ】', '突然rider', 9023, '09:00'),
  ('DpILHrxLvos', 'https://www.youtube.com/watch?v=DpILHrxLvos', '【バイクで東北ひとり旅】岩手県八幡平の絶景と世界で2番目に選ばれた盛岡へ…。名物わんこそばも堪能しました。【モトブログ/Honda Gold Wing】', '突然rider', 7863, ''),
  ('4gmQVXbAx6w', 'https://www.youtube.com/watch?v=4gmQVXbAx6w', '【東北バイク旅】絶景の秘境を求め八幡平から秋田へ！この時期にしか見れない景色とご当地グルメを巡るソロツーリング。美しい田沢湖とノスタルジックな角館も満喫しました。【Gold Wing/モトブログ】', '突然rider', 7188, ''),
  ('IXAGs19StXA', 'https://www.youtube.com/watch?v=IXAGs19StXA', '東北ツーリング2020 #1 八幡平アスピーテライン　田沢湖 【モトブログ】絶景探索 with YZF-R25', 'SHU MOTOR VLOG', 7062, ''),
  ('6qdMIvZzOnI', 'https://www.youtube.com/watch?v=6qdMIvZzOnI', '【フォルツァ250東北ツーリング】アスピーテライン悪天候で遭難…超絶景…まさかの展開！世界三景で痛感した「ツーリングの光と影」', 'チャンネルもーりんぐ', 5874, '15:31'),
  ('pyaA42mXWsU', 'https://www.youtube.com/watch?v=pyaA42mXWsU', '【東北地方】日本の絶景100選：美しき日本の風景', 'Holiday Ideas', 5189, ''),
  ('-FSxLo8JPas', 'https://www.youtube.com/watch?v=-FSxLo8JPas', '東北ツーリング＃3絶景の八幡平アスピーテラインを往くモトブログ＃57', 'Angrider', 4249, ''),
  ('1Y-aHbFoHbc', 'https://www.youtube.com/watch?v=1Y-aHbFoHbc', '【TOHOKU RoadTrip】#4 絶景のアスピーテライン・乳頭温泉編/八幡平の奇跡/田沢湖キャンプ/東北ツーリング【Audi A5】', 'UC’s Log | The Great Escape', 4067, ''),
  ('FZ4oCMRpSR8', 'https://www.youtube.com/watch?v=FZ4oCMRpSR8', '【絶景！八幡平ドラゴンアイ】初夏の絶景！秋田・岩手ツーリング！', 'へいぞうバイク旅', 3911, ''),
  ('oD6ghTxoRGw', 'https://www.youtube.com/watch?v=oD6ghTxoRGw', '3分半で東北ツーリング♪♯37', 'AIRU LAND.', 2323, ''),
  ('iK-WJpApNcA', 'https://www.youtube.com/watch?v=iK-WJpApNcA', '八幡平ｱｽﾋﾟｰﾃﾗｲﾝ、奥入瀬渓流【絶景ツーリング】3泊4日東北ぐるり女一人旅『YAMAHA BOLT』ナツゾラ最高かよっ(*ﾟ∀ﾟ)#3/4', 'Black Bolt/boru', 1893, ''),
  ('8_2edm_sylA', 'https://www.youtube.com/watch?v=8_2edm_sylA', '混浴温泉って本当にあるんだねぇ【東北ツーリングPart3】  紲星あかり車載 [VOICEROID車載]', 'お燐のバイク旅チャンネル', 1860, ''),
  ('z6N9PtZ9WdU', 'https://www.youtube.com/watch?v=z6N9PtZ9WdU', '【２０２５東北ツーリング】絶景の八幡平アスピーテラインを越えて秋田県へ！！【モトブログ】', '榛名【はるな】のバイクで探訪記', 1512, ''),
  ('82fxxrRM2CA', 'https://www.youtube.com/watch?v=82fxxrRM2CA', '【東北 絶景ドライブ】一度は走りたい絶景ロード13選｜奥入瀬・八幡平・蔵王・磐梯吾妻', 'Holiday Ideas', 1430, '01:29'),
  ('1fFOhJiVv9I', 'https://www.youtube.com/watch?v=1fFOhJiVv9I', '【日本一周】東北の誇る山岳絶景ロード！【八幡平アスピーテライン】', 'キイハンター', 1314, ''),
  ('mhi0lAQX6HY', 'https://www.youtube.com/watch?v=mhi0lAQX6HY', '【モトブログ】元ヤンキー3人と岩手の絶景見てきた！！【アスピーテライン】', 'ちょっち', 900, ''),
  ('TLwS0JzLw0M', 'https://www.youtube.com/watch?v=TLwS0JzLw0M', '正直、東北なめてました　8日間2100㎞の景色が最高だった', '56 Rock', 555, ''),
  ('TWZXkndceSE', 'https://www.youtube.com/watch?v=TWZXkndceSE', '【東北ツーリング#5】標高1600mの絶景ロード　八幡平アスピーテライン　　田代平高原～八幡平～田沢湖', 'さかみきた ', 497, ''),
  ('HoNda20wzCY', 'https://www.youtube.com/watch?v=HoNda20wzCY', '超絶景！！秋田•青森•岩手！東北ひとり旅ツーリング！【CBR600RR】', 'かぶゆー', 273, ''),
  ('xyppz31Evgk', 'https://www.youtube.com/watch?v=xyppz31Evgk', '【Vstrom650】2021春の絶景東北ツーリング【Motorcycle Touring in Tohoku region of Japan】', 'BikerHiker Motovlog', 240, '00:00'),
  ('5XvHuxJUusg', 'https://www.youtube.com/watch?v=5XvHuxJUusg', '【東北ツーリング＃3】朝霧を抜けて絶景へ。八幡平アスピーテライン', 'ちび Rider156 with Oscar Touring Diary', 233, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
