insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('ycHrPTrAg-E', 'https://www.youtube.com/watch?v=ycHrPTrAg-E', '【最新版】バイクで走る最高の道 TOP30【2022】', 'ケロステ', 545213, ''),
  ('iPYoGjApa2g', 'https://www.youtube.com/watch?v=iPYoGjApa2g', '下道で仙台まで!!250CCで行く2泊3日の仙台バイク旅【総集編】', 'しょうたろうモトブログ -Shotaro_Motovlog-', 172197, ''),
  ('utTgOhUmbeQ', 'https://www.youtube.com/watch?v=utTgOhUmbeQ', '【王道】東北の絶景ドライブ•ツーリングスポット13コース[永久保存版]', 'スバル車で行く東北わんこ旅『アッキー and Ten2』', 168505, ''),
  ('WXHcJYkCXbc', 'https://www.youtube.com/watch?v=WXHcJYkCXbc', '［イッキ見］1泊2日1350km東北ツーリング 群馬～福島・宮城・山形・秋田風光明媚な景色を求めて！！[東北1人旅]', 'KeboRider', 36260, ''),
  ('3f9QK5PZDU0', 'https://www.youtube.com/watch?v=3f9QK5PZDU0', '【2026最新道路開通情報】GWに行くべき絶景道路が続々冬季閉鎖解除開通！「東日本・最強ツーリングドライブルート」＊群馬から日帰り一泊で行ける範囲', 'おでかけポコ', 32155, ''),
  ('MR7kxFr_5bA', 'https://www.youtube.com/watch?v=MR7kxFr_5bA', 'GW東北一周ツーリング 東北の名道を楽しみ尽くす5日間【VOICEROID車載】', 'ゆかどろ', 30330, '19:41'),
  ('hybVzV15zck', 'https://www.youtube.com/watch?v=hybVzV15zck', '#2 【東北】ダメかなと思ったら運良く絶景とうまい食事を堪能できたツーリング | 福島・宮城・山形 | SV650', 'STOMP', 29846, ''),
  ('4gE0AFm3aj8', 'https://www.youtube.com/watch?v=4gE0AFm3aj8', '【ADV150】南東北日帰りツーリング', 'へいぞうバイク旅', 9052, ''),
  ('26vU9ggcp1c', 'https://www.youtube.com/watch?v=26vU9ggcp1c', '【東北バイク旅】福島から山形へ吾妻連峰と蔵王連峰を見渡す絶景ツーリング！ライダーが集まる神社やカフェも満喫しました。【Honda Gold Wing/モトブログ】', '突然rider', 9033, '15:00'),
  ('8uERFzNugp0', 'https://www.youtube.com/watch?v=8uERFzNugp0', '【東北バイク旅】この時期の蔵王連峰は美しすぎる…。残雪の絶景山岳ロードを走り山形へ！大自然の景色とグルメを満喫するツーリング。【HONDA Gold Wing/Rebel/モトブログ】', '突然rider', 8874, ''),
  ('1K1NrJvmec0', 'https://www.youtube.com/watch?v=1K1NrJvmec0', '【1泊2日で巡る東北！】秋田・山形ツーリング2025年 仁賀保高原・鳥海山・月山・蔵王を400Xで走る絶景バイク旅', 'Moto Lifez', 7854, '16:22'),
  ('FWdJ268ZyzY', 'https://www.youtube.com/watch?v=FWdJ268ZyzY', '【バイク旅】秋の訪れを感じる天空の山寺へ！山形の絶対に行きたいツーリングスポットを巡る。絶景とおしゃれカフェなどお勧めグルメ教えます。【モトブログ】Gold Wing Tour/Rebel250', '突然rider', 5801, ''),
  ('KJnifzZq0lQ', 'https://www.youtube.com/watch?v=KJnifzZq0lQ', '【バイク旅】バイク乗り必見！宮城県の新しいツーリングスポットSUGOカフェで絶品グルメを堪能！バイク旅で必ず立ち寄りたくなるお勧めグルメも教えます。【モトブログ/Gold Wing Tour】', '突然rider', 5059, '03:32'),
  ('Osbfea8BZW0', 'https://www.youtube.com/watch?v=Osbfea8BZW0', '【東北の絶景道】残雪の蔵王エコーラインへ！五感を揺さぶる大自然の絶景が最高すぎた。｜バイク乗りなら一度は走るべき聖地。【HONDA Gold Wing/モトブログ】', '突然rider', 4533, '08:00'),
  ('8tfx9hjQM6E', 'https://www.youtube.com/watch?v=8tfx9hjQM6E', '【東北バイク旅】最高の景色がここにあった…。東北の宮城と山形に跨る神秘的な蔵王連峰経由で酷道と呼ばれる秘境の林道二口峠へ！大自然の絶景を満喫しました。【HONDA Gold Wing/モトブログ】', '突然rider', 4346, '07:00'),
  ('Vud1gnX8FxA', 'https://www.youtube.com/watch?v=Vud1gnX8FxA', '【東北ツー】雪の回廊‼︎東北の絶景てんこ盛りツーリング〈Part.1〉', 'ありちゃん', 3961, ''),
  ('EuBE-MMN3EQ', 'https://www.youtube.com/watch?v=EuBE-MMN3EQ', 'カンナムスパイダー　絶景！雲海ロードを走る！', 'MASAKOIスパイダーツーリング', 3920, ''),
  ('MdLO14BMec0', 'https://www.youtube.com/watch?v=MdLO14BMec0', '【バイク旅】圧巻！天空へとそそり立つ『雪の壁』東北が誇る蔵王エコーライン雪の回廊！そこで目にした光景とは？【モトブログ】Gold Wing tour', '突然rider', 2880, ''),
  ('2ip-k4Red5w', 'https://www.youtube.com/watch?v=2ip-k4Red5w', '【またもや悲劇】リベンジで蔵王へ！新型レブル1100Tでエコーラインを走るも2度目の大失敗！心折れるも東北の絶景とバイク女子が経営するお店で美味しいグルメを堪能しました。【モトブログ】', '突然rider', 2689, ''),
  ('n4yBqovw1KQ', 'https://www.youtube.com/watch?v=n4yBqovw1KQ', '2020 東北ツーリング『絶景の蔵王エコーラインと赤湯辛味噌ラーメン』のモトブログ', 'KOBA MotoChannel', 2541, ''),
  ('82fxxrRM2CA', 'https://www.youtube.com/watch?v=82fxxrRM2CA', '【東北 絶景ドライブ】一度は走りたい絶景ロード13選｜奥入瀬・八幡平・蔵王・磐梯吾妻', 'Holiday Ideas', 1430, '03:12'),
  ('1dbzyvx8Dl8', 'https://www.youtube.com/watch?v=1dbzyvx8Dl8', '【東北ツーリング】#4人生初の東北へ👍仙台ライダーと超有名な食事処へ😊', '空と雲・風の色   T.k Rider Channel ', 1210, ''),
  ('iTG6BxDR3fk', 'https://www.youtube.com/watch?v=iTG6BxDR3fk', 'モトブログ #018ｰ1日目 絶景！！蔵王エコーライン   東北周遊ツーリング【GSX-R1000R】', 'ITKライダー', 1174, ''),
  ('HOUGvg3t_fA', 'https://www.youtube.com/watch?v=HOUGvg3t_fA', '東北ツーリング PART4「開く天界の扉」', 'Cbr400r Takaprilia RS660', 1122, '00:45'),
  ('4GKhPg5jZIM', 'https://www.youtube.com/watch?v=4GKhPg5jZIM', '雪の壁と満開の桜 | 東北ツーリング', 'バイク猫のモトブログ', 706, ''),
  ('nmmH04Z5l_s', 'https://www.youtube.com/watch?v=nmmH04Z5l_s', '【東北ツーリング】#5  いよいよ絶景の蔵王エコーラインへ😆宮城県の快走路にビックリです😊', '空と雲・風の色   T.k Rider Channel ', 671, ''),
  ('xyppz31Evgk', 'https://www.youtube.com/watch?v=xyppz31Evgk', '【Vstrom650】2021春の絶景東北ツーリング【Motorcycle Touring in Tohoku region of Japan】', 'BikerHiker Motovlog', 240, '31:46'),
  ('c0HJISe6amk', 'https://www.youtube.com/watch?v=c0HJISe6amk', '【モトブログ#80】蔵王御釜ツーリング【ワインディング】【絶景】', 'バク バイク', 133, '14:30')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('峩々温泉', 'onsen', 38.143889, 140.500278, '峩々温泉（ががおんせん）は宮城県柴田郡川崎町にある温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Gaga_hotspring_zao.jpg/960px-Gaga_hotspring_zao.jpg', 'Wikipedia', 'wikipedia'),
  ('刈田嶺神社', 'other', 38.124611, 140.576528, '刈田嶺神社（かったみねじんじゃ）は、奥羽山脈・蔵王連峰の宮城県側、刈田岳東麓の遠刈田にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Kattamine-jinja_satomiya_Haiden.jpg/960px-Kattamine-jinja_satomiya_Haiden.jpg', 'Wikipedia', 'wikipedia'),
  ('お釜', 'viewpoint', 38.136155, 140.449567, '蔵王の代表的な絶景スポット', 'seed_auto', 'iPYoGjApa2g', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Zao%2C_Katta_District%2C_Miyagi_Prefecture%2C_Japan_-_panoramio_%283%29.jpg/960px-Zao%2C_Katta_District%2C_Miyagi_Prefecture%2C_Japan_-_panoramio_%283%29.jpg', 'Hiroyuki Sato / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('三階の滝', 'viewpoint', 38.131694, 140.522222, '三階の滝（さんかいのたき、三階滝とも）は、宮城県刈田郡蔵王町にある滝。', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/c/c8/Sankai_no_taki_5nov07.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:蔵王エコーライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('金精道路（金精峠）', '群馬県片品村と栃木県奥日光を結ぶ高標高の山岳道路。金精峠からの景色や紅葉の美しさで人気が高く、走り応えのあるワインディングが続きます。
注意: 冬季閉鎖あり（12月下旬〜4月下旬）。 / 冬季閉鎖あり。秋期・早朝は気温が一桁になるため防寒必須 / 冬季閉鎖あり（12月下旬〜4月下旬頃） / 冬季閉鎖（12月下旬〜4月下旬）。標高2000m超のため積雪や路面凍結、気温低下に注意。 / 冬季閉鎖（12月下旬〜4月下旬）、秋終盤の路面凍結・積雪注意 / 初冠雪・路面凍結・塩カル散布、冬季閉鎖あり / 冬季閉鎖あり（12月下旬〜4月下旬）。晩秋〜早春は凍結・積雪注意。 / 冬季閉鎖あり（12月下旬〜4月下旬）。濃霧・悪天候に注意 / 冬季閉鎖あり（例年12月下旬〜4月下旬）。紅葉シーズンの渋滞や路肩駐車、濡れた落ち葉によるスリップに注意。 / 標高が高く秋は急激に冷え込みます。冬季閉鎖あり。 / 冬季閉鎖、トンネル内冷涼・暗所注意 / 冬季閉鎖あり。スノーシェッド内は路面が濡れていることが多い / 冬季閉鎖（12月下旬～4月下旬） / 12月下旬〜4月下旬冬季閉鎖 / 冬期全面通行止めあり（12月下旬〜4月下旬）
