insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('qkK-XfXLKFk', 'https://www.youtube.com/watch?v=qkK-XfXLKFk', 'モトブログ #0215 首都圏から行く日帰りツーリングスポット５選【GSX-R1000R】', 'ITKライダー', 106463, ''),
  ('3f9QK5PZDU0', 'https://www.youtube.com/watch?v=3f9QK5PZDU0', '【2026最新道路開通情報】GWに行くべき絶景道路が続々冬季閉鎖解除開通！「東日本・最強ツーリングドライブルート」＊群馬から日帰り一泊で行ける範囲', 'おでかけポコ', 32155, ''),
  ('VaLbp8WGzGM', 'https://www.youtube.com/watch?v=VaLbp8WGzGM', '【奥日光紅葉2026の参考に】「金精峠」から「いろは坂」まで・奥日光湯元温泉・湯ノ湖・湯滝(上)・戦場ヶ原・光徳園地・龍頭滝(竜頭の滝)・中禅寺湖・群馬県菅沼周辺金精道路', 'おでかけポコ', 27633, ''),
  ('FwyrCe-hniE', 'https://www.youtube.com/watch?v=FwyrCe-hniE', '2026【群馬県】真夏でも涼しい峠道ベスト5 ～気象庁データから8月の平均気温を計算！夏のツーリング、ドライブの参考に！', 'おでかけポコ', 24648, ''),
  ('Zf7y8oNKUUQ', 'https://www.youtube.com/watch?v=Zf7y8oNKUUQ', '【奥日光紅葉2026の参考に】「いろは坂」～黒髪平・明智平・中禅寺湖・華厳の滝・イタリア大使館別荘記念公園・竜頭の滝・戦場ヶ原・光徳園地・湯滝・湯ノ湖・奥日光湯元温泉「金精峠」「山王峠」', 'おでかけポコ', 22302, ''),
  ('_SJHL6z7oFE', 'https://www.youtube.com/watch?v=_SJHL6z7oFE', '奥日光の紅葉状況2025！いろは坂(明智平周辺)、中禅寺湖は色づき始め、金精峠は見頃。ツーリングやドライブの参考にどうぞ｜モンキー125', 'ゼキザップ_モトブログ', 18879, '11:28'),
  ('FBbZLEd8jgc', 'https://www.youtube.com/watch?v=FBbZLEd8jgc', '【奥日光紅葉2026の参考に】「いろは坂」から明智平・中禅寺湖・華厳の滝・イタリア大使館別荘記念公園・竜頭の滝・戦場ヶ原・光徳園地・湯滝・湯ノ湖・奥日光湯元温泉「金精峠」菅沼、丸沼まで', 'おでかけポコ', 17268, ''),
  ('FwjcmVj2do8', 'https://www.youtube.com/watch?v=FwjcmVj2do8', '【バイク旅】奥日光から金精峠経由で群馬へ！変わり果てた華厳の滝と美しい奥四万湖の大自然に感動するツーリング。【Honda Gold Wing/Rebel 1100T/モトブログ】', '突然rider', 13521, ''),
  ('75uzyw5vrac', 'https://www.youtube.com/watch?v=75uzyw5vrac', '開通日翌日走行【金精峠2026】4月25日走行した時の気温は？雪は？奥日光の桜は？GWにお出かけしよう～絶景の金精道路を走って奥日光へ', 'おでかけポコ', 11113, ''),
  ('jOlJrg93__Y', 'https://www.youtube.com/watch?v=jOlJrg93__Y', '【北関東バイク旅】奥日光にある金精峠経由で群馬へ！大自然の絶景と異国情緒溢れる神秘的な沸光山放水寺を巡るツーリング。地元の人気グルメも満喫しました。【Honda Gold Wing/モトブログ】', '突然rider', 9194, ''),
  ('0Contni9oqw', 'https://www.youtube.com/watch?v=0Contni9oqw', '秋の日光！中禅寺湖やいろは坂・金精峠をハーレーでツーリング', 'イチロクのハーレーちゃんねる', 8726, '19:23'),
  ('fXmiJck1eBQ', 'https://www.youtube.com/watch?v=fXmiJck1eBQ', '【YZF‐R1】往復440キロ 日光の紅葉の求めて【ツーリング】', 'RY×バイク旅', 7738, ''),
  ('ZUTaLx8qrQA', 'https://www.youtube.com/watch?v=ZUTaLx8qrQA', '12月18日【奥日光雪景色】中禅寺湖、華厳の滝、龍頭の滝(竜頭の滝)、戦場ヶ原、湯ノ湖、湯滝、奥日光湯元温泉へツーリングドライブ', 'おでかけポコ', 6544, ''),
  ('Cw62PaRq9iw', 'https://www.youtube.com/watch?v=Cw62PaRq9iw', '【スタッドレスタイヤの威力はいかに？】スーパーカブを冬タイヤに履き替えて冬季閉鎖一週間前の金精峠チャレンジ記録', 'おでかけポコ', 5969, ''),
  ('jSnPPkVYahU', 'https://www.youtube.com/watch?v=jSnPPkVYahU', '2026年【栃木県】真夏に涼しい道路ベスト5 ・絶景スポット・展望地・道路最高地点も紹介！～気象庁データから8月の平均気温を計算！夏のツーリング、ドライブの参考に！', 'おでかけポコ', 5107, ''),
  ('4H1mQmy1oLE', 'https://www.youtube.com/watch?v=4H1mQmy1oLE', '奥日光の初冠雪と紅葉で異色の絶景2025！いろは坂(明智平周辺)、中禅寺湖が見頃、金精峠は初冠雪で三段紅葉｜モンキー125で秋の栃木ツーリング', 'ゼキザップ_モトブログ', 3792, '09:06'),
  ('KFdskLYx9Wc', 'https://www.youtube.com/watch?v=KFdskLYx9Wc', '赤城山の紅葉と雪化粧…奇跡の絶景！モンキー125で秋の群馬ツーリング', 'ゼキザップ_モトブログ', 3478, ''),
  ('fAaZ5j3Qtjs', 'https://www.youtube.com/watch?v=fAaZ5j3Qtjs', '紅葉と雪景色が幻想的！金精峠と丸沼高原をモンキー125でツーリング^^', 'ゼキザップ_モトブログ', 3317, '00:00'),
  ('KiQicNNUJas', 'https://www.youtube.com/watch?v=KiQicNNUJas', '【モトブログ】絶景はナシ!!タイヤの穴だけ見つめた金精峠ツーリング', '練り物ちっくーモトブログ', 3028, '08:40'),
  ('1AC39XWkrlg', 'https://www.youtube.com/watch?v=1AC39XWkrlg', '【YZF‐R1】下道320キロ 日光・群馬のバイク旅【道の駅】', 'RY×バイク旅', 2590, ''),
  ('FeQbYQ91tVo', 'https://www.youtube.com/watch?v=FeQbYQ91tVo', 'いろは坂から奥日光に続く道はだんだん紅葉していくよツーリング', 'Tsuka Walker', 595, ''),
  ('TRjm7ZrkRo8', 'https://www.youtube.com/watch?v=TRjm7ZrkRo8', '【ツーリングプラン】「もはや神コスパ」な3000円日帰りツーリング｜絶景ロードを駆け抜ける！', '​のっとん / バイク旅ch - NoTone Ride Japan', 335, ''),
  ('Kuxh4lmNhpU', 'https://www.youtube.com/watch?v=Kuxh4lmNhpU', '奥利根ゆけむり街道 知らなかったけど最高な道じゃないかツーリング', 'Tsuka Walker', 286, ''),
