insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('日光湯元温泉', 'onsen', 36.806500, 139.424420, '日光湯元温泉（にっこうゆもとおんせん）は、栃木県日光市奥日光の湯ノ湖畔、金精峠の麓にある温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Yumoto%2C_Nikko_National_Park%2C_Tochigi%2C_Japan.jpg/960px-Yumoto%2C_Nikko_National_Park%2C_Tochigi%2C_Japan.jpg', 'Wikipedia', 'wikipedia'),
  ('日光湯元温泉スキー場', 'onsen', 36.804722, 139.412500, '日光湯元温泉スキー場（にっこうゆもとおんせんスキーじょう）は、栃木県日光市湯元温泉にある東武興業が運営するスキー場である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/%E6%97%A5%E5%85%89%E6%B9%AF%E5%85%83%E6%B8%A9%E6%B3%89%E3%82%B9%E3%82%AD%E3%83%BC%E5%A0%B4.jpg/960px-%E6%97%A5%E5%85%89%E6%B9%AF%E5%85%83%E6%B8%A9%E6%B3%89%E3%82%B9%E3%82%AD%E3%83%BC%E5%A0%B4.jpg', 'Wikipedia', 'wikipedia'),
  ('温泉ヶ岳', 'onsen', 36.824400, 139.403900, '温泉ヶ岳（ゆせんがたけ）は、栃木県日光市と群馬県利根郡片品村にまたがる標高2,332.9mの火山。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/%E6%97%A5%E5%85%892004%E5%B9%B411%E6%9C%88034.jpg/960px-%E6%97%A5%E5%85%892004%E5%B9%B411%E6%9C%88034.jpg', 'Wikipedia', 'wikipedia'),
  ('温泉寺', 'onsen', 36.808333, 139.423333, '温泉寺（おんせんじ）は、栃木県日光市湯元にある天台宗の寺院で、輪王寺の別院となっている。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Onsenji_temple_ver1.jpg/960px-Onsenji_temple_ver1.jpg', 'Wikipedia', 'wikipedia'),
  ('金精トンネル', 'pass', 36.818510, 139.396519, '栃木県と群馬県の境に位置する標高高所のトンネル', 'seed_auto', '7aIZFMaoCmE', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Lake_Sugenuma_2010_-_panoramio.jpg/960px-Lake_Sugenuma_2010_-_panoramio.jpg', 'jtease9325 / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('金精峠', 'pass', 36.819064, 139.396759, '群馬県と栃木県の県境にある高所峠', 'seed_auto', '9Ji_4LyEq9c', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/%E9%87%91%E7%B2%BE%E5%B3%A0_-_panoramio.jpg/960px-%E9%87%91%E7%B2%BE%E5%B3%A0_-_panoramio.jpg', 'alonfloc / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('丸沼', 'viewpoint', 36.826191, 139.343742, '標高が高くスノーシェッドが連なる区間', 'seed_auto', 'KiQicNNUJas', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/%E4%B8%B8%E6%B2%BC%E9%AB%98%E5%8E%9F_-_panoramio.jpg/960px-%E4%B8%B8%E6%B2%BC%E9%AB%98%E5%8E%9F_-_panoramio.jpg', 'alonfloc / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('湯ノ湖', 'viewpoint', 36.800000, 139.423611, '湯ノ湖（ゆのこ）は、栃木県日光市の西部にある湖。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/200731_Yunoko_Nikko_Tochigi_pref_Japan07s3.jpg/960px-200731_Yunoko_Nikko_Tochigi_pref_Japan07s3.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:金精道路'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('国道406号（白沢峠）', '鬼無里から峠を抜けて白馬村へと繋がる山岳ルート。白沢洞門のトンネル内から額縁のように切り取られる北アルプスの大絶景が非常に有名です。
注意: 山岳道路のため車幅狭小部や冬季閉鎖・積雪凍結に注意 / 冬季凍結・狭隘区間あり / トンネル手前に大型車のすれ違い注意あり / 酷道と呼ばれる狭隘・曲折区間あり、路面のひび割れや摩耗に注意 / 冬期〜春先の積雪・路面凍結に注意。一部狭隘区間あり。 / 標高が高いため早春の積雪や路面凍結に注意 / 洞門付近は幅員が狭く観光客・撮影者の横断に注意 / 幅員狭小な酷道区間あり、冬季凍結・閉鎖注意 / トンネルを抜けた直後の路肩停車注意 / 峠道のためカーブが多く、冬期・残雪期は路面状況に注意 / 冬季閉鎖や急カーブ多し / 標高差による急霧や連続カーブに注意 / 峠道はカーブが多く、路上駐車に注意が必要 / 一部道幅が狭くブラインドコーナーあり / 濃霧が発生しやすい区間あり / トンネル内漏水・暗闇注意、一部道幅狭小あり / トンネル手前のカーブ、冬季路面凍結注意 / 狭隘区間・冬季閉鎖および路面凍結注意
