insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('道の駅大津', 'rest', 32.880860, 130.891140, '道の駅大津（みちのえき おおづ）は、熊本県菊池郡大津町にある国道57号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/Ozu_Roadside_Station.jpg/960px-Ozu_Roadside_Station.jpg', 'Wikipedia', 'wikipedia'),
  ('大観峰', 'viewpoint', 32.996370, 131.067310, '阿蘇谷と阿蘇五岳を一望できる大パノラマ絶景ポイント', 'seed_auto', 'AHEC1EdeKQc', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/%E5%A4%A7%E8%A6%B3%E5%B3%B0_20150918_-_panoramio.jpg/960px-%E5%A4%A7%E8%A6%B3%E5%B3%B0_20150918_-_panoramio.jpg', '690 Noda / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('扇谷展望所跡', 'viewpoint', 32.997552, 131.080352, '以前の待ち合わせ予定地（訪問時進入禁止）', 'seed_auto', '01TnUuEg1to', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/%E9%98%BF%E8%98%87_%E3%81%9D%E3%81%AE05_-_panoramio.jpg/960px-%E9%98%BF%E8%98%87_%E3%81%9D%E3%81%AE05_-_panoramio.jpg', 'sk01 / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('長者原', 'viewpoint', 32.860052, 130.863955, 'やまなみハイウェイ沿いの代表的な絶景ポイント', 'seed_auto', 'mqq_Z3808eQ', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Mount_Kuju_October_2011_01.jpg/960px-Mount_Kuju_October_2011_01.jpg?utm_source=ja.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:阿蘇ミルクロード'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

