insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('北門神社', 'other', 45.420000, 141.671306, '北門神社（ほくもんじんじゃ）は、北海道稚内市にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/%E7%A8%9A%E5%86%85_%E5%8C%97%E9%96%80%E7%A5%9E%E7%A4%BE_-_panoramio.jpg/960px-%E7%A8%9A%E5%86%85_%E5%8C%97%E9%96%80%E7%A5%9E%E7%A4%BE_-_panoramio.jpg', 'Wikipedia', 'wikipedia'),
  ('宗谷岬神社', 'other', 45.521833, 141.934778, '宗谷岬神社（そうやみさきじんじゃ）は、北海道稚内市宗谷岬にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/%E6%97%A5%E6%9C%AC%E6%9C%80%E5%8C%97%E3%81%AE%E7%A2%91%E3%81%A8%E9%96%93%E5%AE%AE%E6%9E%97%E8%94%B5%E3%81%AE%E9%8A%85%E5%83%8F_-_panoramio.jpg/960px-%E6%97%A5%E6%9C%AC%E6%9C%80%E5%8C%97%E3%81%AE%E7%A2%91%E3%81%A8%E9%96%93%E5%AE%AE%E6%9E%97%E8%94%B5%E3%81%AE%E9%8A%85%E5%83%8F_-_panoramio.jpg', 'Mamusi Taka / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('北海道立宗谷ふれあい公園', 'viewpoint', 45.394167, 141.756667, '北海道立宗谷ふれあい公園（ほっかいどうりつそうやふれあいこうえん）は、北海道稚内市にある公園。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/36/Soya_Fureai_park_multifield.jpg/960px-Soya_Fureai_park_multifield.jpg', 'Wikipedia', 'wikipedia'),
  ('大岬旧海軍望楼跡', 'viewpoint', 45.521438, 141.937900, '大岬旧海軍望楼跡（おおみさききゅうかいぐんぼうろうあと）は、稚内市宗谷岬公園内に現存する旧帝国海軍が建設した海軍望楼の軍事史跡である。', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/a/a0/Ohmisaki%E3%83%BBkyu-kaigun-bourou_6260391%E5%8F%B2%E8%B7%A1%E5%A4%A7%E5%B2%AC%E6%97%A7%E6%B5%B7%E8%BB%8D%E6%9C%9B%E6%A5%BC.jpg', 'Wikipedia', 'wikipedia'),
  ('宗谷岬', 'viewpoint', 45.511020, 141.943039, 'コメントでおすすめされている日本最北端の岬', 'seed_auto', '_CngvLboTZc', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/%E5%AE%97%E8%B0%B7%E5%B2%AC%E7%89%A7%E5%A0%B4_-_panoramio.jpg/960px-%E5%AE%97%E8%B0%B7%E5%B2%AC%E7%89%A7%E5%A0%B4_-_panoramio.jpg', 'Yobito KAYANUMA / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('宗谷岬公園', 'viewpoint', 45.520278, 141.937500, '', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/Tower_of_Prayer_monument%2C_Cape_Soya%2C_Wakkanai%2C_Japan.jpg/960px-Tower_of_Prayer_monument%2C_Cape_Soya%2C_Wakkanai%2C_Japan.jpg', 'OKJaguar / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('宗谷岬灯台', 'viewpoint', 45.521389, 141.936389, '宗谷岬灯台（そうやみさきとうだい）は、北海道稚内市宗谷岬に建つ灯台。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Soyamisaki_lighthouse.JPG/960px-Soyamisaki_lighthouse.JPG', 'Wikipedia', 'wikipedia'),
  ('白い道', 'viewpoint', 45.491371, 141.889615, 'ホタテの貝殻が敷き詰められた真っ白な道と青い海のコントラストが美しい', 'seed_auto', 'M9xWlvJPbAk', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a8/Soya_Hills_White_Shell_Road.jpg/960px-Soya_Hills_White_Shell_Road.jpg', 'Yasu (talk) / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('稚内公園', 'viewpoint', 45.419722, 141.666944, '稚内公園（わっかないこうえん）は、北海道稚内市にある公園。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Wakkanai_harbor.JPG/960px-Wakkanai_harbor.JPG', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:宗谷丘陵白い道'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

