  ('金峰神社', 'other', 39.181944, 139.942222, '金峰神社（きんぽうじんじゃ）は、秋田県にかほ市象潟町小滝にある神社である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Kinpou_Shrine%2C_Nikaho.jpg/960px-Kinpou_Shrine%2C_Nikaho.jpg', 'Wikipedia', 'wikipedia'),
  ('奈曽の白滝', 'viewpoint', 39.181444, 139.943250, '奈曽の白滝（なそのしらたき）は、秋田県にかほ市にあり、すぐ近くには金峰神社がある。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/Naso_no_Shirataki.JPG/960px-Naso_no_Shirataki.JPG', 'Wikipedia', 'wikipedia'),
  ('鉾立展望台', 'viewpoint', 39.119900, 139.992472, '日本海と鳥海山の絶景が一望できる展望台', 'seed_auto', 'LtKfc75wt2o', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/Mt._Chokai%2C_19_Oct._2013.jpg/960px-Mt._Chokai%2C_19_Oct._2013.jpg', '8-Forest / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('鳥海山', 'viewpoint', 39.121808, 139.991559, '山頂から日本海が見渡せる景色', 'seed_auto', 'AVb8FvuFJbw', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/Mt._Chokai%2C_19_Oct._2013.jpg/960px-Mt._Chokai%2C_19_Oct._2013.jpg', '8-Forest / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('鳥海山鉾立展望台', 'viewpoint', 39.119900, 139.992472, '鳥海山の山容や日本海を一望できる絶景展望台', 'seed_auto', 'EeOJoC0ycTc', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/Mt._Chokai%2C_19_Oct._2013.jpg/960px-Mt._Chokai%2C_19_Oct._2013.jpg', '8-Forest / CC BY-SA 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:鳥海ブルーライン'
