insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('I3XtOD1W__Q', 'https://www.youtube.com/watch?v=I3XtOD1W__Q', '【日光ツーリング】大型バイク２台と栃木県の絶景を堪能しに行ってきた。でも季節外れの寒さに負けて引き返してきた｜ツーリング｜Ninja｜Kawasaki｜ZX4R｜ZX25R｜いろは坂｜CB750F', 'TAKASHUN【モトブログ】', 92545, ''),
  ('LWdvQfWUUnY', 'https://www.youtube.com/watch?v=LWdvQfWUUnY', '[ 関東編 ] バイクで走る関東地方の首都圏圧巻のツーリングコース20選★人生で一度は走りたい最高の道！#絶景ロード #東京', 'I Am Rider', 23880, ''),
  ('6HfB2IBVyQs', 'https://www.youtube.com/watch?v=6HfB2IBVyQs', '[バイク旅#114]栃木 日光霧降高原バイクツーリング　大笹牧場のジンギスカンはおいしい　雨の霧降高原道路💦', 'イーザイル', 13649, ''),
  ('5yZsEdVTwJU', 'https://www.youtube.com/watch?v=5yZsEdVTwJU', '429Racing　霧降高原ツーリング　パート２ #36', 'えっちゃんねる', 12677, ''),
  ('fXmiJck1eBQ', 'https://www.youtube.com/watch?v=fXmiJck1eBQ', '【YZF‐R1】往復440キロ 日光の紅葉の求めて【ツーリング】', 'RY×バイク旅', 7738, ''),
  ('KOoqbEq95rA', 'https://www.youtube.com/watch?v=KOoqbEq95rA', '【GB350】バイクで初めての高速道路！霧降高原ツーリング編【無職ライダー】', '元公務員もっち', 6333, '04:45'),
  ('ImwbZ4tUaSo', 'https://www.youtube.com/watch?v=ImwbZ4tUaSo', 'モンキー125で日光霧降高原ロングツーリング！平日なのに仕事が無くなった暇人の現実逃避…', 'ゼキザップ_モトブログ', 5374, ''),
  ('jSnPPkVYahU', 'https://www.youtube.com/watch?v=jSnPPkVYahU', '2026年【栃木県】真夏に涼しい道路ベスト5 ・絶景スポット・展望地・道路最高地点も紹介！～気象庁データから8月の平均気温を計算！夏のツーリング、ドライブの参考に！', 'おでかけポコ', 5107, ''),
  ('_y82tLvoBwQ', 'https://www.youtube.com/watch?v=_y82tLvoBwQ', '９月も絶景【日光霧降高原道路】日の出と早朝走行の景色映像 #ツーリングスポット #ドライブスポット #絶景スポット', 'おでかけポコ', 4413, ''),
  ('CqsLhbP-8WA', 'https://www.youtube.com/watch?v=CqsLhbP-8WA', '【ソロツーリング】牧場の間を抜ける最高のロードを走ります【奥日光】WR250X 栃木県', 'Tsuka Walker', 4313, ''),
  ('arCSonZxijU', 'https://www.youtube.com/watch?v=arCSonZxijU', '【真冬の霧降高原】バイクで行けるか！？【六方沢】', 'MotoBikeChannel', 3851, ''),
  ('DoC_MuHoFhs', 'https://www.youtube.com/watch?v=DoC_MuHoFhs', '雪景色絶景【日光霧降高原道路】スタッドレスタイヤのスーパーカブで走る～キスゲ平園地駐車場～六方沢展望台駐車場～六方沢橋～大笹牧場手前までのバイクツーリング走行映像', 'おでかけポコ', 3743, ''),
  ('hy2M2uD9qmQ', 'https://www.youtube.com/watch?v=hy2M2uD9qmQ', '【雪景色の霧降高原へ】スタッドレスタイヤスーパーカブに乗って桐生市→草木湖湖畔みかげ原展望地旧車ミーティングダムサンダーの様子→足尾町→世界遺産日光地区→霧降高原道路を走ってキスゲ平園地までの走行映像', 'おでかけポコ', 3605, ''),
  ('JxNHsfG27_k', 'https://www.youtube.com/watch?v=JxNHsfG27_k', 'モンキー125ならロングツーリングも楽しい♪群馬県～山形県、往復の帰り道は可愛いスポット巡り！あかべこ公園とラッキー公園、夕方の霧降高原', 'ゼキザップ_モトブログ', 2851, ''),
  ('1fAA6RBCBsc', 'https://www.youtube.com/watch?v=1fAA6RBCBsc', '【2022年】首都圏発！圧倒的ゴールデンウィークにおすすめの絶景ツーリングロード５選', '圧倒的バイクチャンネル', 1039, ''),
  ('FeQbYQ91tVo', 'https://www.youtube.com/watch?v=FeQbYQ91tVo', 'いろは坂から奥日光に続く道はだんだん紅葉していくよツーリング', 'Tsuka Walker', 595, ''),
  ('TRjm7ZrkRo8', 'https://www.youtube.com/watch?v=TRjm7ZrkRo8', '【ツーリングプラン】「もはや神コスパ」な3000円日帰りツーリング｜絶景ロードを駆け抜ける！', '​のっとん / バイク旅ch - NoTone Ride Japan', 335, ''),
  ('Kuxh4lmNhpU', 'https://www.youtube.com/watch?v=Kuxh4lmNhpU', '奥利根ゆけむり街道 知らなかったけど最高な道じゃないかツーリング', 'Tsuka Walker', 286, ''),
  ('-SxlyDVWyVs', 'https://www.youtube.com/watch?v=-SxlyDVWyVs', '霧降高原の絶景に感動！大笹牧場で「ライダーの義務」を果たしてきた【GSX250R】', 'くるまん', 129, ''),
  ('5XsJE44yBMg', 'https://www.youtube.com/watch?v=5XsJE44yBMg', 'TabiMoto　VT250SPADA　紅葉の栃木３大ワインディングロード走破 insta360 one R', 'Tabi Moto', 114, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('輪王寺', 'other', 36.754389, 139.601139, '輪王寺（りんのうじ）は、栃木県日光市にある寺院で、天台宗の門跡寺院である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/JP-Nikko-Sanbutsu-do.JPG/960px-JP-Nikko-Sanbutsu-do.JPG', 'Wikipedia', 'wikipedia'),
  ('大笹牧場', 'rest', 36.840987, 139.617204, 'バイクが多く集まる人気スポット', 'seed_auto', '5yZsEdVTwJU', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/Ozasa_Farm_Rest_House.jpg/960px-Ozasa_Farm_Rest_House.jpg', 'Miyuki Meinaka / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('キスゲ平園地', 'viewpoint', 36.807113, 139.592764, '視聴者コメントで景色が素晴らしいと紹介されている地点', 'seed_auto', 'fXmiJck1eBQ', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/%E6%97%A5%E5%85%89%E5%85%AD%E6%96%B9%E6%B2%A2%E3%81%AE%E7%B4%85%E8%91%89_03.jpg/960px-%E6%97%A5%E5%85%89%E5%85%AD%E6%96%B9%E6%B2%A2%E3%81%AE%E7%B4%85%E8%91%89_03.jpg', 'くろふね / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('半月山第2駐車場', 'viewpoint', 36.776684, 139.622755, '中禅寺湖スカイラインにある駐車場。涼しいスポット第3位として紹介', 'seed_auto', 'jSnPPkVYahU', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/Tokorono%2C_Nikko%2C_Tochigi_Prefecture_321-1421%2C_Japan_-_panoramio.jpg/960px-Tokorono%2C_Nikko%2C_Tochigi_Prefecture_321-1421%2C_Japan_-_panoramio.jpg', 'taro gen / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('日光田母沢御用邸記念公園', 'viewpoint', 36.752500, 139.591389, '日光田母沢御用邸記念公園（にっこうたもざわごようていきねんこうえん）は、栃木県日光市にある栃木県立の都市公園（歴史公園）である。', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/b/ba/Tamozawa06.jpg', 'Wikipedia', 'wikipedia'),
  ('霧降高原', 'viewpoint', 36.802778, 139.600000, '霧降高原（きりふりこうげん）は、栃木県日光市市街地北方、日光国立公園の女峰山東山麓に広がる高原である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Kirifuri_Highland_20090719.jpg/960px-Kirifuri_Highland_20090719.jpg', 'Wikipedia', 'wikipedia'),
  ('霧降高原道路 最高地点', 'viewpoint', 36.807000, 139.592792, '真夏に涼しいスポット第5位として紹介', 'seed_auto', 'jSnPPkVYahU', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/%E6%97%A5%E5%85%89%E5%85%AD%E6%96%B9%E6%B2%A2%E3%81%AE%E7%B4%85%E8%91%89_03.jpg/960px-%E6%97%A5%E5%85%89%E5%85%AD%E6%96%B9%E6%B2%A2%E3%81%AE%E7%B4%85%E8%91%89_03.jpg', 'くろふね / CC BY-SA 4.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:霧降高原道路'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('国道249号', '能登半島の絶景海岸線を巡り、千枚田から日本三大パワースポット（金剛崎・青の洞窟）や能登半島最北端の禄剛崎へ向かう爽快なツーリングルート。
