insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('つばき茶屋', 'food', 37.525490, 137.257940, '海を眺めながらイカさま定食やイカ焼きが食べられる人気のお食事処', 'seed_auto', 'ux4goa65FzM', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/R6_noto_earthquake_suzu_noroshi-area_2024-02-16_4.jpg/960px-R6_noto_earthquake_suzu_noroshi-area_2024-02-16_4.jpg', 'Hurohukidaikon / CC BY 4.0 / Wikimedia Commons', 'commons'),
  ('トトロ岩', 'viewpoint', 37.391093, 136.902521, 'トトロのシルエットに見える海岸沿いの奇岩', 'seed_auto', 'ux4goa65FzM', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/City_hall_of_Wajima%2C_Ishikawa%2C_Japan.jpg/960px-City_hall_of_Wajima%2C_Ishikawa%2C_Japan.jpg', 'Yasu (talk) / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('垂水の滝', 'viewpoint', 37.465495, 137.085439, '海岸沿いにある落差のある滝', 'seed_auto', 'fcclOACgefo', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/%E5%9E%82%E6%B0%B4%E3%81%AE%E6%BB%9D_-_panoramio.jpg/960px-%E5%9E%82%E6%B0%B4%E3%81%AE%E6%BB%9D_-_panoramio.jpg', 'Yobito KAYANUMA / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('白米千枚田', 'viewpoint', 37.425542, 136.999507, '日本海に面した美しい棚田で、名物のふぐおにぎりを紹介', 'seed_auto', 'ux4goa65FzM', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/%E7%99%BD%E7%B1%B3%E5%8D%83%E6%9E%9A%E7%94%B0%E4%B8%87%E7%87%88%E3%81%BE%E3%81%A4%E3%82%8A_%28Candle_night_at_Hakumai_Senmaida%29_19_Oct%2C_2013_-_panoramio.jpg/960px-%E7%99%BD%E7%B1%B3%E5%8D%83%E6%9E%9A%E7%94%B0%E4%B8%87%E7%87%88%E3%81%BE%E3%81%A4%E3%82%8A_%28Candle_night_at_Hakumai_Senmaida%29_19_Oct%2C_2013_-_panoramio.jpg', 'Hiroaki Kaneko / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('禄剛崎', 'viewpoint', 37.528894, 137.326462, '能登半島の最北端に位置する岬', 'seed_auto', 'fcclOACgefo', 'https://upload.wikimedia.org/wikipedia/commons/d/d1/%E8%83%BD%E7%99%BB%E5%8D%8A%E5%B3%B6%E3%81%AE%E6%9C%80%E5%8C%97%E7%AB%AF%E3%80%8C%E7%A6%84%E5%89%9B%E5%B4%8E%E7%81%AF%E5%8F%B0%E3%80%8D_-_panoramio.jpg', 'u-ra / CC BY-SA 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'num:国道249号:石川'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('メタセコイア並木', '約500本のメタセコイアが約2.4kmにわたり立ち並ぶ絶景ロード。新緑や紅葉など季節ごとに美しい景観が広がります。
注意: 観光シーズン中の混雑・追突注意 / 観光シーズンは路上駐車・歩行者・渋滞に注意 / 観光シーズンは路上駐車や歩行者に注意 / 観光シーズンの渋滞および路側帯停車禁止注意 / 観光客や撮影者が多いため速度に注意してください。 / 時期により観光客や車で混雑 / 観光シーズンの渋滞や路上駐車に注意が必要です。 / 紅葉シーズンや休日は非常に混雑し、路上駐車厳禁です / 見頃の季節は観光混雑あり / 観光渋滞や撮影目的の歩行者の飛び出しに注意 / 観光シーズンの渋滞および通行人に注意 / 観光客や交通量が多い時期があるため注意 / 紅葉などの観光シーズンは非常に混雑し、渋滞が発生します。路上駐車は禁止されているためマキノピックランドなどの駐車場を利用してください。 / 観光シーズンは渋滞や歩行者の飛び出しに注意 / 観光客や歩行者の飛び出し、路上駐車に注意 / 観光シーズンは路上駐車厳禁・徐行遵守 / 観光客の横断に注意
（動画 19 本から自動抽出。位置は地図経路による推定）', '滋賀県', 'マキノピックランド', 'マキノ高原', 'SRID=4326;LINESTRING(136.036270 35.471270, 136.037370 35.484410, 136.037290 35.490580, 136.037490 35.491330, 136.036920 35.493660, 136.036040 35.495150, 136.035340 35.495680, 136.034050 35.495840, 136.034000 35.496170)', 2938, 0.09, true, 'https://www.youtube.com/watch?v=FMbNolbcyDk', 'すっすのもとぶろぐ', 'seed_auto', 'routed', 'name:メタセコイア並木', 5.00, 1.00, 4.26, 3.68, 3.79, 19)
  on conflict (seed_key) do update set description = excluded.description, hint_scenery = excluded.hint_scenery, hint_winding = excluded.hint_winding, hint_surface = excluded.hint_surface, hint_rest = excluded.hint_rest, hint_parking = excluded.hint_parking, mention_count = excluded.mention_count, geom = excluded.geom, length_m = excluded.length_m, curviness = excluded.curviness, updated_at = now()
  returning id)
