insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('北牧野古墳群', 'other', 35.492750, 136.038139, '北牧野古墳群（きたまきのこふんぐん）は滋賀県高島市マキノ町牧野にある古墳時代後期の古墳群である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/%28%E6%BB%8B%E8%B3%80%E7%9C%8C%29_%E3%83%A1%E3%82%BF%E3%82%BB%E3%82%B3%E3%82%A4%E3%83%A4%E4%B8%A6%E6%9C%A8%E3%80%82%E3%81%A1%E3%82%87%E3%81%A3%E3%81%A8%E8%A1%8C%E3%81%91%E3%81%B0%E7%A6%8F%E4%BA%95%E7%9C%8C%E3%80%82_-_panoramio.jpg/960px-%28%E6%BB%8B%E8%B3%80%E7%9C%8C%29_%E3%83%A1%E3%82%BF%E3%82%BB%E3%82%B3%E3%82%A4%E3%83%A4%E4%B8%A6%E6%9C%A8%E3%80%82%E3%81%A1%E3%82%87%E3%81%A3%E3%81%A8%E8%A1%8C%E3%81%91%E3%81%B0%E7%A6%8F%E4%BA%95%E7%9C%8C%E3%80%82_-_panoramio.jpg', 'Shift / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('北牧野製鉄遺跡', 'other', 35.487222, 136.036389, '北牧野製鉄遺跡（きたまきのせいてついせき）は滋賀県高島市マキノ町牧野にある製鉄遺跡である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/%E3%83%A1%E3%82%BF%E3%82%BB%E3%82%B3%E3%82%A4%E3%83%A4%E5%A4%8F1_-_panoramio.jpg/960px-%E3%83%A1%E3%82%BF%E3%82%BB%E3%82%B3%E3%82%A4%E3%83%A4%E5%A4%8F1_-_panoramio.jpg', 'baggio4ever / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('日置前遺跡', 'other', 35.487222, 136.036389, '日置前遺跡（ひおきまえいせき）は滋賀県高島市今津町日置前にある複合遺跡である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/%E3%83%A1%E3%82%BF%E3%82%BB%E3%82%B3%E3%82%A4%E3%83%A4%E5%A4%8F1_-_panoramio.jpg/960px-%E3%83%A1%E3%82%BF%E3%82%BB%E3%82%B3%E3%82%A4%E3%83%A4%E5%A4%8F1_-_panoramio.jpg', 'baggio4ever / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('マキノピックランド', 'rest', 35.471231, 136.036982, 'ジェラートやカフェが楽しめる立ち寄りスポット', 'seed_auto', 'Ak4s_UJdkqI', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Makino_20211204142730_%2851817308587%29.jpg/960px-Makino_20211204142730_%2851817308587%29.jpg', 'inunami / CC BY 2.0 / Wikimedia Commons', 'commons'),
  ('メタセコイア並木', 'viewpoint', 35.487470, 136.037233, '四季折々の景色が楽しめる絶景並木道', 'seed_auto', 'T4z4gy-8cro', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/%E3%83%A1%E3%82%BF%E3%82%BB%E3%82%B3%E3%82%A4%E3%83%A4%E5%A4%8F1_-_panoramio.jpg/960px-%E3%83%A1%E3%82%BF%E3%82%BB%E3%82%B3%E3%82%A4%E3%83%A4%E5%A4%8F1_-_panoramio.jpg', 'baggio4ever / CC BY 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:メタセコイア並木'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

