insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('qoOlu_DUcqo', 'https://www.youtube.com/watch?v=qoOlu_DUcqo', '予算5万円!! 東京▶︎本州最北端 250CCで行く!!東日本1周ツーリング【総集編】', 'しょうたろうモトブログ -Shotaro_Motovlog-', 301703, '15:40'),
  ('7TeQJyAgBvE', 'https://www.youtube.com/watch?v=7TeQJyAgBvE', '【北海道ツーリング】6日間1100キロのバイク旅！絶景×グルメ×旅人との出会いに大感動', 'Ori and Kaito', 195710, '19:12'),
  ('AWXP1KTNijk', 'https://www.youtube.com/watch?v=AWXP1KTNijk', '【絶景】北海道ツーリングのおすすめルートベスト10', 'MotoCamp【モトキャンプ】', 133636, ''),
  ('opaArABbrXM', 'https://www.youtube.com/watch?v=opaArABbrXM', '関東圏のお薦めツーリングロード15選+(ツーリングマップルのレビュー)', 'ヤマハ乗りのホンダ好きの鈴菌', 131698, '08:55'),
  ('_CngvLboTZc', 'https://www.youtube.com/watch?v=_CngvLboTZc', '北海道ツーリング 感動した道 BEST20 [旧版]', 'パナイモン [Rebel1100]', 115233, '02:30'),
  ('ifQUzO4toSs', 'https://www.youtube.com/watch?v=ifQUzO4toSs', '北海道ツーリング【 絶景道5選 】PART1  Superb view road in Hokkaido, Japan', 'はぐれた', 106476, ''),
  ('uY1WtaSEI8w', 'https://www.youtube.com/watch?v=uY1WtaSEI8w', '北海道ツーリング 感動した道 BEST30+20 [最新版]', 'パナイモン [Rebel1100]', 64278, '14:24'),
  ('DkHglqoATSY', 'https://www.youtube.com/watch?v=DkHglqoATSY', '【北海道ツーリング2025 #4】北見→帯広→旭川  北海道はすべての道がツーリングロード！あと帯広の豚丼！【ジクサー150】 (Day 6)', 'み山の雑記帳', 19971, '52:02'),
  ('gkihzDnls50', 'https://www.youtube.com/watch?v=gkihzDnls50', '【関東勢必見】一度は走りたい超絶景ツーリングコース紹介！フォルツァ250MF15バイクスクーター', 'チャンネルもーりんぐ', 16759, '15:30'),
  ('dp-69O_v7TI', 'https://www.youtube.com/watch?v=dp-69O_v7TI', '【北海道ツーリング2021】６日目 北見→十勝【YZF‐R1】', 'RY×バイク旅', 7493, ''),
  ('HXvPb2gF8dg', 'https://www.youtube.com/watch?v=HXvPb2gF8dg', 'もう一度走りたい！北海道の絶景道10選　他に選外の道も６本ほど紹介しています。独断と偏見に満ちたチョイスなのです(笑)', 'ジンベエ親分のツーリング記', 6149, '06:17'),
  ('7XOlpV0s5H8', 'https://www.youtube.com/watch?v=7XOlpV0s5H8', '【完結】北海道ツーリング ⓺後編　三国峠の絶景！【KTM690ENDURO R】', 'Moto猫ちゃんねる', 3813, '03:07'),
  ('ZouKfB9koZM', 'https://www.youtube.com/watch?v=ZouKfB9koZM', '【北海道ツーリング2020】美幌峠と摩周湖の絶景ワイディング天国 with R1200GS & G310R', 'さすライダーチャンネル', 3336, ''),
  ('3nMKHVPyLOc', 'https://www.youtube.com/watch?v=3nMKHVPyLOc', '【絶景:美幌峠·三国峠·ナイタイ高原牧場】北海道ツーリング2024·夏/中編　道内3泊4日で最北端～道央を回るルート', '【ゆっくりバイクで一人旅】Nanjack Motorcycle', 1705, '12:03'),
  ('GLjavEHgzEk', 'https://www.youtube.com/watch?v=GLjavEHgzEk', '【山梨県】三国峠→山中湖ツーリング(まさかこんな絶景があったとは！)', '平日ライダー', 1574, ''),
  ('6haO541Jt8I', 'https://www.youtube.com/watch?v=6haO541Jt8I', '北海道キャンプツーリング 2019 #13（後編）道内で一番高い峠！三国峠｜KAWASAKI Ninja1000', 'akichannel', 992, ''),
  ('bTjrxoMUSgo', 'https://www.youtube.com/watch?v=bTjrxoMUSgo', 'GB350 北海道ツーリング2022 #3「タウシュベツ川橋梁」(絶景ツーリングVol.63)', 'ZKライダー', 592, ''),
  ('JKAAzf1n-Z8', 'https://www.youtube.com/watch?v=JKAAzf1n-Z8', '#5  2020北海道ツーリング、 一泊ツーリング、北海道の絶景、三国峠＆タウシュベツ川橋梁、No3三国峠を走る編、GSX‐S１０００', 'AKIRA Motovlog Channel', 417, ''),
  ('xON24ps6D0Y', 'https://www.youtube.com/watch?v=xON24ps6D0Y', 'GB350 北海道ツーリング2022 #4「三国峠／流星の滝」(絶景ツーリングVol.64)', 'ZKライダー', 200, '')
