insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('2tdeDHwPmmc', 'https://www.youtube.com/watch?v=2tdeDHwPmmc', '昼までに帰る！道志道・山中湖・奥多摩周遊道路。日帰り300kmツーリング[Kawasaki W800 Street]', 'gaso', 397901, '18:26'),
  ('PuZ2GR3uwF4', 'https://www.youtube.com/watch?v=PuZ2GR3uwF4', '昼の12時までに300km走って帰るツーリング【道志道・山中湖・奥多摩】', 'しょうたろうモトブログ -Shotaro_Motovlog-', 80478, ''),
  ('Gwq90MhufJM', 'https://www.youtube.com/watch?v=Gwq90MhufJM', '【乗り換えて良かった？】S1000RRを納車して450Km走ったリアルな感想をお話します。　ファーストインプレッション/レビュー【 S1000RR / モトブログ 】', 'ESPRESSO RIDER / エスプレッソライダー ', 63002, ''),
  ('yk35t9WzC4I', 'https://www.youtube.com/watch?v=yk35t9WzC4I', '奥多摩から道志みちへのコースがすごく良かったツーリング | SV650', 'STOMP', 39716, '15:14'),
  ('LWdvQfWUUnY', 'https://www.youtube.com/watch?v=LWdvQfWUUnY', '[ 関東編 ] バイクで走る関東地方の首都圏圧巻のツーリングコース20選★人生で一度は走りたい最高の道！#絶景ロード #東京', 'I Am Rider', 23880, ''),
  ('J1pNYfLoe0U', 'https://www.youtube.com/watch?v=J1pNYfLoe0U', '【徹底比較】バイク撮影に最強なのはどっち？ Insta360 X5 vs DJI OSMO 360【実走レビュー】', 'ESPRESSO RIDER / エスプレッソライダー ', 20897, '04:51'),
  ('0Kb8oFsGISk', 'https://www.youtube.com/watch?v=0Kb8oFsGISk', '【関東・甲信越 絶景ドライブ】一度は走りたい絶景ロード18選｜富士山・箱根・ビーナスライン・房総', 'Holiday Ideas', 10619, '02:56'),
  ('JttL3z8dJaQ', 'https://www.youtube.com/watch?v=JttL3z8dJaQ', 'バイクで安心して峠を走るうえでの"必殺技"【GSX-R1000R】', 'ITKライダー', 8672, ''),
  ('KItXkRy6brI', 'https://www.youtube.com/watch?v=KItXkRy6brI', '秋の奥多摩周遊道路を日帰りツーリング【ハーレー ファットボーイ】', 'イチロクのハーレーちゃんねる', 7590, '02:55'),
  ('1rdESv_wpdg', 'https://www.youtube.com/watch?v=1rdESv_wpdg', '涼を求めて奥多摩にツーリング   l  BMW C400GT', 'Oji〜', 3933, ''),
  ('BliAs52vDBQ', 'https://www.youtube.com/watch?v=BliAs52vDBQ', 'WR250Xのチューブレス化とα-14とハイシートのインプレ', 'Tsuka Walker', 3724, ''),
  ('LWH1LT2zK9I', 'https://www.youtube.com/watch?v=LWH1LT2zK9I', 'その追い越し危険ですよ【正面衝突寸前！？】奥多摩周遊道路でぶち抜かれました！アフリカツイン 奥多摩事故＃旅好きライダーチャンネル＃アフリカツイン＃奥多摩事故＃奥多摩周遊道路＃道の駅巡り＃鹿カレー', '旅好きライダーチャンネル', 2565, ''),
  ('0fZ_D6YLQho', 'https://www.youtube.com/watch?v=0fZ_D6YLQho', 'ジェネリッククシタニで行く奥多摩ソロツーリング【WR250X】バイク', 'Tsuka Walker', 2343, ''),
  ('OMObZ5aU57g', 'https://www.youtube.com/watch?v=OMObZ5aU57g', '【東京ツーリング】大ピンチ！悪天候の奥多摩周遊道路で大変な目に遭いました【モトブログ/Z900RS】【奥多摩周遊道路】', 'やさおバイクダイアリー【モトブログ】', 2339, ''),
  ('7OJb0nR0xq4', 'https://www.youtube.com/watch?v=7OJb0nR0xq4', '奥多摩周辺 峠道 #2  奥多摩周遊道路【F900R BMW MOTORRAD】', 'HIDEMARU RIDER', 1842, ''),
  ('-2UI2euclCI', 'https://www.youtube.com/watch?v=-2UI2euclCI', '奥多摩周遊道路 & 大菩薩ライン - 2019 冬 山梨・東京バイクツーリング【WR250X】', 'Tsuka Walker', 1464, ''),
  ('17prJevwiZg', 'https://www.youtube.com/watch?v=17prJevwiZg', '【奥多摩周遊道路　秩父  道志みち  】事故にも遭遇　シリーズ4話  アフリカツインで関東周回ツーリング＃アフリカツイン＃ツーリング＃アフリカツインツーリング＃関東周回＃秩父＃道志みち＃奥多摩周遊道路', '旅好きライダーチャンネル', 841, ''),
  ('5H8tx8x-SS0', 'https://www.youtube.com/watch?v=5H8tx8x-SS0', '山梨 道の駅巡り このエリアが面白い グルメ おすすめポイントを紹介 アフリカツイン＃旅好きライダーチャンネル＃道の駅＃道の駅たばやま＃道の駅こすげ＃道の駅つる＃道の駅甲斐大和＃グルメ＃山梨', '旅好きライダーチャンネル', 495, '')
) as v(video_id, url, title, channel, view_count, ts)
