insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('数馬温泉', 'onsen', 35.727944, 139.044333, '数馬温泉（かずまおんせん）は東京都西多摩郡檜原村数馬にある温泉である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Kazuma_hotspring.jpg/960px-Kazuma_hotspring.jpg', 'Wikipedia', 'wikipedia'),
  ('蛇の湯温泉', 'onsen', 35.726000, 139.049750, '蛇の湯温泉（じゃのゆおんせん）は東京都西多摩郡檜原村数馬にある温泉である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/%E6%95%B0%E9%A6%AC%E3%81%AE%E6%B9%AF_-_panoramio.jpg/960px-%E6%95%B0%E9%A6%AC%E3%81%AE%E6%B9%AF_-_panoramio.jpg', 'KOJI MISUMI / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('鶴の湯温泉', 'onsen', 35.783333, 139.045278, '鶴の湯温泉（つるのゆおんせん）は、東京都西多摩郡奥多摩町（旧国:武蔵国）にある温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/%E9%B6%B4%E3%81%AE%E6%B9%AF%E6%B8%A9%E6%B3%89.jpg/960px-%E9%B6%B4%E3%81%AE%E6%B9%AF%E6%B8%A9%E6%B3%89.jpg', 'Wikipedia', 'wikipedia'),
  ('小河内神社', 'other', 35.776722, 139.020750, '小河内神社（おごうちじんじゃ）は、東京都西多摩郡奥多摩町河内（こうち）にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/36/Ogochi-jinja_202508-2.jpg/960px-Ogochi-jinja_202508-2.jpg', 'Wikipedia', 'wikipedia'),
  ('風張峠', 'pass', 35.747227, 139.041752, '東京都の道路最高地点', 'seed_auto', 'JttL3z8dJaQ', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/%E5%A5%A5%E5%A4%9A%E6%91%A9%E5%91%A8%E9%81%8A%E9%81%93%E8%B7%AF%E3%81%AE%E5%B1%B1%E9%A0%82%E4%BB%98%E8%BF%91_-_panoramio.jpg/960px-%E5%A5%A5%E5%A4%9A%E6%91%A9%E5%91%A8%E9%81%8A%E9%81%93%E8%B7%AF%E3%81%AE%E5%B1%B1%E9%A0%82%E4%BB%98%E8%BF%91_-_panoramio.jpg', 'KOJI MISUMI / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('奥多摩湖', 'viewpoint', 35.777400, 139.011400, '奥多摩湖（おくたまこ）は、東京都西多摩郡奥多摩町と山梨県北都留郡丹波山村・小菅村に跨る人造湖。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Ogouchi_damu.JPG/960px-Ogouchi_damu.JPG', 'Wikipedia', 'wikipedia'),
  ('小河内ダム', 'viewpoint', 35.789640, 139.051035, '奥多摩湖にあるおすすめスポットとしてコメントで言及', 'seed_auto', 'yk35t9WzC4I', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/%E5%B0%8F%E6%B2%B3%E5%86%85%E3%83%80%E3%83%A0%E3%80%81%E6%AD%A3%E9%9D%A2%E3%81%8C%E8%A6%8B%E3%81%88%E3%82%8B%E4%B8%98%E3%82%88%E3%82%8A%E3%80%82_-_panoramio.jpg/960px-%E5%B0%8F%E6%B2%B3%E5%86%85%E3%83%80%E3%83%A0%E3%80%81%E6%AD%A3%E9%9D%A2%E3%81%8C%E8%A6%8B%E3%81%88%E3%82%8B%E4%B8%98%E3%82%88%E3%82%8A%E3%80%82_-_panoramio.jpg', 'chanow1050 / CC BY 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:奥多摩周遊道路'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('アネスト岩田 ターンパイク箱根', '小田原から大観山にかけて広がる絶景の有料ドライブコース。走りやすい中高速コーナーが続く人気のツーリングスポット。
