insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('XMaMVM2lalA', 'https://www.youtube.com/watch?v=XMaMVM2lalA', '【ZX-25R】人生初のスポーツ系バイクに四苦八苦です｜30代 女の休日バイク Vlog', 'しーまん  | seaman bike & life vlog', 188497, '08:38'),
  ('gT9T-XdEgww', 'https://www.youtube.com/watch?v=gT9T-XdEgww', 'ターンパイクで行く箱根の旅｜30代女子の休日バイク Vlog', 'しーまん  | seaman bike & life vlog', 137872, '02:12'),
  ('ChZJIkLHIes', 'https://www.youtube.com/watch?v=ChZJIkLHIes', '【中国地方ツーリング#10 final】予算5万円!!GBで行く!!下道のみで中国地方1周ツーリング【広島▶︎東京】', 'しょうたろうモトブログ -Shotaro_Motovlog-', 47766, '20:03'),
  ('AeB5QZWU48I', 'https://www.youtube.com/watch?v=AeB5QZWU48I', '【神奈川】絶対行った方が良い！絶景&絶品ツーリングスポット4選', '平日ライダー', 23381, ''),
  ('NKqkYuNHmYs', 'https://www.youtube.com/watch?v=NKqkYuNHmYs', 'ハーレーで早朝から箱根を巡るツーリング/ターンパイク/バイク', 'イチロクのハーレーちゃんねる', 17848, '02:48'),
  ('ir8aRagMjD0', 'https://www.youtube.com/watch?v=ir8aRagMjD0', '【伊豆ツーリング】ターンパイク箱根と伊豆のスカイライン2つを走り抜ける贅沢な1日｜伊豆半島｜伊豆スカイライン｜ツーリング｜Ninja｜Kawasaki｜ZX4R｜ZX25R｜バイク｜SCproject', 'TAKASHUN【モトブログ】', 16217, '01:58'),
  ('0Kb8oFsGISk', 'https://www.youtube.com/watch?v=0Kb8oFsGISk', '【関東・甲信越 絶景ドライブ】一度は走りたい絶景ロード18選｜富士山・箱根・ビーナスライン・房総', 'Holiday Ideas', 10619, '00:11'),
  ('Ai29HwuViXo', 'https://www.youtube.com/watch?v=Ai29HwuViXo', 'オープンカーの楽しさを湘南・箱根で確認…ロードスターRFが最高すぎた！？でも、、【走行インプレッション】 今日もまた、「人馬一体」', 'SHU MOTOR VLOG', 10020, ''),
  ('5DtDEHzwzk8', 'https://www.youtube.com/watch?v=5DtDEHzwzk8', '遅刻から始まるツーリングはずっと笑いっぱなし【GSX-R1000R】', 'ITKライダー', 5143, ''),
  ('2Dt7dq4S_zk', 'https://www.youtube.com/watch?v=2Dt7dq4S_zk', '超気持ちイイ！！箱根の３大快走路【GSX-R1000R】', 'ITKライダー', 2756, ''),
  ('vdi1a9g_KUg', 'https://www.youtube.com/watch?v=vdi1a9g_KUg', '人生初の伊豆ツーリングで、富士山と絶景ワインディングに完全にやられました。', 'モトラボ104', 2379, ''),
  ('IjhmIc2XFgw', 'https://www.youtube.com/watch?v=IjhmIc2XFgw', '【神奈川県】絶景の箱根ツーリング(箱根ターンパイク、芦ノ湖スカイライン、箱根スカイライン)で観光客の撮影スポットになりました！', '平日ライダー', 1091, ''),
  ('i9nw_omDeOQ', 'https://www.youtube.com/watch?v=i9nw_omDeOQ', 'NO78　CB1100と行く絶景ツーリング　箱根はやっぱり関東有数のツーリングスポットだった（リターンライダーＧのやっぱりバイクサイコー）', 'リターンライダーＧ', 1089, ''),
  ('1fAA6RBCBsc', 'https://www.youtube.com/watch?v=1fAA6RBCBsc', '【2022年】首都圏発！圧倒的ゴールデンウィークにおすすめの絶景ツーリングロード５選', '圧倒的バイクチャンネル', 1039, ''),
  ('0StnImJ0rEo', 'https://www.youtube.com/watch?v=0StnImJ0rEo', '【アネスト岩田ターンパイク箱根、芦ノ湖スカイライン、箱根スカイライン、富士山５号目】定額料金で乗り降り自由のツーリングプラン使用『Vol.52』', 'ケアライダーのケーちゃんねる《Cafe Bike Rider''21》', 967, ''),
  ('Ct5_Io2cwqw', 'https://www.youtube.com/watch?v=Ct5_Io2cwqw', '峠道＜伊豆ツーリング#1＞伊豆スカイライン【F900R BMW MOTORRAD】', 'HIDEMARU RIDER', 875, ''),
  ('7HDmXiJTPDQ', 'https://www.youtube.com/watch?v=7HDmXiJTPDQ', '峠道＜伊豆ツーリング#8 完結編＞伊豆半島から箱根へ｜やっぱり締めはターンパイク箱根で下る！【F900R BMW MOTORRAD】', 'HIDEMARU RIDER', 479, ''),
  ('BwLQdLjQVv4', 'https://www.youtube.com/watch?v=BwLQdLjQVv4', 'こんなパンみたことない！ビジュアルがまるでたまご！濃厚なカスタードクリームがたっぷりのたまごやベーカリーのきみのクリームパン', 'LitRider - ツーリングスポット紹介 - ', 220, '')
