insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('道の駅 ななもり清見', 'rest', 36.133747, 137.166938, '視聴者のお気に入りルート上にある道の駅', 'seed_auto', 'UGJWG_i0_Qo', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Lamborghini_Countach_5000_quattrovalvole_%2825051111490%29.jpg/960px-Lamborghini_Countach_5000_quattrovalvole_%2825051111490%29.jpg', '先従隗始 / CC0 / Wikimedia Commons', 'commons'),
  ('道の駅 パスカル清見', 'rest', 35.940561, 137.082728, '視聴者のお気に入りルート上にある道の駅', 'seed_auto', 'UGJWG_i0_Qo', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/%E3%83%91%E3%82%B9%E3%82%AB%E3%83%AB%E6%B8%85%E8%A6%8B_-_panoramio.jpg/960px-%E3%83%91%E3%82%B9%E3%82%AB%E3%83%AB%E6%B8%85%E8%A6%8B_-_panoramio.jpg', 'Mamusi Taka / CC BY-SA 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:せせらぎ街道'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('高野龍神スカイライン', '高野山から龍神温泉へと至る関西屈指の標高を走るワインディングロード。稜線沿いの絶景と連続するコーナーを楽しめる本格的なツーリングルート。
注意: 冬季凍結注意、スピードが出やすいワインディング / 二輪車速度超過・事故注意、冬季凍結注意 / 冬季チェーン規制や二輪車の事故に注意 / 冬季（12月中旬〜3月下旬）は二輪通行止めや終日片側交互・チェーン規制などの冬季規制あり。週末はスピードを出すバイク・車が多く事故に注意。一部路面の荒れあり。 / スピードを出すバイクや暴走車両が多く注意が必要。警察の取り締まり（ネズミ捕り）あり。冬季は通行規制あり。 / 冬季チェーン規制・夜間通行止めあり / 二輪車の事故多発区間。冬季はチェーン規制や通行止めあり。 / 冬季通行止め、早朝のスピード過剰車、落ち葉や砂利に注意 / 冬季通行規制（夜間通行止め・二輪通行禁止等）あり。落下物や路面の凹凸、逆バンクのコーナーに注意。 / 冬季夜間通行止め・チェーン規制あり。ブラインドコーナーが多く、早朝の飛ばすバイクや路面の砂利・落ち葉に注意。 / 冬季閉鎖、夜間通行規制あり / 冬季チェーン規制・通行止めあり。二輪事故多発区間。 / 二輪車の単独事故が多く速度取締りや凍結注意 / 冬季チェーン規制・二輪通行止め期間あり。中津川集落への分岐後は落石や路面の苔に注意 / 12月中旬から3月下旬まで二輪車冬季通行止め・夜間凍結注意
