insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('大海', 'food', 31.671057, 131.450459, '伊勢海老のランチ', 'seed_auto', 'Kt93os6MHk8', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/Chiotaikai.JPG/960px-Chiotaikai.JPG?utm_source=ja.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia', 'wikipedia'),
  ('鵜戸神宮', 'other', 31.650448, 131.466691, '断崖の洞窟内にある神社で運玉投げを体験', 'seed_auto', 'Kt93os6MHk8', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Udo_jingu_shrine_%2C_%E9%B5%9C%E6%88%B8%E7%A5%9E%E5%AE%AE_-_panoramio_-_z_tanuki_%2816%29.jpg/960px-Udo_jingu_shrine_%2C_%E9%B5%9C%E6%88%B8%E7%A5%9E%E5%AE%AE_-_panoramio_-_z_tanuki_%2816%29.jpg', 'z tanuki / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('堀切峠', 'pass', 31.776450, 131.482307, '太平洋を見下ろす絶景スポットで記念撮影', 'seed_auto', 'Kt93os6MHk8', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/Horokiri_touge_%2C_%E5%A0%80%E5%88%87%E5%B3%A0_-_panoramio.jpg/960px-Horokiri_touge_%2C_%E5%A0%80%E5%88%87%E5%B3%A0_-_panoramio.jpg', 'z tanuki / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('青島', 'viewpoint', 31.803212, 131.467521, '日南海岸沿いにある定番の観光スポット', 'seed_auto', 'XTWFb2j01RA', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Ao-shima_%2C_%E9%9D%92%E5%B3%B6_-_panoramio_%286%29.jpg/960px-Ao-shima_%2C_%E9%9D%92%E5%B3%B6_-_panoramio_%286%29.jpg', 'z tanuki / CC BY 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:日南フェニックスロード'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('国道163号', '京都府木津川市から三重県伊賀市へ木津川沿いを東西に抜ける快走ルート。沿線には和束の茶畑やダム、温泉などの観光スポットが点在します。
