insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('京都府立山城郷土資料館', 'other', 34.752222, 135.833889, '京都府立山城郷土資料館（きょうとふりつやましろきょうどしりょうかん）とは、京都府木津川市にある郷土資料館。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/Kyoto_Prefectural_Yamashiro_Regional_Museum_exterior_view.jpg/960px-Kyoto_Prefectural_Yamashiro_Regional_Museum_exterior_view.jpg', 'Wikipedia', 'wikipedia'),
  ('六所神社', 'other', 34.761639, 136.026694, '六所神社（ろくしょじんじゃ）は京都府相楽郡南山城村北大河原にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Rokusyo_minamiyamashiro_mura3.jpg/960px-Rokusyo_minamiyamashiro_mura3.jpg', 'Wikipedia', 'wikipedia'),
  ('岡田鴨神社', 'other', 34.761611, 135.876389, '岡田鴨神社（おかだかもじんじゃ）は、京都府木津川市加茂町北にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c0/Okada-Kamo-jinja%2C_honden.jpg/960px-Okada-Kamo-jinja%2C_honden.jpg', 'Wikipedia', 'wikipedia'),
  ('正法寺', 'other', 34.792639, 135.902917, '正法寺（しょうほうじ）は、京都府相楽郡和束町にある臨済宗永源寺派の寺。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Sikyakumon.jpg/960px-Sikyakumon.jpg', 'Wikipedia', 'wikipedia'),
  ('法明寺', 'other', 34.767444, 135.959444, '法明寺（ほうみょうじ）は、京都府相楽郡笠置町上有市字西畷（にしなわて）にある真言宗豊山派の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Homyo-ji_Yakushido%2C_Kasagi.jpg/960px-Homyo-ji_Yakushido%2C_Kasagi.jpg', 'Wikipedia', 'wikipedia'),
  ('道の駅お茶の京都みなみやましろ村', 'rest', 34.765190, 136.024310, '道の駅お茶の京都みなみやましろ村（みちのえき おちゃのきょうと みなみやましろむら）は、京都府相楽郡南山城村北大河原にある国道163号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/R163-2020-175.jpg/960px-R163-2020-175.jpg', 'Wikipedia', 'wikipedia'),
  ('道の駅みなみやましろ村', 'rest', 34.765271, 136.024555, '抹茶ソフトクリームを食べに立ち寄った', 'seed_auto', 'qoXFUvP6ubc', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/R163-2020-175.jpg/960px-R163-2020-175.jpg', 'Puchi-masashi / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('道の駅茶処 和束', 'rest', 34.795190, 135.900750, '道の駅茶処 和束（みちのえき ちゃどころ わづか）は、京都府相楽郡和束町に存在した道の駅。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/66/Butsuden.jpg/960px-Butsuden.jpg', 'Barsaka2 / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('泉大橋', 'viewpoint', 34.743417, 135.821611, '泉大橋（いずみおおはし）は、京都府木津川市の国道24号兼国道163号（京都府道・滋賀県道5号木津信楽線重複区間）上にある木津川に架かる橋であり、日本百名橋に選ばれている。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/Izumi-ohashi1.JPG/960px-Izumi-ohashi1.JPG', 'Wikipedia', 'wikipedia'),
  ('高山ダム', 'viewpoint', 34.753708, 136.013441, '復路で経由', 'seed_auto', 'qoXFUvP6ubc', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Takayama-1405-r1.jpg/960px-Takayama-1405-r1.jpg?utm_source=ja.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'num:国道163号:京'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

