select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('ZbTU6xNYyx4', 'https://www.youtube.com/watch?v=ZbTU6xNYyx4', '【GSX-S125】愛知県でバイク初心者にもオススメなツーリングコースを実際に走りながらご紹介！！県外ライダーやベテランにも当然オススメ！！【ゆっくり実況】', 'まぐろゆっけ-motovlog-', 58259, '08:55'),
  ('-z3K29uWREw', 'https://www.youtube.com/watch?v=-z3K29uWREw', '納車されたCB1000Fで奥三河をツーリング | CB1000F', 'STOMP', 28801, ''),
  ('3nvjMYxhraE', 'https://www.youtube.com/watch?v=3nvjMYxhraE', '【SV650】納車！ 夏の早朝ツーリング', 'STOMP', 22810, '19:23'),
