  ('道の駅 もっくる新城', 'rest', 34.917893, 137.533878, 'コメントでルート上の地点として言及', 'seed_auto', '-z3K29uWREw', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/%E6%84%9B%E7%9F%A5%E7%9C%8C%E6%96%B0%E5%9F%8E%E5%B8%82%E5%85%AB%E6%9D%9F%E7%A9%82_%E9%81%93%E3%81%AE%E9%A7%85%E3%82%82%E3%81%A3%E3%81%8F%E3%82%8B%E6%96%B0%E5%9F%8E_%E7%9F%B3%E7%84%BC%E3%81%8D%E3%83%95%E3%83%A9%E3%83%B3%E3%82%AF_20240921_1410.jpg/960px-%E6%84%9B%E7%9F%A5%E7%9C%8C%E6%96%B0%E5%9F%8E%E5%B8%82%E5%85%AB%E6%9D%9F%E7%A9%82_%E9%81%93%E3%81%AE%E9%A7%85%E3%82%82%E3%81%A3%E3%81%8F%E3%82%8B%E6%96%B0%E5%9F%8E_%E7%9F%B3%E7%84%BC%E3%81%8D%E3%83%95%E3%83%A9%E3%83%B3%E3%82%AF_20240921_1410.jpg', '円周率３パーセント / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('道の駅したら', 'rest', 35.064190, 137.549190, '道の駅したら（みちのえき したら）は、愛知県北設楽郡設楽町清崎字中田にある国道257号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/83/Michinoeki_Shitara.jpg/960px-Michinoeki_Shitara.jpg', 'Wikipedia', 'wikipedia'),
  ('道の駅もっくる新城', 'rest', 34.918140, 137.534060, '道の駅もっくる新城（みちのえき もっくるしんしろ）は、愛知県新城市八束穂字五反田にある国道151号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Michinoeki-Mokkuru-Shinsiro-1.jpg/960px-Michinoeki-Mokkuru-Shinsiro-1.jpg', 'Wikipedia', 'wikipedia'),
  ('オシドリの里', 'viewpoint', 35.049174, 137.539079, '冬の設楽でオシドリを観察できるスポット', 'seed_auto', 'Xx0_FlpXGkY', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Old_Bridge2_-_panoramio.jpg/960px-Old_Bridge2_-_panoramio.jpg', 'ESU / CC BY 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'num:国道257号:愛知'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('天に続く道', 'まっすぐ伸びる直線道路が地平線の先まで続き、まるで天へと登っていくかのような大迫力の北海道らしい絶景ルートです。
