insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('横谷温泉', 'onsen', 36.036400, 138.275800, '横谷温泉（よこやおんせん）は、長野県茅野市北山にある温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Kirifuri_Falls_%28Nagano%29.jpg/960px-Kirifuri_Falls_%28Nagano%29.jpg', 'photo: Qurren (talk) Taken with Canon IXY 10S (Digital IXUS 210) / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('八ヶ岳総合博物館', 'other', 36.005889, 138.179139, '八ヶ岳総合博物館（やつがたけそうごうはくぶつかん）は、長野県茅野市にある博物館である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Chino_City_Yatsugatake_Museum_1.jpg/960px-Chino_City_Yatsugatake_Museum_1.jpg', 'Wikipedia', 'wikipedia'),
  ('麦草峠', 'pass', 36.059150, 138.346447, '日本の国道最高地点第2位（標高2,127m）の峠', 'seed_auto', 'BR3Rp47rBGc', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/%E9%BA%A6%E8%8D%89%E5%B3%A0_-_panoramio_%284%29.jpg/960px-%E9%BA%A6%E8%8D%89%E5%B3%A0_-_panoramio_%284%29.jpg', 'alonfloc / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('木戸番頭', 'rest', 35.994990, 138.157659, 'メルヘン街道沿いにあるおすすめの立ち寄りスポット', 'seed_auto', 'icqXcnXub-s', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Nagano_Bank_Chino_Branch.jpg/960px-Nagano_Bank_Chino_Branch.jpg', 'Suikotei / CC BY 4.0 / Wikimedia Commons', 'commons'),
  ('御射鹿池', 'viewpoint', 36.033056, 138.291389, '御射鹿池（みしゃかいけ）は、長野県茅野市豊平にあるため池である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Mishaka_pond.jpg/960px-Mishaka_pond.jpg', 'Wikipedia', 'wikipedia'),
  ('蓼科高原バラクライングリッシュガーデン', 'viewpoint', 36.036389, 138.240000, '蓼科高原バラクライングリッシュガーデン（たてしなこうげん バラクラ イングリッシュガーデン）は長野県茅野市北山の蓼科高原に所在する、1990年開園の日本初の本格的英国式庭園。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/Tateshina_kogen_craton_english_garden_in_2014-8-15_No%2C36.JPG/960px-Tateshina_kogen_craton_english_garden_in_2014-8-15_No%2C36.JPG', 'Wikipedia', 'wikipedia'),
  ('諏訪鉄山', 'viewpoint', 36.046167, 138.269167, '諏訪鉄山（すわてつざん）は、長野県茅野市北山に存在した露天掘りの鉱山。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/%E7%9F%B3%E9%81%8A%E3%81%AE%E6%B9%AF_-_panoramio.jpg/960px-%E7%9F%B3%E9%81%8A%E3%81%AE%E6%B9%AF_-_panoramio.jpg', 'mapplefan8 / CC BY-SA 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:メルヘン街道'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

