insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('w8INZiA9Y1w', 'https://www.youtube.com/watch?v=w8INZiA9Y1w', '【絶景ドライブ】天空の旅：空を駆けるような絶景ドライブコース15選', 'Holiday Ideas', 517200, ''),
  ('rPs1VDzZYM0', 'https://www.youtube.com/watch?v=rPs1VDzZYM0', '東北ツーリング 感動した道 BEST30', 'パナイモン [Rebel1100]', 175344, '12:30'),
  ('utTgOhUmbeQ', 'https://www.youtube.com/watch?v=utTgOhUmbeQ', '【王道】東北の絶景ドライブ•ツーリングスポット13コース[永久保存版]', 'スバル車で行く東北わんこ旅『アッキー and Ten2』', 168505, ''),
  ('-dKRPwlp3no', 'https://www.youtube.com/watch?v=-dKRPwlp3no', '[総集編．原付旅]東北一周ツーリング', 'YSちゃんねる', 54170, '57:51'),
  ('IaBZ4FX_1Q0', 'https://www.youtube.com/watch?v=IaBZ4FX_1Q0', '【ADV150】東北（秋田・青森）弾丸ツーリング【1日目】', 'へいぞうバイク旅', 19174, ''),
  ('5vvfnTNMUSI', 'https://www.youtube.com/watch?v=5vvfnTNMUSI', '小さなバイクで撮影旅、青森県津軽半島ツーリング No.017　4k プロフォトグラファー　風景写真　モンキーbaja　龍泊ライン　龍飛崎　階段国道　国道339号　バイクツーリング　ドライブ旅行　旅', 'photographer関野温の撮影旅', 9962, ''),
  ('aKkAU7mpwJs', 'https://www.youtube.com/watch?v=aKkAU7mpwJs', '【感動】青森、津軽半島の竜泊ラインが最高過ぎました /DAY3 東北一周3300kmツーリング#5', 'そそそのバイク旅TV', 5477, ''),
  ('aDVBN_Sha40', 'https://www.youtube.com/watch?v=aDVBN_Sha40', '【心揺さぶる原風景へ】一生に一度は見たい東北の秘境　（モンキーbaja、XLR80）小さなバイクで巡る日本の絶景、秘境、道　静寂の旅へ', 'photographer関野温の撮影旅', 5036, ''),
  ('Ik1zK9O_ToQ', 'https://www.youtube.com/watch?v=Ik1zK9O_ToQ', '海沿いのバイク旅が一番楽しい 東北一周ツーリング2023年 Part6 紲星あかり車載 [VOICEROID車載]', 'お燐のバイク旅チャンネル', 2192, '06:18'),
  ('82fxxrRM2CA', 'https://www.youtube.com/watch?v=82fxxrRM2CA', '【東北 絶景ドライブ】一度は走りたい絶景ロード13選｜奥入瀬・八幡平・蔵王・磐梯吾妻', 'Holiday Ideas', 1430, '00:11'),
  ('lt95Kf2ugM8', 'https://www.youtube.com/watch?v=lt95Kf2ugM8', '東北ツーリング PART30「Blue Thermal」', 'Cbr400r Takaprilia RS660', 1158, '09:10'),
  ('1Pg_yodpDKs', 'https://www.youtube.com/watch?v=1Pg_yodpDKs', '【モトブログ】バイクに乗る理由。あぁ絶景。【mt25】【竜泊ライン】【東北絶景ツーリング】', 'なまライダー', 789, ''),
  ('wgMSwSYtWaM', 'https://www.youtube.com/watch?v=wgMSwSYtWaM', '津軽半島の最北端・竜飛崎へ 豪快なワインディングが楽しい竜泊ラインはライダーならば1度は走りたい絶景ワインディングロード', 'LitRider - ツーリングスポット紹介 - ', 638, ''),
  ('xyppz31Evgk', 'https://www.youtube.com/watch?v=xyppz31Evgk', '【Vstrom650】2021春の絶景東北ツーリング【Motorcycle Touring in Tohoku region of Japan】', 'BikerHiker Motovlog', 240, '09:51'),
  ('Mw-qxMBog-8', 'https://www.youtube.com/watch?v=Mw-qxMBog-8', '【爆音】津軽海峡冬景色 竜飛崎の珍スポット 大音量・爆音の津軽海峡冬景色を楽しんできた', 'LitRider - ツーリングスポット紹介 - ', 96, '')
