insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('竜飛崎温泉', 'onsen', 41.256900, 140.347700, '竜飛崎温泉(たっぴざきおんせん）は、青森県東津軽郡外ヶ浜町（旧三厩村）（旧国陸奥国）にある津軽半島最北端の温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Tappizaki-Onsen_180915.jpg/960px-Tappizaki-Onsen_180915.jpg', 'Wikipedia', 'wikipedia'),
  ('道の駅こどまり', 'rest', 41.145190, 140.320420, '道の駅こどまり（みちのえき こどまり）は、青森県北津軽郡中泊町小泊にある国道339号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/83/Michinoeki_kodomari_Pontomari.jpg/960px-Michinoeki_kodomari_Pontomari.jpg', 'Wikipedia', 'wikipedia'),
  ('道の駅みんまや', 'rest', 41.253970, 140.346720, '道の駅みんまや（みちのえきみんまや）は、青森県東津軽郡外ヶ浜町にある国道339号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/Roadside_Station_Minmaya_02.jpg/960px-Roadside_Station_Minmaya_02.jpg', 'Wikipedia', 'wikipedia'),
  ('七つ滝', 'viewpoint', 41.178167, 140.333556, '七つ滝は、青森県北津軽郡中泊町にある高さ約21mの滝。', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/5/58/%E4%B8%83%E3%81%A4%E6%BB%9D.JPEG', 'Wikipedia', 'wikipedia'),
  ('龍飛埼灯台', 'viewpoint', 41.258333, 140.342500, '龍飛埼灯台（たっぴさきとうだい）は、青森県津軽半島の竜飛崎の突端に立つ白亜円形の大型灯台。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/Tappisaki_Lighthouse_202607.jpg/960px-Tappisaki_Lighthouse_202607.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:竜泊ライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

