insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('R750', 'food', 34.328178, 136.829634, 'コメントで料理も接客も良いとおすすめされているお店', 'seed_auto', 'MQS0TrXKQLM', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Ugata_in_Shima.jpg/960px-Ugata_in_Shima.jpg', 'Miyuki Meinaka / CC0 / Wikimedia Commons', 'commons'),
  ('円山公園', 'viewpoint', 34.306950, 136.817918, '御木本幸吉の記念碑がある賢島の公園', 'seed_auto', '66fVD4Gd_oY', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/Kashikojima_Maruyama_Park.jpg/960px-Kashikojima_Maruyama_Park.jpg', 'Miyuki Meinaka / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('賢島大橋', 'viewpoint', 34.310947, 136.817192, '夕日が素敵な絶景スポット', 'seed_auto', '66fVD4Gd_oY', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/Kashikojima_and_Honshu.jpg/960px-Kashikojima_and_Honshu.jpg', 'Miyuki Meinaka / Public domain / Wikimedia Commons', 'commons'),
  ('鳥羽展望台', 'viewpoint', 34.427694, 136.915083, '鳥羽展望台（とばてんぼうだい）は、三重県鳥羽市のパールロード沿線にある展望台。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Toba_Tenbodai_5.jpg/960px-Toba_Tenbodai_5.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:パールロード'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

