  ('我野神社', 'other', 35.920944, 139.208000, '我野神社（あがのじんじゃ）は、埼玉県飯能市の神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/%E6%88%91%E9%87%8E%E7%A5%9E%E7%A4%BE_-_panoramio.jpg/960px-%E6%88%91%E9%87%8E%E7%A5%9E%E7%A4%BE_-_panoramio.jpg', '岩浪陸 / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('東神社', 'other', 35.902861, 139.245694, '東神社（あずまじんじゃ）は、埼玉県飯能市の神社。', 'wikipedia', '', 'https://i.ytimg.com/vi/LWdvQfWUUnY/hqdefault.jpg', 'YouTube', 'youtube'),
  ('法光寺', 'other', 35.908694, 139.224806, '法光寺（ほうこうじ）は、埼玉県飯能市にある曹洞宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Agano_spring.jpg/960px-Agano_spring.jpg', '妖精書士 / CC0 / Wikimedia Commons', 'commons'),
  ('興徳寺', 'other', 35.898694, 139.252472, '興徳寺（こうとくじ）は、埼玉県飯能市にある臨済宗建長寺派の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/Seibu_4000_series_52_Seats_of_Happiness_2017-11-06_%2840029632812%29.jpg/960px-Seibu_4000_series_52_Seats_of_Happiness_2017-11-06_%2840029632812%29.jpg', 'Cheng-en Cheng from Taichung City, Taiwan / CC BY-SA 2.0 / Wikimedia Commons', 'commons'),
  ('長念寺', 'other', 35.887806, 139.272472, '長念寺（ちょうねんじ）は、埼玉県飯能市にある曹洞宗の寺院。', 'wikipedia', '', 'https://i.ytimg.com/vi/LWdvQfWUUnY/hqdefault.jpg', 'YouTube', 'youtube'),
  ('高麗神社', 'other', 35.898583, 139.322806, '高麗神社 （こまじんじゃ）は、埼玉県日高市に鎮座する神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Hidaka_Saitama_Koma_Shrine_Shinmon_1.JPG/960px-Hidaka_Saitama_Koma_Shrine_Shinmon_1.JPG', 'Wikipedia', 'wikipedia'),
  ('刈場坂峠', 'pass', 35.968939, 139.183933, '展望の良いビューポイント', 'seed_auto', '8YcndhGtO4E', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/%E5%A5%A5%E6%AD%A6%E8%94%B5%E3%82%B0%E3%83%AA%E3%83%BC%E3%83%B3%E3%83%A9%E3%82%A4%E3%83%B3%EF%BD%A4%E5%88%88%E5%A0%B4%E5%9D%82%E5%B3%A0_-_panoramio_%286%29.jpg/960px-%E5%A5%A5%E6%AD%A6%E8%94%B5%E3%82%B0%E3%83%AA%E3%83%BC%E3%83%B3%E3%83%A9%E3%82%A4%E3%83%B3%EF%BD%A4%E5%88%88%E5%A0%B4%E5%9D%82%E5%B3%A0_-_panoramio_%286%29.jpg', 'icer1212 / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('定峰峠', 'pass', 36.012208, 139.161654, '奥武蔵グリーンラインの終点側の峠', 'seed_auto', '8YcndhGtO4E', 'https://i.ytimg.com/vi/8YcndhGtO4E/hqdefault.jpg', 'YouTube', 'youtube'),
  ('苅場坂峠', 'pass', 35.968889, 139.183889, '苅場坂峠（かばさかとうげ、かりばさかとうげ） は、埼玉県比企郡ときがわ町、飯能市、秩父郡横瀬町の境目にある標高818メートルの峠である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4c/Kabasakatouge.jpg/960px-Kabasakatouge.jpg', 'Wikipedia', 'wikipedia'),
  ('顔振峠', 'pass', 35.926456, 139.245441, '奥武蔵グリーンライン上にある峠', 'seed_auto', 'Vs5OWd3V4Fg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/%E5%A5%A5%E6%AD%A6%E8%94%B5%E3%82%B0%E3%83%AA%E3%83%BC%E3%83%B3%E3%83%A9%E3%82%A4%E3%83%B3%EF%BD%A4%E9%A1%94%E6%8C%AF%E5%B3%A0_-_panoramio_%281%29.jpg/960px-%E5%A5%A5%E6%AD%A6%E8%94%B5%E3%82%B0%E3%83%AA%E3%83%BC%E3%83%B3%E3%83%A9%E3%82%A4%E3%83%B3%EF%BD%A4%E9%A1%94%E6%8C%AF%E5%B3%A0_-_panoramio_%281%29.jpg', 'icer1212 / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('鎌北湖', 'viewpoint', 35.917143, 139.291049, 'グリーンラインの起点付近にある湖', 'seed_auto', '8YcndhGtO4E', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/Oyagi%2C_Moroyama%2C_Iruma_District%2C_Saitama_Prefecture_350-0452%2C_Japan_-_panoramio_%285%29.jpg/960px-Oyagi%2C_Moroyama%2C_Iruma_District%2C_Saitama_Prefecture_350-0452%2C_Japan_-_panoramio_%285%29.jpg', '赤カメラ / CC BY 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:奥武蔵グリーンライン'
