insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('あのベンチ', 'viewpoint', 35.241601, 136.178233, '琵琶湖畔にあるSNS等で有名な一本木とベンチの撮影スポット', 'seed_auto', 'tAEZ-_WXXRU', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Ishideracho%2C_Hikone%2C_Shiga_Prefecture_521-1101%2C_Japan_-_panoramio.jpg/960px-Ishideracho%2C_Hikone%2C_Shiga_Prefecture_521-1101%2C_Japan_-_panoramio.jpg', 'Fumihiko Ueno / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('マキノサニービーチ', 'viewpoint', 35.451854, 136.060121, '奥琵琶湖の美しい湖畔ビーチ', 'seed_auto', 'tAEZ-_WXXRU', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/%E9%AB%98%E6%9C%A8%E6%B5%9C%E3%83%9E%E3%82%AD%E3%83%8E%E3%82%B5%E3%83%8B%E3%83%BC%E3%83%93%E3%83%BC%E3%83%81_-_panoramio.jpg/960px-%E9%AB%98%E6%9C%A8%E6%B5%9C%E3%83%9E%E3%82%AD%E3%83%8E%E3%82%B5%E3%83%8B%E3%83%BC%E3%83%93%E3%83%BC%E3%83%81_-_panoramio.jpg', 'catyasu / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('海津大崎', 'viewpoint', 35.449181, 136.087549, '琵琶湖北岸の絶景スポットおよび桜の名所', 'seed_auto', 'tAEZ-_WXXRU', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/%E6%B5%B7%E6%B4%A5%E5%A4%A7%E5%B4%8E4_-_panoramio.jpg/960px-%E6%B5%B7%E6%B4%A5%E5%A4%A7%E5%B4%8E4_-_panoramio.jpg', 'baggio4ever / CC BY 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:さざなみ街道'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

