insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('lpNY-aprF8s', 'https://www.youtube.com/watch?v=lpNY-aprF8s', '東京から日帰り圏内の絶景ロードベスト10【10 best scenic roads within a day trip from Tokyo】', 'MSX4 RIDER (マジェックスフォーライダー)', 46901, ''),
  ('FP9ZbT1q_Fg', 'https://www.youtube.com/watch?v=FP9ZbT1q_Fg', '【群馬】志賀草津道路から国道最高地点をハーレーでツーリング/バイク', 'イチロクのハーレーちゃんねる', 25399, '17:06'),
  ('kKXDNVhS27o', 'https://www.youtube.com/watch?v=kKXDNVhS27o', '改良版【素敵すぎる4月の長野県を調査】2025 白馬村ツーリング｜400X バイク旅', 'Moto Lifez', 17890, '17:44'),
  ('CsWRTevzPus', 'https://www.youtube.com/watch?v=CsWRTevzPus', '【ジクサー150】二泊三日 信州ツーリング！長野・群馬の超絶景ロード！＜Day 2＞', 'み山の雑記帳', 16337, ''),
  ('pt6hSMcPi9g', 'https://www.youtube.com/watch?v=pt6hSMcPi9g', '【絶景】突然現れる真っ赤なツツジロード！嬬恋パノラマラインから湯の丸高原へ感動の梅雨入り直前ツーリング「湯の丸高原つつじ祭り2026」', 'おでかけポコ', 11697, ''),
  ('W67PUv1_WQk', 'https://www.youtube.com/watch?v=W67PUv1_WQk', '祝！2026開通【つまごいパノラマライン北ルート】群馬の絶景道路の一つが冬期閉鎖解除開通～開通日翌日の日の出夜明けの絶景ロードのバイクツーリング映像＋愛妻の丘からの浅間山と田代湖などからの絶景', 'おでかけポコ', 7476, ''),
  ('KTVC8xv1zuc', 'https://www.youtube.com/watch?v=KTVC8xv1zuc', '【絶景路】嬬恋パノラマラインをW800で走ってきた【バイク旅】', 'ケロステ', 6234, ''),
  ('SvW1RpeB_0I', 'https://www.youtube.com/watch?v=SvW1RpeB_0I', '【走行検証】つまごいパノラマライン走って～脇道グルリ県道112号も走って～「バラギ高原」に行ってみた！その道どうだった？ #絶景', 'おでかけポコ', 3379, ''),
  ('pe263l_2BRk', 'https://www.youtube.com/watch?v=pe263l_2BRk', '2026冬【つまごいパノラマライン南ルート】スタッドレスタイヤのスーパーカブでバイクツーリングの1/16走行映像　#絶景', 'おでかけポコ', 3239, ''),
  ('f0adO9LaX3A', 'https://www.youtube.com/watch?v=f0adO9LaX3A', '2016年5月 信州ワインディング三昧ツーリング', 'kbtkmc Touring', 3053, ''),
  ('Gy45P9gwDYQ', 'https://www.youtube.com/watch?v=Gy45P9gwDYQ', '【WR250X】峠ばかりの欲張りコースでソロツーリング【長野群馬ラストラン】', 'Tsuka Walker', 1637, ''),
  ('IU8SwJy6XsI', 'https://www.youtube.com/watch?v=IU8SwJy6XsI', '【バイク旅】早朝の長野の高原を走ってきた【WR250X】長野ツーリング前編', 'Tsuka Walker', 1212, ''),
  ('9xhnlvkE1Iw', 'https://www.youtube.com/watch?v=9xhnlvkE1Iw', '群馬の実力を思い知らされた！榛名山と浅間山を巡る旅', 'なちの週末バイク旅', 1156, ''),
  ('BR3Rp47rBGc', 'https://www.youtube.com/watch?v=BR3Rp47rBGc', '【モトブログ】群馬〜長野 猛暑の関東平野 涼を求め高原へ脱出ツーリング', '練り物ちっくーモトブログ', 586, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('奥嬬恋温泉', 'onsen', 36.532890, 138.503280, '奥嬬恋温泉（おくつまごいおんせん）は、群馬県吾妻郡嬬恋村（旧国上野国）にある温泉。', 'wikipedia', '', 'https://i.ytimg.com/vi/lpNY-aprF8s/hqdefault.jpg', 'YouTube', 'youtube'),
  ('愛妻の丘', 'viewpoint', 36.505492, 138.458974, '浅間山とキャベツ畑を見渡せる定番の絶景展望台', 'seed_auto', 'BR3Rp47rBGc', 'https://i.ytimg.com/vi/lpNY-aprF8s/hqdefault.jpg', 'YouTube', 'youtube')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:つまごいパノラマライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('国道169号', '奈良の山間部から紀伊半島を縦断して三重・尾鷲方面へ抜ける紀伊半島の快走ルート。綺麗な川沿いや大自然の山並みを眺めながら走ることができます。
