insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('久美浜温泉湯元館', 'onsen', 34.297553, 135.827973, '丹後半島ツーリングの立ち寄り温泉として視聴者コメントで紹介', 'seed_auto', 'macr_fGxQAY', 'https://i.ytimg.com/vi/macr_fGxQAY/hqdefault.jpg', 'YouTube', 'youtube'),
  ('丹生川上神社下社', 'other', 34.306111, 135.803333, '丹生川上神社下社（にうかわかみじんじゃしもしゃ）は、奈良県吉野郡下市町長谷（ながたに）にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/Niukawakami_simosya01.JPG/960px-Niukawakami_simosya01.JPG', 'Wikipedia', 'wikipedia'),
  ('大名持神社', 'other', 34.394006, 135.868981, '大名持神社（おおなもちじんじゃ）は、奈良県吉野郡吉野町河原屋にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/%C5%8Cnamochi-jinja02.jpg/960px-%C5%8Cnamochi-jinja02.jpg', 'Wikipedia', 'wikipedia'),
  ('大師山寺', 'other', 34.395000, 135.849722, '大師山寺（だいしさんじ）は、奈良県吉野郡吉野町上市にある寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Daishisan-ji.JPG/960px-Daishisan-ji.JPG', 'Wikipedia', 'wikipedia'),
  ('宮滝遺跡', 'other', 34.377194, 135.893306, '宮滝遺跡（みやたきいせき）は、奈良県吉野郡吉野町宮滝にある複合遺跡。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/%E5%AE%AE%E6%BB%9D%E9%81%BA%E8%B7%A1%E3%81%AE%E6%A1%9C%E3%81%AE%E6%9C%A8_2013.4.01_-_panoramio.jpg/960px-%E5%AE%AE%E6%BB%9D%E9%81%BA%E8%B7%A1%E3%81%AE%E6%A1%9C%E3%81%AE%E6%9C%A8_2013.4.01_-_panoramio.jpg', 'Nankou Oronain (as36… / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('岡峯古墳', 'other', 34.379222, 135.795383, '岡峯古墳（おかみねこふん）は、奈良県吉野郡下市町阿知賀にある古墳。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/Okamine_Kofun%2C_funkyu.jpg/960px-Okamine_Kofun%2C_funkyu.jpg', 'Wikipedia', 'wikipedia'),
  ('本善寺', 'other', 34.392831, 135.858811, '本善寺（ほんぜんじ）は、奈良県吉野郡吉野町にある浄土真宗本願寺派の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Honzenji_%28Iigai%29.jpg/960px-Honzenji_%28Iigai%29.jpg', 'Wikipedia', 'wikipedia'),
  ('蔵王堂', 'other', 34.368267, 135.859018, '吉野山にある金峯山寺の本堂。動画の目的地の一つ', 'seed_auto', 'cnT6-CpZLko', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/%E9%87%91%E5%B3%B0%E5%B1%B1%E5%AF%BA%E8%94%B5%E7%8E%8B%E5%A0%82_%E5%90%89%E9%87%8E%E7%94%BA%E5%90%89%E9%87%8E%E5%B1%B1_Kimpusenji_Za%C5%8D-d%C5%8D_2013.4.09_-_panoramio.jpg/960px-%E9%87%91%E5%B3%B0%E5%B1%B1%E5%AF%BA%E8%94%B5%E7%8E%8B%E5%A0%82_%E5%90%89%E9%87%8E%E7%94%BA%E5%90%89%E9%87%8E%E5%B1%B1_Kimpusenji_Za%C5%8D-d%C5%8D_2013.4.09_-_panoramio.jpg', 'Nankou Oronain (as36… / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('願行寺', 'other', 34.369931, 135.787886, '願行寺（がんぎょうじ）は、奈良県吉野郡下市町、秋野川左岸の御坊山麓にある寺。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6a/Gangyoji_%28Shimoichi%29_201802c.jpg/960px-Gangyoji_%28Shimoichi%29_201802c.jpg', 'Wikipedia', 'wikipedia'),
  ('道の駅吉野路 黒滝', 'rest', 34.305890, 135.823280, '道の駅吉野路 黒滝（みちのえき よしのじ くろたき）は、奈良県吉野郡黒滝村長瀬にある国道309号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/20080923%E9%81%93%E3%81%AE%E9%A7%85%E5%90%89%E9%87%8E%E8%B7%AF_%E9%BB%92%E6%BB%9D01.JPG/960px-20080923%E9%81%93%E3%81%AE%E9%A7%85%E5%90%89%E9%87%8E%E8%B7%AF_%E9%BB%92%E6%BB%9D01.JPG', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'num:国道169号:奈良'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

