insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('ニセコアンヌプリ温泉', 'onsen', 42.843920, 140.634500, 'ニセコアンヌプリ温泉（ニセコアンヌプリおんせん）は、北海道虻田郡ニセコ町にある温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/YugokoroTei_roten.JPG/960px-YugokoroTei_roten.JPG', 'Wikipedia', 'wikipedia'),
  ('ニセコ昆布温泉', 'onsen', 42.839830, 140.622420, 'ニセコ昆布温泉（ニセコこんぶおんせん）は、北海道虻田郡ニセコ町、北海道磯谷郡蘭越町にある温泉で、ニセコ温泉郷の一つ。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/Niseko_Konbu_spa_Koikawa_roten.jpg/960px-Niseko_Konbu_spa_Koikawa_roten.jpg', 'Wikipedia', 'wikipedia'),
  ('ニセコ温泉郷', 'onsen', 42.800000, 140.680000, 'ニセコ温泉郷（ニセコおんせんきょう）は、北海道虻田郡ニセコ町および北海道磯谷郡蘭越町にある温泉の総称（温泉郷）であるが、ニセコアンヌプリを中心とするエリアの特徴から、最近は北海道虻田郡倶知安町の温泉も含めてニセコ温泉郷と紹介されることが一般', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/3/37/GOSHIKI_SPR.JPG', 'Wikipedia', 'wikipedia'),
  ('ニセコ湯本温泉', 'onsen', 42.869690, 140.597860, 'ニセコ湯本温泉（ニセコゆもとおんせん）は、北海道磯谷郡蘭越町にある温泉で、ニセコ温泉郷の一つ。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/Niseko_Yumoto_Ooyunuma_2007.jpg/960px-Niseko_Yumoto_Ooyunuma_2007.jpg', 'Wikipedia', 'wikipedia'),
  ('岩内神社', 'other', 42.974528, 140.514444, '岩内神社（いわないじんじゃ）は、北海道岩内郡岩内町にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/Iwanai_Shrine_Haiden.jpg/960px-Iwanai_Shrine_Haiden.jpg', 'Wikipedia', 'wikipedia'),
  ('ニセコ旅物語', 'rest', 42.842853, 140.637394, 'ニセコエリアにある旅の拠点となる宿', 'seed_auto', 'ZuvOqf9mvpY', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/YugokoroTei_roten.JPG/960px-YugokoroTei_roten.JPG', 'Soica2001 (talk) / Public domain / Wikimedia Commons', 'commons'),
  ('道の駅いわない', 'rest', 42.983440, 140.516750, '道の駅いわない（みちのえき いわない）は、北海道岩内郡岩内町にある北海道道270号岩内港線の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a8/Michinoeki_Iwanai.jpg/960px-Michinoeki_Iwanai.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:ニセコパノラマライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
