insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('opaArABbrXM', 'https://www.youtube.com/watch?v=opaArABbrXM', '関東圏のお薦めツーリングロード15選+(ツーリングマップルのレビュー)', 'ヤマハ乗りのホンダ好きの鈴菌', 131698, '08:12'),
  ('Yb150lccGBw', 'https://www.youtube.com/watch?v=Yb150lccGBw', '【群馬】赤城山に紅葉を見に行くよ｜DUCATI Monster 821｜30代 女の休日バイクVlog', 'しーまん  | seaman bike & life vlog', 103247, '08:20'),
  ('CDtM8M6-0Ks', 'https://www.youtube.com/watch?v=CDtM8M6-0Ks', '赤城山の午後は行き当たりばったり｜DUCATI Monster 821｜30代 女の休日バイクVlog', 'しーまん  | seaman bike & life vlog', 83244, '01:28'),
  ('CRCRKNZ6PZQ', 'https://www.youtube.com/watch?v=CRCRKNZ6PZQ', '新装開店【赤城山ほぼの駅AKAGIでランチ】ドライブツーリング！赤城大沼にあったAKAGIフォトスポットがなくなっていたけど、トヨタスポーツ800(通称ヨタハチ)がいた', 'おでかけポコ', 18162, ''),
  ('HGUOhJ3F3Os', 'https://www.youtube.com/watch?v=HGUOhJ3F3Os', '祝3/19開通【赤城山～沼田赤城線】前橋赤城線(上りは南面道路)、雪景色が残る赤城大沼一周して、冬季閉鎖解除開通したばかりの北面道路「沼田赤城線」を下って、県道62号線にて赤城山半周ツーリング映像', 'おでかけポコ', 10604, ''),
  ('mFdxLCXyico', 'https://www.youtube.com/watch?v=mFdxLCXyico', '【モンキー125】春の赤城山ツーリング！絶景と絶品ピザを満喫…からの過酷すぎる林道アタック！？', 'MONKEY125 - まろっしゅ''sモトブログ', 7803, ''),
  ('mighIvp-tqE', 'https://www.youtube.com/watch?v=mighIvp-tqE', '下道1日で何キロ走れる？ボアアップGROM絶景ツーリング(信州･群馬編)', 'sharin-jin', 6717, ''),
  ('-kR5iV1OirA', 'https://www.youtube.com/watch?v=-kR5iV1OirA', '【群馬県】イニシャルDで有名な２つの峠を一気に完走！やっぱり群馬は面白い！', '平日ライダー', 4121, ''),
  ('KFdskLYx9Wc', 'https://www.youtube.com/watch?v=KFdskLYx9Wc', '赤城山の紅葉と雪化粧…奇跡の絶景！モンキー125で秋の群馬ツーリング', 'ゼキザップ_モトブログ', 3478, '02:50'),
  ('-suaN_zHSPk', 'https://www.youtube.com/watch?v=-suaN_zHSPk', '【モトブログ】グンマー赤城山紅葉 照葉峡に行きたかったツーリング', '練り物ちっくーモトブログ', 1253, ''),
  ('3KGQwxBD6UI', 'https://www.youtube.com/watch?v=3KGQwxBD6UI', '【モトブログ】群馬県 グンマーの秘境で海鮮料理＆神のチキンツーリング', '練り物ちっくーモトブログ', 597, ''),
  ('8N8ry33pak4', 'https://www.youtube.com/watch?v=8N8ry33pak4', '【モトブログ】原付2種オフロードのある生活', '練り物ちっくーモトブログ', 405, '08:44'),
  ('9Ji_4LyEq9c', 'https://www.youtube.com/watch?v=9Ji_4LyEq9c', '【モトブログ】赤城山から金精道路ぐるっと一周ツーリング', '練り物ちっくーモトブログ', 155, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('スノーピーク赤城キャンプフィールド', 'other', 36.555983, 139.169952, '4月25日オープン予定のキャンプ場', 'seed_auto', 'HGUOhJ3F3Os', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/Gunma_Sakasa_Akagi_xl.jpg/960px-Gunma_Sakasa_Akagi_xl.jpg', 'GENESIS / CC BY 4.0 / Wikimedia Commons', 'commons'),
  ('大蓮寺', 'other', 36.394722, 139.070000, '大蓮寺（だいれんじ）は、群馬県前橋市千代田町にある浄土宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Dairen-ji_Maebashi_2025-12_ac_%281%29.jpg/960px-Dairen-ji_Maebashi_2025-12_ac_%281%29.jpg', 'Wikipedia', 'wikipedia'),
  ('妙安寺', 'other', 36.394722, 139.069444, '妙安寺（みょうあんじ）は、群馬県前橋市千代田町にある真宗大谷派の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/Myoan-ji_Maebashi_2025-12_ac_%281%29.jpg/960px-Myoan-ji_Maebashi_2025-12_ac_%281%29.jpg', 'Wikipedia', 'wikipedia'),
  ('広瀬川美術館', 'other', 36.395111, 139.068944, '広瀬川美術館（ひろせがわびじゅつかん）は、群馬県前橋市千代田町の広瀬川河畔にある私立美術館。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/Hirosegawa_Art_Museum.jpg/960px-Hirosegawa_Art_Museum.jpg', 'Wikipedia', 'wikipedia'),
  ('橋林寺', 'other', 36.397417, 139.067861, '橋林寺（きょうりんじ）は、群馬県前橋市住吉町にある曹洞宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/Kyorin-ji_Maebashi_2025-12_ac_%281%29.jpg/960px-Kyorin-ji_Maebashi_2025-12_ac_%281%29.jpg', 'Wikipedia', 'wikipedia'),
  ('王山古墳', 'other', 36.394944, 139.052986, '王山古墳（おうやまこふん）は、群馬県前橋市大渡町（おおわたりまち）にある古墳（積石塚）。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/Oyama_Kofun_%28Maebashi%29%2C_funkyu.jpg/960px-Oyama_Kofun_%28Maebashi%29%2C_funkyu.jpg', 'Wikipedia', 'wikipedia'),
  ('総社神社', 'other', 36.388000, 139.037861, '総社神社（そうじゃじんじゃ）は、群馬県前橋市元総社町にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/Souja-jinja_%28Maebashi%29_keidai.JPG/960px-Souja-jinja_%28Maebashi%29_keidai.JPG', 'Wikipedia', 'wikipedia'),
  ('赤城神社', 'other', 36.552666, 139.183551, '秋の紅葉と朱色の神社を参拝', 'seed_auto', 'CDtM8M6-0Ks', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/%E8%B5%A4%E5%9F%8E%E7%A5%9E%E7%A4%BE_-_panoramio.jpg/960px-%E8%B5%A4%E5%9F%8E%E7%A5%9E%E7%A4%BE_-_panoramio.jpg', 'dttx / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('釈迦尊寺', 'other', 36.384167, 139.037778, '釈迦尊寺（しゃかそんじ）は、群馬県前橋市元総社町にある曹洞宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Maebashi_Municipal_Motosoja_Elementary_School.jpg/960px-Maebashi_Municipal_Motosoja_Elementary_School.jpg', 'Suikotei / CC BY 4.0 / Wikimedia Commons', 'commons'),
  ('鳥居峠', 'pass', 36.541050, 139.193051, 'ほぼの駅がある景色が良い峠。', 'seed_auto', 'CRCRKNZ6PZQ', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Akagi-sancho_Station_2016-10.jpg/960px-Akagi-sancho_Station_2016-10.jpg', 'photo: Qurren (talk) Taken with Canon IXY 430F (Digital IXUS 245 HS) / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('ほぼの駅 AKAGI', 'rest', 36.540779, 139.193099, '赤城山鳥居峠にある旧赤城山頂駅を活用した施設。ランチで立ち寄り。', 'seed_auto', 'CRCRKNZ6PZQ', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/Akagi-sancho_Station_platform_2016-10_3.jpg/960px-Akagi-sancho_Station_platform_2016-10_3.jpg', 'photo: Qurren (talk) Taken with Canon IXY 430F (Digital IXUS 245 HS) / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
