insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('まる姫', 'food', 35.295423, 135.886572, '鯖街道沿いにある人気の鯖寿司店', 'seed_auto', 'BktWRNCml0I', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/%E5%85%AB%E7%8E%8B%E5%AD%90%E7%A5%9E%E7%A4%BE_-_panoramio_%282%29.jpg/960px-%E5%85%AB%E7%8E%8B%E5%AD%90%E7%A5%9E%E7%A4%BE_-_panoramio_%282%29.jpg', 'Akeiro Torii / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('栃生梅竹', 'food', 35.294853, 135.886866, 'まる姫の向かいにある有名な鯖寿司店', 'seed_auto', 'BktWRNCml0I', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/%E5%85%AB%E7%8E%8B%E5%AD%90%E7%A5%9E%E7%A4%BE_-_panoramio_%282%29.jpg/960px-%E5%85%AB%E7%8E%8B%E5%AD%90%E7%A5%9E%E7%A4%BE_-_panoramio_%282%29.jpg', 'Akeiro Torii / CC BY-SA 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:鯖街道'
