  ('賀名生梅林', 'viewpoint', 34.295320, 135.717757, '立ち寄った梅林の名所', 'seed_auto', 'ySMEq7oXbUk', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/%E8%B3%80%E5%90%8D%E7%94%9F%E6%A2%85%E6%9E%97_An%C5%8D-bairin%2C_Ume_grove_2014.3.28_-_panoramio.jpg/960px-%E8%B3%80%E5%90%8D%E7%94%9F%E6%A2%85%E6%9E%97_An%C5%8D-bairin%2C_Ume_grove_2014.3.28_-_panoramio.jpg', 'Nankou Oronain (as36… / CC BY-SA 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'num:国道168号:奈良'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

