insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('4Jm2K8QE0KU', 'https://www.youtube.com/watch?v=4Jm2K8QE0KU', '【大阪発！】行って良かった関西/近畿ツーリング7選！日帰りツーリング【大阪・京都・和歌山・奈良・兵庫】', 'トッサン | 原付二種専門', 75741, ''),
  ('lWjremVe_kI', 'https://www.youtube.com/watch?v=lWjremVe_kI', 'モンキー125で淡路島一周ツーリング！原付二種でのフェリーでアワイチを楽しもう！[鳴門海峡〜淡路サンセットライン〜明石海峡][後編]', 'サルカブ', 58293, ''),
  ('TMrIUEOQ8pQ', 'https://www.youtube.com/watch?v=TMrIUEOQ8pQ', '【ジクサー150】夏より快適！？真冬の淡路島ツーリング！ （明石海峡大橋  灘黒岩水仙郷 うずまちテラス  北淡震災記念公園ほか）', 'み山の雑記帳', 15245, '50:31'),
  ('1mujOR1nKUg', 'https://www.youtube.com/watch?v=1mujOR1nKUg', '【モトブログ】ツーリングシーズン到来　関西ツーリングおすすめコース４選', 'Mantis Rider', 14709, ''),
  ('KsI_XfouEpA', 'https://www.youtube.com/watch?v=KsI_XfouEpA', '冬の淡路島ツーリングは絶対やめとけ！バイク乗りの絶望的な実態', '島民スタイル【淡路島のパパサン乗り】', 9201, ''),
  ('-mPxyxpvZVE', 'https://www.youtube.com/watch?v=-mPxyxpvZVE', '【淡路島ツーリング】行列の先に待っていた究極のラーメン。出汁の旨みが体に染み渡る', '島民スタイル【淡路島のパパサン乗り】', 5326, '13:40'),
  ('-0ccTEQ07Dw', 'https://www.youtube.com/watch?v=-0ccTEQ07Dw', '代車に乗ったら想像以上に楽しかった。【VTR250レビュー】', '島民スタイル【淡路島のパパサン乗り】', 3966, '00:05'),
