insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('UGSS9KPy3Mg', 'https://www.youtube.com/watch?v=UGSS9KPy3Mg', '群馬県民の9割が一生通らない道。赤城山の東にある大迫力の風景が美しい林道小中新地線【ハンターカブCT125ツーリング】', 'ゼキザップ_モトブログ', 106839, '02:03'),
  ('DAknNyYhc-4', 'https://www.youtube.com/watch?v=DAknNyYhc-4', '【ローカル快走道路情報2】約23キロ信号機ゼロの県道を走って群馬県桐生市→栃木県佐野市「創業55年老舗500円の佐野ラーメン」と「100円でデザート＆コーヒー」を食べに行くドライブツーリング', 'おでかけポコ', 38766, ''),
  ('dqIe5HPQ00M', 'https://www.youtube.com/watch?v=dqIe5HPQ00M', '12月18日「いろは坂」走って「奥日光」冬景色を見にバイクツーリングに行ってきました＋桐生市から国道122号線の草木湖、足尾町、日足トンネルなどの積雪、凍結などのドライブ道路情報', 'おでかけポコ', 9901, ''),
  ('WLeEea0unc4', 'https://www.youtube.com/watch?v=WLeEea0unc4', '群馬B級スポット？【梨木の氷柱】冬だけの桐生市絶景スポットへ行ったみたツーリングドライブ道中の走行映像と氷柱の様子と場所のレポート', 'おでかけポコ', 7214, ''),
  ('N2dLVGFcygE', 'https://www.youtube.com/watch?v=N2dLVGFcygE', '開花状況【満開】某所の河津桜のトンネルと渡良瀬渓谷鐡道沿い国道122号線ツーリングとグルメ「神梅庵」手打ち蕎麦うどんの店', 'おでかけポコ', 5976, '00:00'),
  ('fNf03xW04vw', 'https://www.youtube.com/watch?v=fNf03xW04vw', 'グンマー帝国の遺跡！国鉄足尾線の廃線路を辿ると、突如現れるモアイ像｜モンキー125で群馬ツーリング│観光ドライブ情報', 'ゼキザップ_モトブログ', 4570, '02:17'),
  ('FKmcCk2u7Z4', 'https://www.youtube.com/watch?v=FKmcCk2u7Z4', '地図に無い群馬の超穴場花桃と桜スポットと精肉店の食事処しまむらで満腹ソースカツ丼とラーメンセット｜モンキー125ツーリング', 'ゼキザップ_モトブログ', 4372, ''),
  ('hy2M2uD9qmQ', 'https://www.youtube.com/watch?v=hy2M2uD9qmQ', '【雪景色の霧降高原へ】スタッドレスタイヤスーパーカブに乗って桐生市→草木湖湖畔みかげ原展望地旧車ミーティングダムサンダーの様子→足尾町→世界遺産日光地区→霧降高原道路を走ってキスゲ平園地までの走行映像', 'おでかけポコ', 3605, ''),
  ('8c6w56sVDxE', 'https://www.youtube.com/watch?v=8c6w56sVDxE', 'YZF-R1 群馬 ０℃の道の駅巡り【ツーリング】', 'RY×バイク旅', 3505, ''),
  ('PGUn7iZUJmo', 'https://www.youtube.com/watch?v=PGUn7iZUJmo', '群馬のマイナー河津桜トンネルと、わたらせ渓谷鐵道沿線の梅と神戸駅の花桃2026｜モンキー125でお花見ツーリング', 'ゼキザップ_モトブログ', 3209, '03:56'),
  ('BGviafGHQlQ', 'https://www.youtube.com/watch?v=BGviafGHQlQ', '県民は素通りして気付かない穴場の桜と、わたらせ渓谷鐵道神戸駅の花桃｜モンキー125で群馬の春旅ツーリング', 'ゼキザップ_モトブログ', 2097, '01:18'),
  ('7M0jJn4LMt0', 'https://www.youtube.com/watch?v=7M0jJn4LMt0', '【モトブログ】2026 夏 福島 茨城 絶景の水湖と絶景の海ツーリング', '練り物ちっくーモトブログ', 2039, '01:58')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('千網谷戸遺跡', 'other', 36.428056, 139.306389, '千網谷戸遺跡（ちあみがいどいせき）は、群馬県桐生市川内町三丁目（大字須永字千網谷戸）にある縄文時代から古墳時代にかけての遺跡。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/ja/thumb/1/10/%E5%8D%83%E7%B6%B2%E8%B0%B7%E6%88%B8%E9%81%BA%E8%B7%A1%E5%87%BA%E5%9C%9F_%E5%9C%9F%E8%A3%BD%E8%80%B3%E9%A3%BE.JPG/960px-%E5%8D%83%E7%B6%B2%E8%B0%B7%E6%88%B8%E9%81%BA%E8%B7%A1%E5%87%BA%E5%9C%9F_%E5%9C%9F%E8%A3%BD%E8%80%B3%E9%A3%BE.JPG', 'Wikipedia', 'wikipedia'),
  ('白髭神社', 'other', 36.414806, 139.324000, '白髭神社（しらひげじんじゃ）は、群馬県桐生市堤町二丁目にある神社。', 'wikipedia', '', 'https://i.ytimg.com/vi/UGSS9KPy3Mg/hqdefault.jpg', 'YouTube', 'youtube'),
  ('高津戸城', 'other', 36.438333, 139.281389, '高津戸城（たかつどじょう）は、群馬県みどり市大間々町高津戸にあった日本の城（山城）。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Okanobori_Canal_monument.jpg/960px-Okanobori_Canal_monument.jpg', 'Qurren / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('城下トンネル', 'pass', 36.485667, 139.263694, '城下トンネル（しろおりトンネル）は、群馬県桐生市にあるトンネルである。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/Watetsu-WK07-Motojuku-station-platform-20250505-101535.jpg/960px-Watetsu-WK07-Motojuku-station-platform-20250505-101535.jpg', 'LERK / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('道の駅くろほね・やまびこ', 'rest', 36.491250, 139.272220, '道の駅くろほね・やまびこ（みちのえき くろほね・やまびこ）は、群馬県桐生市黒保根町下田沢にある国道122号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2b/%E9%81%93%E3%81%AE%E9%A7%85_%E3%81%8F%E3%82%8D%E3%81%BB%E3%81%AD%E3%83%BB%E3%82%84%E3%81%BE%E3%81%B3%E3%81%93_20200822_111927.jpg/960px-%E9%81%93%E3%81%AE%E9%A7%85_%E3%81%8F%E3%82%8D%E3%81%BB%E3%81%AD%E3%83%BB%E3%82%84%E3%81%BE%E3%81%B3%E3%81%93_20200822_111927.jpg', 'Wikipedia', 'wikipedia'),
  ('わたらせ渓谷鐵道', 'viewpoint', 36.433608, 139.277425, 'わたらせ渓谷鐵道株式会社（わたらせけいこくてつどう）は、群馬県・栃木県において特定地方交通線の足尾線を引き継いだ鉄道路線わたらせ渓谷線を運営する第三セクターの鉄道事業者である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/%E5%A4%A7%E9%96%93%E3%80%85%E9%A7%85_%E9%A7%85%E8%88%8E%282023%E5%B9%B48%E6%9C%88%29.jpg/960px-%E5%A4%A7%E9%96%93%E3%80%85%E9%A7%85_%E9%A7%85%E8%88%8E%282023%E5%B9%B48%E6%9C%88%29.jpg', 'Wikipedia', 'wikipedia'),
  ('丸山', 'viewpoint', 36.413778, 139.322333, '丸山（まるやま）は、群馬県桐生市堤町にある山。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/%E5%AF%8C%E5%A3%AB%E5%B1%B1%E4%B8%8B%E9%A7%85%2C_Fujiyamashita_Sta._-_panoramio.jpg/960px-%E5%AF%8C%E5%A3%AB%E5%B1%B1%E4%B8%8B%E9%A7%85%2C_Fujiyamashita_Sta._-_panoramio.jpg', 'xe zna / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('黒保根運動公園', 'viewpoint', 36.499278, 139.277333, '黒保根運動公園（くろほねうんどうこうえん）は、群馬県桐生市黒保根町にある公園。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/%E9%BB%92%E4%BF%9D%E6%A0%B9%E5%A4%A7%E6%A9%8B_-_panoramio.jpg/960px-%E9%BB%92%E4%BF%9D%E6%A0%B9%E5%A4%A7%E6%A9%8B_-_panoramio.jpg', 'くろふね / CC BY 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'num:国道122号:群馬'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

