insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('関ケ原グルメガーデン', 'food', 35.368014, 136.453667, '動画の概要欄で紹介されているグルメスポット', 'seed_auto', 'I9xZh1MhW-k', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/%E9%96%A2%E3%81%8C%E5%8E%9F-%E9%96%A2%E3%83%B6%E5%8E%9F_-_panoramio_%284%29.jpg/960px-%E9%96%A2%E3%81%8C%E5%8E%9F-%E9%96%A2%E3%83%B6%E5%8E%9F_-_panoramio_%284%29.jpg', '珈琲牛乳 / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('伊吹山', 'viewpoint', 35.417778, 136.406389, '伊吹山（いぶきやま、いぶきさん）は、滋賀県と岐阜県の県境を南北に走る伊吹山地の主峰（最高峰）である、標高1,377 mの山。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Ibukiyama_from_Kannonzaka%28Maibara-Nagahama%29.jpg/960px-Ibukiyama_from_Kannonzaka%28Maibara-Nagahama%29.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:伊吹山ドライブウェイ'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

