insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('w8INZiA9Y1w', 'https://www.youtube.com/watch?v=w8INZiA9Y1w', '【絶景ドライブ】天空の旅：空を駆けるような絶景ドライブコース15選', 'Holiday Ideas', 517200, ''),
  ('utTgOhUmbeQ', 'https://www.youtube.com/watch?v=utTgOhUmbeQ', '【王道】東北の絶景ドライブ•ツーリングスポット13コース[永久保存版]', 'スバル車で行く東北わんこ旅『アッキー and Ten2』', 168505, ''),
  ('3f9QK5PZDU0', 'https://www.youtube.com/watch?v=3f9QK5PZDU0', '【2026最新道路開通情報】GWに行くべき絶景道路が続々冬季閉鎖解除開通！「東日本・最強ツーリングドライブルート」＊群馬から日帰り一泊で行ける範囲', 'おでかけポコ', 32155, ''),
  ('9uv6dMbN2Sc', 'https://www.youtube.com/watch?v=9uv6dMbN2Sc', '【東北バイク旅】福島に来たら絶対に行くべき道！やっぱり福島三大ラインは凄かった…。裏磐梯にある大自然の絶景と人気の道の駅グルメを満喫しました。【HONDA Gold Wing/モトブログ】', '突然rider', 12049, ''),
  ('4gE0AFm3aj8', 'https://www.youtube.com/watch?v=4gE0AFm3aj8', '【ADV150】南東北日帰りツーリング', 'へいぞうバイク旅', 9052, ''),
  ('26vU9ggcp1c', 'https://www.youtube.com/watch?v=26vU9ggcp1c', '【東北バイク旅】福島から山形へ吾妻連峰と蔵王連峰を見渡す絶景ツーリング！ライダーが集まる神社やカフェも満喫しました。【Honda Gold Wing/モトブログ】', '突然rider', 9033, '09:00'),
  ('Bx2gDtLYiTk', 'https://www.youtube.com/watch?v=Bx2gDtLYiTk', '【東北バイク旅】福島にある絶景の裏磐梯と西吾妻スカバレーを満喫するツーリング！猪苗代町の隠れた名店も見つけました。【Honda Gold Wing/モトブログ】', '突然rider', 3259, ''),
  ('2ip-k4Red5w', 'https://www.youtube.com/watch?v=2ip-k4Red5w', '【またもや悲劇】リベンジで蔵王へ！新型レブル1100Tでエコーラインを走るも2度目の大失敗！心折れるも東北の絶景とバイク女子が経営するお店で美味しいグルメを堪能しました。【モトブログ】', '突然rider', 2689, ''),
  ('n4yBqovw1KQ', 'https://www.youtube.com/watch?v=n4yBqovw1KQ', '2020 東北ツーリング『絶景の蔵王エコーラインと赤湯辛味噌ラーメン』のモトブログ', 'KOBA MotoChannel', 2541, ''),
  ('OJSwiBXFiDQ', 'https://www.youtube.com/watch?v=OJSwiBXFiDQ', '【バイク旅】絶対に行きたい東北の絶景紅葉！活火山のある磐梯吾妻スカイランから山形まで走るソロツー。穴場ルートとカフェやグルメも楽しみました。【モトブログ】Gold Wing Tour', '突然rider', 2014, ''),
  ('pv9UZAJmzIQ', 'https://www.youtube.com/watch?v=pv9UZAJmzIQ', 'モンキー125で半年ぶりに開通した西吾妻スカイバレーツーリング！磐梯山ゴールドラインは…期待と違った感じでした^^;', 'ゼキザップ_モトブログ', 2007, ''),
  ('IGt9w1clKv0', 'https://www.youtube.com/watch?v=IGt9w1clKv0', '磐梯吾妻スカイラインに行ってきました[レブル1100][Rebel1100]', 'パナイモン [Rebel1100]', 790, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('早稲沢温泉', 'onsen', 37.725800, 140.066300, '早稲沢温泉（わせざわおんせん）は福島県耶麻郡北塩原村檜原にある温泉。', 'wikipedia', '', 'https://i.ytimg.com/vi/w8INZiA9Y1w/hqdefault.jpg', 'YouTube', 'youtube'),
  ('白布峠', 'pass', 37.750355, 140.092508, '西吾妻スカイバレーの峠', 'seed_auto', '26vU9ggcp1c', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Shirabu_Peak%28%E7%99%BD%E5%B8%83%E5%B3%A0%29_-_panoramio.jpg/960px-Shirabu_Peak%28%E7%99%BD%E5%B8%83%E5%B3%A0%29_-_panoramio.jpg', 'Fumihiko Ueno / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('曽原湖', 'viewpoint', 37.685333, 140.070528, '曽原湖（そはらこ）は、福島県北塩原村にある湖。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/Lake_Sohara-ko.JPG/960px-Lake_Sohara-ko.JPG', 'Wikipedia', 'wikipedia'),
  ('桧原湖', 'viewpoint', 37.683167, 140.059037, '磐梯山をバックに美しい景観が広がるスポット', 'seed_auto', 'Bx2gDtLYiTk', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/%E8%A3%8F%E7%A3%90%E6%A2%AF%E6%A1%A7%E5%8E%9F%E6%B9%96%E7%95%94%E3%83%9B%E3%83%86%E3%83%AB%E3%81%8B%E3%82%89%E6%9C%9B%E3%82%80_-_panoramio.jpg/960px-%E8%A3%8F%E7%A3%90%E6%A2%AF%E6%A1%A7%E5%8E%9F%E6%B9%96%E7%95%94%E3%83%9B%E3%83%86%E3%83%AB%E3%81%8B%E3%82%89%E6%9C%9B%E3%82%80_-_panoramio.jpg', 'jeienne / CC BY 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:西吾妻スカイバレー'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

