insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('pJZlHx-7uTc', 'https://www.youtube.com/watch?v=pJZlHx-7uTc', '【赤城山一周のススメ】お気軽！短時間！絶景！ワインディング！峠道！全て揃ったツーリング　#ツーリングスポット', 'おでかけポコ', 14901, ''),
  ('vB7mLSInOq0', 'https://www.youtube.com/watch?v=vB7mLSInOq0', '【群馬の秘境が凄すぎる】5月7日なのに！桜・チューリップ・スイセンが同時に見頃！？美味しい！旨い！すいせんソフトクリームも食べられる絶景のノルンみなかみフラワーガーデンへバイクツーリング', 'おでかけポコ', 12627, ''),
  ('z-FSp31XBMg', 'https://www.youtube.com/watch?v=z-FSp31XBMg', '春近し【絶景ルート】雪解けが進んでいた2月14日の赤城山の麓ツーリング！満開が近い梅の名所と利根沼田望郷ラインを走って道の駅川場田園プラザへ、そして赤城山南麓行列のできる蕎麦の名店で2人前を一人で食す', 'おでかけポコ', 11087, '23:26'),
  ('HGUOhJ3F3Os', 'https://www.youtube.com/watch?v=HGUOhJ3F3Os', '祝3/19開通【赤城山～沼田赤城線】前橋赤城線(上りは南面道路)、雪景色が残る赤城大沼一周して、冬季閉鎖解除開通したばかりの北面道路「沼田赤城線」を下って、県道62号線にて赤城山半周ツーリング映像', 'おでかけポコ', 10604, ''),
  ('nTd7AVqZgyQ', 'https://www.youtube.com/watch?v=nTd7AVqZgyQ', '【まだ赤城山一周できるかな？】各道路の雪や凍結、ドライorウェット路面の様子「からっ風街道」「赤城西麓広域農道」「利根沼田望郷ライン」「薗原湖湖畔道路」「県道62号沼田大間々線」などドライブツーリング', 'おでかけポコ', 7904, ''),
  ('oj5G5U3j4BY', 'https://www.youtube.com/watch?v=oj5G5U3j4BY', '赤城山から周回ルート【前編】絶景と花をつないで奥日光へ', 'おでかけポコ', 7505, ''),
  ('_EH2w7BmuIc', 'https://www.youtube.com/watch?v=_EH2w7BmuIc', '今の【群馬の絶景スポット教えます】雪山と紅葉と花と絶景ロード！群馬県で珍しい絶景！三段紅葉は見られるのか？', 'おでかけポコ', 7132, ''),
  ('J_ZORiPWy50', 'https://www.youtube.com/watch?v=J_ZORiPWy50', '群馬県人が群馬で迷子に【未知の絶景スポット発見】ひまわり畑を目指したら未知の絶景と幻の滝に辿り着いた～群馬の夏ツーリング2026年6月17日', 'おでかけポコ', 6861, ''),
  ('AMPeFWejYUg', 'https://www.youtube.com/watch?v=AMPeFWejYUg', '【モトブログ】入道雲の下で夏満喫 真夏の群馬 絶景ルートを駆けるツーリング おじさん少年の夏へ帰る', '練り物ちっくーモトブログ', 2491, '02:26'),
  ('JxsHwxjmtIo', 'https://www.youtube.com/watch?v=JxsHwxjmtIo', '【モトブログ】赤城山周辺オススメ 4つの快走路巡る 辛味噌ラーメンでポカポカ ツーリング', '練り物ちっくーモトブログ', 2403, ''),
  ('5uirSY0pnjU', 'https://www.youtube.com/watch?v=5uirSY0pnjU', '【モトブログ】４つの絶景快走路で赤城山一周Touring', '練り物ちっくーモトブログ', 1288, ''),
  ('8N8ry33pak4', 'https://www.youtube.com/watch?v=8N8ry33pak4', '【モトブログ】原付2種オフロードのある生活', '練り物ちっくーモトブログ', 405, '02:50')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('中塚古墳', 'other', 36.423417, 139.244228, '中塚古墳（なかつかこふん）は、群馬県桐生市新里町新川にある古墳。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/Nakatsuka_Kofun_%28Kiryu%29%2C_funkyu-1.jpg/960px-Nakatsuka_Kofun_%28Kiryu%29%2C_funkyu-1.jpg', 'Wikipedia', 'wikipedia'),
  ('小林天神古墳', 'other', 36.422394, 139.237464, '小林天神古墳（こばやしてんじんこふん/こばやしのてんじんこふん、天神山古墳）は、群馬県桐生市新里町小林にある古墳。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/Kobayashi_Tenjin_Kofun%2C_funkyu.jpg/960px-Kobayashi_Tenjin_Kofun%2C_funkyu.jpg', 'Wikipedia', 'wikipedia'),
  ('山上城', 'other', 36.428056, 139.227778, '山上城（やまかみじょう）は、群馬県桐生市新里町山上にあった戦国時代の城。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1b/Yamakami_Castle_entrance.jpg/960px-Yamakami_Castle_entrance.jpg', 'Wikipedia', 'wikipedia'),
  ('武井廃寺塔跡', 'other', 36.423861, 139.242931, '武井廃寺塔跡（たけいはいじとうあと）は、群馬県桐生市新里町武井にある古墳（火葬墓）。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Takei_Haiji%2C_gaikan-2.jpg/960px-Takei_Haiji%2C_gaikan-2.jpg', 'Wikipedia', 'wikipedia'),
  ('現代からくりおもちゃ美術館・ぽるぺっぽ', 'other', 36.485806, 139.114306, '現代からくりおもちゃ美術館・ぽるぺっぽ（げんだいからくりおもちゃびじゅつかん・ぽるぺっぽ）は、かつて群馬県前橋市の赤城山中腹にあった私立美術館。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/36/Akagi_Onuma_Canal_No.1_Circular_tank_diversion_works.jpg/960px-Akagi_Onuma_Canal_No.1_Circular_tank_diversion_works.jpg', 'photo: Qurren (talk) Taken with Canon PowerShot G9 X / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('赤城パーキングエリア', 'other', 36.537440, 139.048280, '赤城パーキングエリア（あかぎパーキングエリア）は、群馬県渋川市赤城町津久田にある関越自動車道のパーキングエリア。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/Akagi_PA.JPG/960px-Akagi_PA.JPG', 'Wikipedia', 'wikipedia'),
  ('赤城神社', 'other', 36.484056, 139.177694, '赤城神社（あかぎじんじゃ）は、群馬県前橋市三夜沢町にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Akagi-jinja_%28Miyosawa%29_shoumen.JPG/960px-Akagi-jinja_%28Miyosawa%29_shoumen.JPG', 'Wikipedia', 'wikipedia'),
  ('長者塚古墳', 'other', 36.455125, 139.229533, '長者塚古墳（ちょうじゃづかこふん、関長者塚古墳）は、群馬県桐生市新里町関にある古墳。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Chojazuka_Kofun%2C_funkyu.jpg/960px-Chojazuka_Kofun%2C_funkyu.jpg', 'Wikipedia', 'wikipedia'),
  ('嶺公園', 'viewpoint', 36.457606, 139.119326, '赤城山南麓にある梅の名所', 'seed_auto', 'z-FSp31XBMg', 'https://i.ytimg.com/vi/z-FSp31XBMg/hqdefault.jpg', 'YouTube', 'youtube')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:からっ風街道'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

