insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('DqXJ1BVRKOQ', 'https://www.youtube.com/watch?v=DqXJ1BVRKOQ', '【秩父旅 #1】秩父の絶対行きたいツーリングスポットを巡る旅。「前編」 秩父高原牧場～小鹿神社【 BMW S1000RR / モトブログ 】', 'ESPRESSO RIDER / エスプレッソライダー ', 121331, '07:46'),
  ('KVloCaBTRs4', 'https://www.youtube.com/watch?v=KVloCaBTRs4', '【2024保存版】秩父絶景ツーリングガイド', 'KOBA MotoChannel', 17114, ''),
  ('q5MyMgv19xM', 'https://www.youtube.com/watch?v=q5MyMgv19xM', '埼玉探訪【絶景スポット巡りツーリング1】ナビに逆らって迷子…からの偶然見つけた見つけたミカン畑にあった絶景スポットや3年ぶり復活の天空のポピー！', 'おでかけポコ', 12811, ''),
  ('RKnz8oZEsbc', 'https://www.youtube.com/watch?v=RKnz8oZEsbc', '開花状況＆絶景【秩父・小川町】春の桃源郷・花桃の郷花桃街道バイクツーリング＆ドライブルート！3月14日撮影', 'おでかけポコ', 12009, '17:07'),
  ('Mmt3fqIh_LQ', 'https://www.youtube.com/watch?v=Mmt3fqIh_LQ', '秩父【絶景ロード＆絶景スポット巡り】天空の展望台、皇鈴山展望台、美の山公園展望台、超激坂チャレンジ、埼玉で発見！花桃街道', 'おでかけポコ', 11219, '16:40'),
  ('bDZeEyKreI4', 'https://www.youtube.com/watch?v=bDZeEyKreI4', '暑い夏は朝活ツーリング！涼を求めて埼玉県秩父の険道をモンキー125で初走行と秩父高原牧場ミルクハウスでライダーの義務', 'ゼキザップ_モトブログ', 9010, ''),
  ('j8QRFR5lGNM', 'https://www.youtube.com/watch?v=j8QRFR5lGNM', 'トレーに直接盛られた蕎麦とミルクハウスでライダーの義務｜CT125ハンターカブで秩父グルメツーリング', 'ゼキザップ_モトブログ', 6593, '05:22'),
  ('7x7MEmF_rmw', 'https://www.youtube.com/watch?v=7x7MEmF_rmw', '[バイク旅#150] 祝150動画アップ記念ソロツー　バイクの町 小鹿野で贅沢グルメ　「まる銀 たじま」さんで「鉱水うなぎ」を食べる　記念日にふさわしい美味しさだったｗ', 'イーザイル', 4147, ''),
  ('D0Tx5c0lrLo', 'https://www.youtube.com/watch?v=D0Tx5c0lrLo', '[バイク旅#153] 東秩父山越えバイクツー(埼玉県)　ゴール寄居町「焼肉たてがみ」さんの「豚丼」は最高・満足！　彩の国ふれあい牧場からの絶景あり', 'イーザイル', 2829, ''),
  ('0_cu8AFjMX8', 'https://www.youtube.com/watch?v=0_cu8AFjMX8', '秩父ツーリング【秩父高原牧場】', 'S 40.s', 2783, ''),
  ('03CsmjzfCkg', 'https://www.youtube.com/watch?v=03CsmjzfCkg', '[バイク旅#71]埼玉県東秩父にZ900RSでマスツー　ときがわ町の高柳うどんは箸がとまらない　ふれあい牧場で癒されました', 'イーザイル', 2559, '07:09'),
  ('9MYkXPWLiag', 'https://www.youtube.com/watch?v=9MYkXPWLiag', '『2025秩父』絶景スポット、グルメ、お土産を紹介', 'KOBA MotoChannel', 1702, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
