insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('cwJTfPdLDj8', 'https://www.youtube.com/watch?v=cwJTfPdLDj8', '【八ヶ岳】知ってる？信州の大自然を全力で楽しめる絶景ツーリング！｜山梨観光｜バイク女子｜モトブログ', 'バイクで旅するまりさん 【Mari''s  motorcycle Vlog / ninja 650】', 58346, ''),
  ('lpNY-aprF8s', 'https://www.youtube.com/watch?v=lpNY-aprF8s', '東京から日帰り圏内の絶景ロードベスト10【10 best scenic roads within a day trip from Tokyo】', 'MSX4 RIDER (マジェックスフォーライダー)', 46901, ''),
  ('Le95YDlgLbo', 'https://www.youtube.com/watch?v=Le95YDlgLbo', '【長野】ビーナスラインと秘境の大鹿村がすごく良かったツーリング | SV650', 'STOMP', 30928, ''),
  ('8jMssrtJf3E', 'https://www.youtube.com/watch?v=8jMssrtJf3E', '【長野・諏訪湖】たった4時間で絶景＆名所めぐり！バイク旅でもこんなに楽しめる｜モトブログ｜長野観光', 'バイクで旅するまりさん 【Mari''s  motorcycle Vlog / ninja 650】', 16666, ''),
  ('D-fQ4c_8JuA', 'https://www.youtube.com/watch?v=D-fQ4c_8JuA', '［ 長野編 ］バイクで走る長野県の絶景山岳ツーリングコース13選★人生で一度は走りたい最高の道！#絶景ロード #長野県', 'I Am Rider', 16577, ''),
  ('0QZ8HaXH3TE', 'https://www.youtube.com/watch?v=0QZ8HaXH3TE', 'Z900RS 長野 夏のビーナスラインで心を整える【ツーリング】', 'RY×バイク旅', 16378, '06:35'),
  ('GLC48zzOYgc', 'https://www.youtube.com/watch?v=GLC48zzOYgc', '祝！全線開通【ビーナスライン】開通日翌日～富士山も見えた夜明けの絶景ロードのバイクツーリング走行映像(白樺湖→霧ヶ峰→美ヶ原高原美術館)', 'おでかけポコ', 11828, ''),
