insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('rPs1VDzZYM0', 'https://www.youtube.com/watch?v=rPs1VDzZYM0', '東北ツーリング 感動した道 BEST30', 'パナイモン [Rebel1100]', 175344, '00:45'),
  ('utTgOhUmbeQ', 'https://www.youtube.com/watch?v=utTgOhUmbeQ', '【王道】東北の絶景ドライブ•ツーリングスポット13コース[永久保存版]', 'スバル車で行く東北わんこ旅『アッキー and Ten2』', 168505, ''),
  ('GmhkVSkUfMs', 'https://www.youtube.com/watch?v=GmhkVSkUfMs', '磐梯吾妻スカイライン | 行くぜ、磐梯。福島三大ラインツーリング | Husqvarna Svartpilen 401', 'moto IGNITE', 103714, '08:57'),
  ('3f9QK5PZDU0', 'https://www.youtube.com/watch?v=3f9QK5PZDU0', '【2026最新道路開通情報】GWに行くべき絶景道路が続々冬季閉鎖解除開通！「東日本・最強ツーリングドライブルート」＊群馬から日帰り一泊で行ける範囲', 'おでかけポコ', 32155, ''),
  ('9uv6dMbN2Sc', 'https://www.youtube.com/watch?v=9uv6dMbN2Sc', '【東北バイク旅】福島に来たら絶対に行くべき道！やっぱり福島三大ラインは凄かった…。裏磐梯にある大自然の絶景と人気の道の駅グルメを満喫しました。【HONDA Gold Wing/モトブログ】', '突然rider', 12049, ''),
  ('rNytR1w3GHk', 'https://www.youtube.com/watch?v=rNytR1w3GHk', '紅葉、爽快、そして渋滞　磐梯吾妻スカイライン　バイクツーリング　BMW R1100RT', 'Blueberry White', 6963, ''),
  ('pyaA42mXWsU', 'https://www.youtube.com/watch?v=pyaA42mXWsU', '【東北地方】日本の絶景100選：美しき日本の風景', 'Holiday Ideas', 5189, ''),
  ('v-6Qztj7nlM', 'https://www.youtube.com/watch?v=v-6Qztj7nlM', '峠道＜栃木→福島ソロツーリング#6＞福島・磐梯吾妻スカイラインつづき【F900R BMW MOTORRAD】絶景だけではない！福島の極上ワインディングロード', 'HIDEMARU RIDER', 1655, ''),
  ('82fxxrRM2CA', 'https://www.youtube.com/watch?v=82fxxrRM2CA', '【東北 絶景ドライブ】一度は走りたい絶景ロード13選｜奥入瀬・八幡平・蔵王・磐梯吾妻', 'Holiday Ideas', 1430, '04:36'),
  ('1fAA6RBCBsc', 'https://www.youtube.com/watch?v=1fAA6RBCBsc', '【2022年】首都圏発！圧倒的ゴールデンウィークにおすすめの絶景ツーリングロード５選', '圧倒的バイクチャンネル', 1039, ''),
  ('Xaz3xPCe1jc', 'https://www.youtube.com/watch?v=Xaz3xPCe1jc', '磐梯吾妻スカイライン＃２　ガチ絶景！行きたくなる映像。東北屈指の絶景道はこんなにも綺麗なのか！磐梯3ラインを走る南東北ツーリングDay２。', 'うらしばモータース', 342, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('道の駅裏磐梯', 'rest', 37.665030, 140.043830, '道の駅裏磐梯（みちのえき うらばんだい）は、福島県耶麻郡北塩原村にある国道459号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/Urabandai%2C_Michi-no-Eki%2C_Fukushima%2C_Japan%2C_November_2019.jpg/960px-Urabandai%2C_Michi-no-Eki%2C_Fukushima%2C_Japan%2C_November_2019.jpg', 'Wikipedia', 'wikipedia'),
  ('小野川湖', 'viewpoint', 37.672694, 140.097694, '小野川湖（おのがわこ）は、福島県耶麻郡北塩原村にある湖。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/Lake_Onogawa-ko2.JPG/960px-Lake_Onogawa-ko2.JPG', 'Wikipedia', 'wikipedia'),
  ('磐梯高原', 'viewpoint', 37.656861, 140.078833, '磐梯高原（ばんだいこうげん）は、裏磐梯または裏磐梯高原とも呼ばれ、福島県北部にある磐梯山、安達太良山、吾妻山に囲まれた標高800メートル程度の高原状の地域をいう。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/Mt.Bandai.jpg/960px-Mt.Bandai.jpg', 'Wikipedia', 'wikipedia'),
  ('秋元湖', 'viewpoint', 37.655556, 140.133333, '秋元湖（あきもとこ）は、福島県耶麻郡北塩原村および同郡猪苗代町にまたがる湖。', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/a/a6/Akimotoko.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:磐梯吾妻レークライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

