insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('I3XtOD1W__Q', 'https://www.youtube.com/watch?v=I3XtOD1W__Q', '【日光ツーリング】大型バイク２台と栃木県の絶景を堪能しに行ってきた。でも季節外れの寒さに負けて引き返してきた｜ツーリング｜Ninja｜Kawasaki｜ZX4R｜ZX25R｜いろは坂｜CB750F', 'TAKASHUN【モトブログ】', 92545, ''),
  ('LWdvQfWUUnY', 'https://www.youtube.com/watch?v=LWdvQfWUUnY', '[ 関東編 ] バイクで走る関東地方の首都圏圧巻のツーリングコース20選★人生で一度は走りたい最高の道！#絶景ロード #東京', 'I Am Rider', 23880, ''),
  ('spArxTXWiOI', 'https://www.youtube.com/watch?v=spArxTXWiOI', '【GSX-S125】日光霧降高原ツーリング 前編 ≪埼玉～日塩もみじライン≫', 'GreeDolly/グリードリー', 19742, ''),
  ('MF5yGxTmi7M', 'https://www.youtube.com/watch?v=MF5yGxTmi7M', '【秋のとちぎ旅 #2】栃木に来たら必ず走りたい道。 栃木ツーリング#2【HONDA CL250 / モトブログ 】GOPRO HERO12', 'ESPRESSO RIDER / エスプレ', 14470, '01:49'),
  ('1aoKI45a-28', 'https://www.youtube.com/watch?v=1aoKI45a-28', '【バイク】初秋の栃木・那須高原ツーリング（那須高原・日塩もみじライン）【快走路】', 'Gutti''s MotoVlog', 11417, ''),
  ('0Kb8oFsGISk', 'https://www.youtube.com/watch?v=0Kb8oFsGISk', '【関東・甲信越 絶景ドライブ】一度は走りたい絶景ロード18選｜富士山・箱根・ビーナスライン・房総', 'Holiday Ideas', 10619, '09:25'),
  ('fXmiJck1eBQ', 'https://www.youtube.com/watch?v=fXmiJck1eBQ', '【YZF‐R1】往復440キロ 日光の紅葉の求めて【ツーリング】', 'RY×バイク旅', 7738, ''),
  ('CqsLhbP-8WA', 'https://www.youtube.com/watch?v=CqsLhbP-8WA', '【ソロツーリング】牧場の間を抜ける最高のロードを走ります【奥日光】WR250X 栃木県', 'Tsuka Walker', 4313, ''),
  ('HWj0jfNePOA', 'https://www.youtube.com/watch?v=HWj0jfNePOA', '2026年【栃木県】 真夏に涼しい道路ベスト10（前編）絶景スポット・展望地・道路最高地点も紹介！気象庁データから8月の平均気温を計算！夏のツーリング、ドライブの参考に！', 'おでかけポコ', 4278, ''),
  ('TRjm7ZrkRo8', 'https://www.youtube.com/watch?v=TRjm7ZrkRo8', '【ツーリングプラン】「もはや神コスパ」な3000円日帰りツーリング｜絶景ロードを駆け抜ける！', '​のっとん / バイク旅ch - NoTone Ride Japan', 335, ''),
  ('5XsJE44yBMg', 'https://www.youtube.com/watch?v=5XsJE44yBMg', 'TabiMoto　VT250SPADA　紅葉の栃木３大ワインディングロード走破 insta360 one R', 'Tabi Moto', 114, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('中塩原温泉', 'onsen', 36.978530, 139.811920, '中塩原温泉（なかしおばらおんせん）は、栃木県那須塩原市（旧国下野国）にある塩原温泉郷塩原十一湯の一つの温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/Shiobara_Branch_of_Nasushiobara_City_Hall.jpg/960px-Shiobara_Branch_of_Nasushiobara_City_Hall.jpg', 'Miyuki Meinaka / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('塩原新湯温泉', 'onsen', 36.956310, 139.781140, '塩原新湯温泉（あらゆおんせん）は、栃木県那須塩原市（旧国下野国）にある塩原温泉郷の一つの温泉。', 'wikipedia', '', 'https://i.ytimg.com/vi/I3XtOD1W__Q/hqdefault.jpg', 'YouTube', 'youtube'),
  ('塩原温泉郷', 'onsen', 36.968500, 139.823100, '塩原温泉郷（しおばらおんせんきょう）は、栃木県那須塩原市（旧国下野国）塩原地区内の、箒川沿いの谷間を中心に点在する11の温泉の総称（温泉郷）。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Yuppo_no_Sato.JPG/960px-Yuppo_no_Sato.JPG', 'Wikipedia', 'wikipedia'),
  ('温泉神社', 'onsen', 36.953194, 139.779667, '温泉神社（おんせんじんじゃ）は栃木県那須塩原市にある神社。', 'wikipedia', '', 'https://i.ytimg.com/vi/I3XtOD1W__Q/hqdefault.jpg', 'YouTube', 'youtube'),
  ('畑下温泉', 'onsen', 36.966780, 139.826690, '畑下温泉（はたおりおんせん）は、栃木県那須塩原市（旧国下野国）にある塩原温泉郷の一つの温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Hataori_Onsen_Town.jpg/960px-Hataori_Onsen_Town.jpg', 'Wikipedia', 'wikipedia'),
  ('門前温泉', 'onsen', 36.969780, 139.821420, '門前温泉（もんぜんおんせん）は、栃木県那須塩原市（旧国下野国）にある塩原温泉郷の一つの温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Shiobara_Monzen_Onsen.JPG/960px-Shiobara_Monzen_Onsen.JPG', 'Wikipedia', 'wikipedia'),
  ('妙雲寺', 'other', 36.970778, 139.821222, '妙雲寺（みょううんじ）は、栃木県那須塩原市塩原にある臨済宗妙心寺派の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/%E7%94%98%E9%9C%B2%E5%B1%B1%E5%A6%99%E9%9B%B2%E5%AF%BA%E5%A4%A7%E9%96%80.jpg/960px-%E7%94%98%E9%9C%B2%E5%B1%B1%E5%A6%99%E9%9B%B2%E5%AF%BA%E5%A4%A7%E9%96%80.jpg', 'Wikipedia', 'wikipedia'),
  ('日塩峠', 'pass', 36.925751, 139.753501, '日塩もみじラインの峠', 'seed_auto', 'HWj0jfNePOA', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/%E6%97%A5%E5%A1%A9%E3%82%82%E3%81%BF%E3%81%98%E3%83%A9%E3%82%A4%E3%83%B3_20131012_-_panoramio.jpg/960px-%E6%97%A5%E5%A1%A9%E3%82%82%E3%81%BF%E3%81%98%E3%83%A9%E3%82%A4%E3%83%B3_20131012_-_panoramio.jpg', '690 Noda / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('龍王峡', 'viewpoint', 36.863333, 139.713056, '龍王峡（りゅうおうきょう）は、栃木県北部、日光市の鬼怒川上流部に発達する峡谷。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e4/250725_Ryuokyo_Nikko_Tochigi_pref_Japan15s3.jpg/960px-250725_Ryuokyo_Nikko_Tochigi_pref_Japan15s3.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:日塩もみじライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

