select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('O_D2jrha0xg', 'https://www.youtube.com/watch?v=O_D2jrha0xg', '【絶景永久保存版】 阿蘇を日帰り8時間で楽しむ！阿蘇のオススメツーリングスポット紹介！CBR1000RR SC59で駆け抜けてみた！ミルクロードやまなみハイウェイ阿蘇パノラマライン箱石峠【モトブログ】', 'ヤマモト店長のモトブログ', 90312, ''),
  ('rA1Q-6srPR4', 'https://www.youtube.com/watch?v=rA1Q-6srPR4', '阿蘇の絶景ルート紹介 阿蘇ツーリング 阿蘇の楽しみ方 阿蘇バイクツーリング 阿蘇バイク【MotoVlog#79】', '青井 薫生 バイクのチャンネル', 59351, '03:37'),
