insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('上色見熊野座神社', 'other', 32.854500, 131.158667, '上色見熊野座神社（かみしきみ くまのいますじんじゃ、かみしきみ くまのざじんじゃ）は、熊本県阿蘇郡高森町上色見（かみしきみ）にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Kamishikimi_Kumanoimasu_Shrine_001.jpg/960px-Kamishikimi_Kumanoimasu_Shrine_001.jpg', 'Wikipedia', 'wikipedia'),
  ('阿蘇神社', 'other', 32.947778, 131.115972, '阿蘇神社（あそじんじゃ）は、九州中央部、熊本県阿蘇市にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/Aso_Jinja_03.jpg/960px-Aso_Jinja_03.jpg', 'Wikipedia', 'wikipedia'),
  ('箱石峠', 'pass', 32.906364, 131.154560, '根子岳のギザギザとした雄大な姿を間近に望める絶景峠。', 'seed_auto', 'O_D2jrha0xg', 'https://i.ytimg.com/vi/O_D2jrha0xg/hqdefault.jpg', 'YouTube', 'youtube'),
  ('箱石峠展望所', 'viewpoint', 32.907739, 131.150114, '根子岳超接近パノラマが楽しめる絶景スポット', 'seed_auto', 'GtojBqbKsq4', 'https://i.ytimg.com/vi/O_D2jrha0xg/hqdefault.jpg', 'YouTube', 'youtube')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:箱石峠'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

