insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('LWdvQfWUUnY', 'https://www.youtube.com/watch?v=LWdvQfWUUnY', '[ 関東編 ] バイクで走る関東地方の首都圏圧巻のツーリングコース20選★人生で一度は走りたい最高の道！#絶景ロード #東京', 'I Am Rider', 23880, ''),
  ('AB-WnR8FwNs', 'https://www.youtube.com/watch?v=AB-WnR8FwNs', '[バイク旅#208] 名栗湖有間ダムから妙義山へ　峠の釜めし「おぎのや」さんでグルメ　紅葉の絶景巡り', 'イーザイル', 11333, ''),
  ('JFbBFI6A2EM', 'https://www.youtube.com/watch?v=JFbBFI6A2EM', 'ZX‐10R 群馬 妙義山とコスモス街道【ツーリング】', 'RY×バイク旅', 11248, ''),
  ('0Kb8oFsGISk', 'https://www.youtube.com/watch?v=0Kb8oFsGISk', '【関東・甲信越 絶景ドライブ】一度は走りたい絶景ロード18選｜富士山・箱根・ビーナスライン・房総', 'Holiday Ideas', 10619, '07:59'),
  ('mighIvp-tqE', 'https://www.youtube.com/watch?v=mighIvp-tqE', '下道1日で何キロ走れる？ボアアップGROM絶景ツーリング(信州･群馬編)', 'sharin-jin', 6717, ''),
  ('2YEU9igU46Y', 'https://www.youtube.com/watch?v=2YEU9igU46Y', '上りが遅すぎるモンキー125で妙義山ツーリング！アイドリング調整したのに電圧不足な件は経過観察中…', 'ゼキザップ_モトブログ', 5956, ''),
  ('DIXu9NY7xcw', 'https://www.youtube.com/watch?v=DIXu9NY7xcw', '群馬の春旅！もうすぐ満開の妙義山河津桜と下仁田グルメ満喫ドライブ2026', 'ゼキザップ_モトブログ', 4065, '02:11'),
  ('Bhy95P9eoL8', 'https://www.youtube.com/watch?v=Bhy95P9eoL8', '妙義山ツーリング 日本三大奇景の岩石は圧倒される迫力', 'Tsuka Walker', 2454, ''),
  ('3xv4V81N3VU', 'https://www.youtube.com/watch?v=3xv4V81N3VU', '妙義山の紅葉が大迫力！モンキー125で下仁田グルメと走りを満喫ツーリング', 'ゼキザップ_モトブログ', 2426, '03:03'),
  ('L1hjsfSLifU', 'https://www.youtube.com/watch?v=L1hjsfSLifU', '【YZF‐R1】遭遇！！ナンシーおじさん！！【ツーリング】', 'RY×バイク旅', 2422, '08:40'),
  ('qajyqlev2J8', 'https://www.youtube.com/watch?v=qajyqlev2J8', '【YZF‐R1】道の駅巡り【関東】', 'RY×バイク旅', 772, '')
) as v(video_id, url, title, channel, view_count, ts)
