insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('中之嶽神社', 'other', 36.283806, 138.737389, '中之嶽神社（なかのたけじんじゃ）は、群馬県甘楽郡下仁田町上小坂にある神社である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/Nakanotake_Shrine.JPG/960px-Nakanotake_Shrine.JPG', 'Wikipedia', 'wikipedia'),
  ('妙義神社', 'other', 36.300472, 138.762389, '妙義神社（みょうぎじんじゃ）は、群馬県富岡市にある神社である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Myogi-jinja_Haiden-Heiden-Honden_2.jpg/960px-Myogi-jinja_Haiden-Heiden-Honden_2.jpg', 'Wikipedia', 'wikipedia'),
  ('道の駅 みょうぎ', 'rest', 36.299307, 138.765961, '妙義山の麓にある道の駅', 'seed_auto', 'JFbBFI6A2EM', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/Myogi-jinja_Otorii.jpg/960px-Myogi-jinja_Otorii.jpg', 'photo: Qurren (talk) Taken with Canon IXY 10S (Digital IXUS 210) / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('道の駅みょうぎ', 'rest', 36.299670, 138.765970, '道の駅みょうぎ（みちのえき みょうぎ）は、群馬県富岡市にある群馬県道196号上小坂四ツ家妙義線の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Michinoeki_myogi.jpg/960px-Michinoeki_myogi.jpg', 'Wikipedia', 'wikipedia'),
  ('妙義さくらの里', 'viewpoint', 36.282526, 138.742932, '妙義山道路沿いにある河津桜の名所', 'seed_auto', 'DIXu9NY7xcw', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/Myogisan_Sakurano_Sato_-_panoramio.jpg/960px-Myogisan_Sakurano_Sato_-_panoramio.jpg', 'Koichi Shibata / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('妙義公園駐車場', 'viewpoint', 36.282500, 138.738829, '妙義山道路沿いの絶景駐車場', 'seed_auto', 'DIXu9NY7xcw', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Mt-myogi-in-summer.jpg/960px-Mt-myogi-in-summer.jpg', 'Jesse Fuller / CC BY-SA 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:妙義山道路'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('高ボッチスカイライン', '富士山・諏訪湖・アルプスが一望できる高ボッチ高原へ登る山岳ルート。途中の道はやや狭く酷道気味ですが頂上からの展望は抜群です。
注意: 松本市側へ下る道は酷い悪路・細道。車幅・対向車に注意。 / 冬季閉鎖あり。塩尻峠側（東側）ルートの通行止め等、道路状況に注意。鉢伏山荘付近は有料駐車場あり。 / 冬季閉鎖あり。諏訪・塩尻峠側からのアクセスルートは通行止めの可能性あり / 狭隘区間・急勾配あり。冬季閉鎖あり / 道幅が狭い区間あり / 冬期閉鎖あり、道幅が狭く対向車に注意 / 道幅が狭くすれ違い注意。冬季閉鎖あり / 冬期閉鎖あり、狭隘区間あり / ウシアブなどの虫が多い / 冬季閉鎖あり。道幅が狭く路面凹凸あり
