insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('冨具神社', 'other', 34.764028, 136.843833, '冨具神社（ふぐじんじゃ）は、愛知県知多郡美浜町大字野間にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/Fugu_Shrine_in_Mihama_Town.jpg/960px-Fugu_Shrine_in_Mihama_Town.jpg', 'Wikipedia', 'wikipedia'),
  ('如意輪寺', 'other', 34.739667, 136.873611, '如意輪寺（にょいりんじ）は、愛知県知多郡南知多町内海中之郷12にある真言宗豊山派の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Nyoirin-ji_main_hall_ac_%281%29.jpg/960px-Nyoirin-ji_main_hall_ac_%281%29.jpg', 'Wikipedia', 'wikipedia'),
  ('廻船と音吉記念館', 'other', 34.750778, 136.852389, '廻船と音吉記念館（かいせんとおときちきねんかん）は、愛知県知多郡美浜町にある私設博物館（記念館）。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/%E6%97%A5%E5%90%89%E8%8B%91_%E5%88%BA%E3%81%97%E7%9B%9B%E3%82%8A_%E4%B8%AD_-_panoramio.jpg/960px-%E6%97%A5%E5%90%89%E8%8B%91_%E5%88%BA%E3%81%97%E7%9B%9B%E3%82%8A_%E4%B8%AD_-_panoramio.jpg', 'gundam2345 / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('羽豆神社', 'other', 34.696389, 136.972194, '羽豆神社（はずじんじゃ）は、愛知県知多郡南知多町大字師崎字明神山に鎮座する神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/87/Hazu_Shrine_121027.JPG/960px-Hazu_Shrine_121027.JPG', 'Wikipedia', 'wikipedia'),
  ('羽豆神社の社叢', 'other', 34.695861, 136.972056, '羽豆神社の社叢（はずじんじゃのしゃそう）は、愛知県知多郡南知多町師崎に鎮座する羽豆神社の境内にある、国の天然記念物に指定された社叢（鎮守の森）である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Morozaki_Hazu_Cape_2019-06_ac.jpg/960px-Morozaki_Hazu_Cape_2019-06_ac.jpg', 'Wikipedia', 'wikipedia'),
  ('西岸寺', 'other', 34.735222, 136.871306, '西岸寺（せいがんじ）は、愛知県知多郡南知多町内海浦向60にある西山浄土宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/Seigan-ji_Utsumi_main_hall_ac_%281%29.jpg/960px-Seigan-ji_Utsumi_main_hall_ac_%281%29.jpg', 'Wikipedia', 'wikipedia'),
  ('野間神社', 'other', 34.810278, 136.863250, '野間神社（のまじんじゃ）は、愛知県知多郡美浜町大字上野間にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/MT-Kaminoma-station-closed-track-no2-001.jpg/960px-MT-Kaminoma-station-closed-track-no2-001.jpg', 'HQA02330 / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('つぶて浦', 'viewpoint', 34.728467, 136.877475, '鳥居越しのサンセットが綺麗な絶景スポット', 'seed_auto', 'yqMrKihF-KM', 'https://i.ytimg.com/vi/yqMrKihF-KM/hqdefault.jpg', 'YouTube', 'youtube'),
  ('野間埼灯台', 'viewpoint', 34.757781, 136.844533, '野間埼灯台（のまさきとうだい）は、愛知県知多郡美浜町の野間崎に立つ中型灯台である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/Noma_todai_s.jpg/960px-Noma_todai_s.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'num:国道247号:愛知'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

