insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('道の駅つぐ高原グリーンパーク', 'rest', 35.198830, 137.606310, '道の駅つぐ高原グリーンパーク（みちのえき つぐこうげん グリーンパーク）は、愛知県北設楽郡設楽町津具字東山にある愛知県道10号設楽根羽線の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/14/%E9%81%93%E3%81%AE%E9%A7%85_%E3%81%A4%E3%81%90%E9%AB%98%E5%8E%9F%E3%82%B0%E3%83%AA%E3%83%BC%E3%83%B3%E3%83%BB%E3%83%91%E3%83%BC%E3%82%AF.jpg/960px-%E9%81%93%E3%81%AE%E9%A7%85_%E3%81%A4%E3%81%90%E9%AB%98%E5%8E%9F%E3%82%B0%E3%83%AA%E3%83%BC%E3%83%B3%E3%83%BB%E3%83%91%E3%83%BC%E3%82%AF.jpg', 'Wikipedia', 'wikipedia'),
  ('面ノ木ピット', 'rest', 35.189504, 137.591331, '面の木峠付近の休憩スポット', 'seed_auto', '4zqBjXabVq8', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/%E5%A4%A9%E7%8B%97%E6%A3%9A%E3%81%AE%E5%A4%A9%E7%8B%97_-_panoramio.jpg/960px-%E5%A4%A9%E7%8B%97%E6%A3%9A%E3%81%AE%E5%A4%A9%E7%8B%97_-_panoramio.jpg', '菅野崇 / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('井山展望台', 'viewpoint', 35.185556, 137.569111, '風力発電所がある絶景ポイント。車馬乗り入れ不可で徒歩10分程度歩く', 'seed_auto', '9YQiGiWFQQw', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Nishinagura%2C_Shitara%2C_Kitashitara_District%2C_Aichi_Prefecture_441-2431%2C_Japan_-_panoramio_%281%29.jpg/960px-Nishinagura%2C_Shitara%2C_Kitashitara_District%2C_Aichi_Prefecture_441-2431%2C_Japan_-_panoramio_%281%29.jpg', 'ESU / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('茶臼山高原', 'viewpoint', 35.224439, 137.654344, '茶臼山高原道路沿いの絶景スポット', 'seed_auto', '4ramMKzKd9Y', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/%E9%87%91%E3%81%AE%E6%B3%A2_-_panoramio.jpg/960px-%E9%87%91%E3%81%AE%E6%B3%A2_-_panoramio.jpg', 'ESU / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('茶臼山高原 展望駐車場', 'viewpoint', 35.224439, 137.654344, '雲海が見られる絶景の展望駐車場', 'seed_auto', 'ZMcAJbL1N5o', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/%E9%87%91%E3%81%AE%E6%B3%A2_-_panoramio.jpg/960px-%E9%87%91%E3%81%AE%E6%B3%A2_-_panoramio.jpg', 'ESU / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('茶臼山高原スキー場', 'viewpoint', 35.220697, 137.655550, '茶臼山高原スキー場（ちゃうすやまこうげんスキーじょう）は、愛知県北設楽郡豊根村の愛知県最高峰の茶臼山にある愛知県唯一のスキー場である。', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/8/86/Chausuyama02.jpg', 'Wikipedia', 'wikipedia'),
  ('茶臼山高原両生類研究所', 'viewpoint', 35.231111, 137.658583, '茶臼山高原両生類研究所（ちゃうすやまこうげんりょうせいるいけんきゅうじょ）は、長野県下伊那郡根羽村にある自然科学博物館。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e9/Sakauba%2C_Toyone%2C_Kitashitara_District%2C_Aichi_Prefecture_449-0405%2C_Japan_-_panoramio.jpg/960px-Sakauba%2C_Toyone%2C_Kitashitara_District%2C_Aichi_Prefecture_449-0405%2C_Japan_-_panoramio.jpg', 'ESU / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('萩太郎山', 'viewpoint', 35.214194, 137.657722, '萩太郎山（はぎたろうやま）は、愛知県北設楽郡豊根村北西部にある山である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Mount_Hagitaro_from_Mount_Chausu.jpg/960px-Mount_Hagitaro_from_Mount_Chausu.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:茶臼山高原道路'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

