insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('9oMrvvkPrNs', 'https://www.youtube.com/watch?v=9oMrvvkPrNs', '【長野・埼玉】理想とする完璧な白馬を楽しんだツーリング。 そして秩父を目指す  |  SV650', 'STOMP', 52729, ''),
  ('3CeTgrxg7b0', 'https://www.youtube.com/watch?v=3CeTgrxg7b0', '[バイク旅#244] 雨覚悟のバイク旅　群馬県御巣鷹の尾根近くの奥神流湖上野ダムへ　聖地名栗湖からの日帰り旅　おススメもつ煮久保田さん(カレーもつ煮)へ', 'イーザイル', 10632, ''),
  ('FjBGcV4kVxY', 'https://www.youtube.com/watch?v=FjBGcV4kVxY', '[バイク旅#182] 秩父・神流湖バイクツー　入店できた純手打ちうどん「花矢蔵」さんのうどんは凄くうまかった(グルメ)　神流(かんな)湖(絶景)でびっくりハプニング💦　雪解け状態の峠道を走る', 'イーザイル', 7020, ''),
  ('u52kRsm2teU', 'https://www.youtube.com/watch?v=u52kRsm2teU', 'YZF-R1 群馬 十石街道 道の駅巡り【ツーリング】', 'RY×バイク旅', 5510, ''),
  ('fi-2-wq7xY8', 'https://www.youtube.com/watch?v=fi-2-wq7xY8', '幻のデカ盛り！群馬の下仁田カツ丼デススター「れすとらんヒロ」｜シャア専用ハンターカブと孤独のグルメ聖地巡礼ツーリング', 'ゼキザップ_モトブログ', 4953, '04:35'),
  ('Vw3BwaQUPv0', 'https://www.youtube.com/watch?v=Vw3BwaQUPv0', 'モンキー125って実は燃費悪い？冬の国道299号志賀坂峠ツーリングと、実燃費報告…夏と冬の燃費差に驚いてます', 'ゼキザップ_モトブログ', 3746, '04:18'),
  ('wPVxvWHc0PE', 'https://www.youtube.com/watch?v=wPVxvWHc0PE', '群馬の紅葉穴場スポット紹介！上野村～御荷鉾スーパー林道をモンキー125でツーリング', 'ゼキザップ_モトブログ', 2939, '03:17'),
  ('FJA2yV43O9I', 'https://www.youtube.com/watch?v=FJA2yV43O9I', '【モトブログ】絶景道路で神流川を巡り ノスタルジックな街で絶品ローカルグルメ 下仁田カツ丼を喰らうツーリング', '練り物ちっくーモトブログ', 2432, '02:07'),
  ('6Ekd6I8KqUc', 'https://www.youtube.com/watch?v=6Ekd6I8KqUc', '【モトブログ】ジャンルごちゃ混ぜ とにかく走った春の群馬250km 自然 歴史 グルメ 廃墟 花 峠 絶景 新道ツーリング', '練り物ちっくーモトブログ', 925, ''),
  ('O8w_wcHA0Ts', 'https://www.youtube.com/watch?v=O8w_wcHA0Ts', '埼玉群馬の絶景ルート　初冬のツーリングはここで決まり！　北関東紅葉ツーリング　神流川　上野', 'ぴーちゃんバイクTV', 330, '')
) as v(video_id, url, title, channel, view_count, ts)
