insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('9zkDdfPsMNA', 'https://www.youtube.com/watch?v=9zkDdfPsMNA', '【恥ずかしくて入れない秘湯】長野県の道路沿いにある塩生乙の冷鉱泉と迫力の小田切ダム｜モンキー125ツーリング', 'ゼキザップ_モトブログ', 32453, '01:05'),
  ('nTO0Zrb0RG4', 'https://www.youtube.com/watch?v=nTO0Zrb0RG4', '【白馬村】絶対一度は訪れたい！日本一美しい村は期待以上だった！｜長野観光｜モトブログ', 'バイクで旅するまりさん 【Mari''s  motorcycle Vlog / ninja 650】', 30018, '12:12'),
  ('Zon-HidfaAg', 'https://www.youtube.com/watch?v=Zon-HidfaAg', '信州、長野県　小川村　旅でしか出会えない風景をもとめて撮影旅　vol.42　小さなバイクでバイクツーリング　Ogawa village Nagano Japan Shinsyu', 'photographer関野温の撮影旅', 19537, '01:54'),
  ('ZhmaI5KKJp8', 'https://www.youtube.com/watch?v=ZhmaI5KKJp8', '【長野・白馬】絶対に外せない長野の最高ツーリングスポットはここ！｜バイク女子｜モトブログ', 'バイクで旅するまりさん 【Mari''s  motorcycle Vlog / ninja 650】', 18956, '05:59'),
  ('IKQLw7VXsPE', 'https://www.youtube.com/watch?v=IKQLw7VXsPE', '【長野・戸隠】神秘と奇跡の戸隠！圧巻の絶景と美味しいランチ！｜長野観光｜モトブログ', 'バイクで旅するまりさん 【Mari''s  motorcycle Vlog / ninja 650】', 10730, '01:22'),
  ('hNAstMKLa04', 'https://www.youtube.com/watch?v=hNAstMKLa04', '4/12春の絶景！小川村【小川アルプスライン2026】「番所の桜」「立屋の桜」「二反田の桜」や「小川村アルプス展望広場」「小川アルプスライン成就展望所」「穴場の北アルプス絶景スポット」バイクツーリング', 'おでかけポコ', 10331, '06:23'),
  ('YNkRWh-xrjo', 'https://www.youtube.com/watch?v=YNkRWh-xrjo', '超オススメ！北アルプスの絶景スポット3選。白馬の白沢洞門と大望峠展望台、アルプス展望広場夢の駅で鯉のぼりと菜の花のコラボは最高｜モンキー125ツーリング', 'ゼキザップ_モトブログ', 6118, '10:47'),
  ('Ib3LnBghGJk', 'https://www.youtube.com/watch?v=Ib3LnBghGJk', '白馬の絶景巡りで初めて声を掛けられビックリ！', 'sharin-jin', 4328, ''),
  ('Wj4o9ZnlmtU', 'https://www.youtube.com/watch?v=Wj4o9ZnlmtU', '北アルプスの王道絶景ライン「小川アルプスライン」', 'sharin-jin', 3747, '00:17'),
  ('9iIPrVMRQhk', 'https://www.youtube.com/watch?v=9iIPrVMRQhk', 'カンナムスパイダーツーリング　信州のアルプスを望む絶景ロードを堪能する', 'MASAKOIスパイダーツーリング', 3110, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
