insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('bfuiqGhwZqw', 'https://www.youtube.com/watch?v=bfuiqGhwZqw', '【絶景】群馬の秘境は異次元だった。｜毛無峠〜志賀草津高原道路（渋峠）｜群馬ツーリング Final｜YAMAHA SR400【モトブログ】', 'Matt RiderJapan', 84938, '02:56'),
  ('LWdvQfWUUnY', 'https://www.youtube.com/watch?v=LWdvQfWUUnY', '[ 関東編 ] バイクで走る関東地方の首都圏圧巻のツーリングコース20選★人生で一度は走りたい最高の道！#絶景ロード #東京', 'I Am Rider', 23880, ''),
  ('hB2k-ET9ly8', 'https://www.youtube.com/watch?v=hB2k-ET9ly8', '開通日走行【志賀草津道路2026】雪の回廊は？草津側通行止めの罠！開通区間約10kmで満足できない人のための絶景3ルート', 'おでかけポコ', 16212, ''),
  ('Nqy2TJqfaRE', 'https://www.youtube.com/watch?v=Nqy2TJqfaRE', '【群馬～長野バイク旅】万座から日本一高い絶景の国道292号経由で信州へ！ゴールドウイング6台で天空の峠道と信州グルメを堪能するツーリング。【HONDA Gold Wing/モトブログ】', '突然rider', 11737, ''),
  ('dGz6jTVspEs', 'https://www.youtube.com/watch?v=dGz6jTVspEs', '冬季閉鎖カウントダウン【志賀草津道路】2025年絶景見納め！日本国道最高地点から日の出見る為、夜の志賀草津ルートを走ってきた～途中の上信自動車道通行止め情報＋万座ハイウェー情報などもあります', 'おでかけポコ', 10800, ''),
  ('fBnauvso-j4', 'https://www.youtube.com/watch?v=fBnauvso-j4', '最低気温-2℃！下道日帰り460km激走の全記録。志賀草津道路からビーナスラインを同日制覇する「変態的」走行ドキュメント～群馬県桐生市発', 'おでかけポコ', 7738, ''),
  ('yQlY23uHWNQ', 'https://www.youtube.com/watch?v=yQlY23uHWNQ', 'グロムで日帰り730km！秘境の絶景「毛無峠」へ', 'sharin-jin', 6578, '0:15'),
  ('IC2rzMeITPM', 'https://www.youtube.com/watch?v=IC2rzMeITPM', '【雪の回廊ツーリング】開通したばかりの志賀草津高原ルート、雪の回廊にハヤブサで行ってきました。5メートル程の積雪がある雪の回廊は見応えがありました（モトブログ）', 'モトケンチャンネル', 1645, ''),
  ('Gy45P9gwDYQ', 'https://www.youtube.com/watch?v=Gy45P9gwDYQ', '【WR250X】峠ばかりの欲張りコースでソロツーリング【長野群馬ラストラン】', 'Tsuka Walker', 1637, ''),
  ('1fAA6RBCBsc', 'https://www.youtube.com/watch?v=1fAA6RBCBsc', '【2022年】首都圏発！圧倒的ゴールデンウィークにおすすめの絶景ツーリングロード５選', '圧倒的バイクチャンネル', 1039, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
