select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('v7AJxY8KSR8', 'https://www.youtube.com/watch?v=v7AJxY8KSR8', '初日から失敗する俳優【北陸キャンプツーリング】1日目', '森キャンプ公平', 117829, ''),
  ('tAamuscFw_k', 'https://www.youtube.com/watch?v=tAamuscFw_k', '【GIXXER250】魚沼スカイライン走ってみた【ソロツーリング】', '庵屋豆腐店', 14988, ''),
  ('JARdIAe9e_k', 'https://www.youtube.com/watch?v=JARdIAe9e_k', '【気温差20℃】残暑の群馬・長野・新潟の快走路ツーリング！【V-Strom250SX 】', 'へいぞうバイク旅', 12900, ''),
  ('9dpXuf6vPEo', 'https://www.youtube.com/watch?v=9dpXuf6vPEo', '【バイク旅】福島の尾瀬から酷道352号線の枝折峠経由で新潟へ！秘境区間の広大な大自然に感動するツーリング。十日町にある隠れた名店のグルメも満喫しました【Honda Gold Wing/モトブログ】', '突然rider', 11906, ''),
  ('MpQtnoU9cKM', 'https://www.youtube.com/watch?v=MpQtnoU9cKM', '【越後】秘境！秋山郷510km下道日帰りツーリング【信州】', 'へいぞうバイク旅', 11365, ''),
  ('Uezf_RHBV74', 'https://www.youtube.com/watch?v=Uezf_RHBV74', '【ソロツーリング】新潟・長野・群馬を縦断してみた! / 魚沼スカイライン 奥志賀林道 志賀草津高原ルート【日本2/3横断】', 'Tsuka Walker', 6346, ''),
  ('KOSHBPZ4Xhk', 'https://www.youtube.com/watch?v=KOSHBPZ4Xhk', 'モンキー125の燃費が良すぎる…けど誤差というか安全率高い設計⁉奥志賀林道に続いて魚沼スカイラインも通行止めで、思い通りにいかないロングツーリング', 'ゼキザップ_モトブログ', 5813, ''),
  ('3nZvdzucTfA', 'https://www.youtube.com/watch?v=3nZvdzucTfA', '走って最高！CBR650R新潟ツーリング！弥彦神社〜魚沼スカイライン', 'なちの週末バイク旅', 2466, ''),
  ('Bm99eRfDgj8', 'https://www.youtube.com/watch?v=Bm99eRfDgj8', '【2泊3日東北ツーリング】1日目は魚沼の有名ツーリングコースと日本海の夕日を眺める | Bonneville T120', 'ゆきだま', 1193, ''),
  ('MP5rX2XVWR8', 'https://www.youtube.com/watch?v=MP5rX2XVWR8', '【新潟】魚沼スカイライン絶景ソロ旅！｜喋り・テロップ一切なしの純粋なバイクツーリング動画［大沢〜R353］山間部の快走路で響くリアルなエンジン音と風切り音だけを堪能する没入型映像 #191', 'Japan Moto Adventures', 187, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('天昌寺', 'other', 37.055422, 138.847364, '天昌寺（てんしょうじ）は、新潟県南魚沼市思川にある曹洞宗の寺院。', 'wikipedia', '', 'https://i.ytimg.com/vi/v7AJxY8KSR8/hqdefault.jpg', 'YouTube', 'youtube'),
  ('薬照寺', 'other', 37.009444, 138.811944, '薬照寺（やくしょうじ）は、新潟県南魚沼市君沢にある真言宗智山派の寺院である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Yakusho-ji_%28Minamiuonuma%29.JPG/960px-Yakusho-ji_%28Minamiuonuma%29.JPG', 'Wikipedia', 'wikipedia'),
  ('関興寺', 'other', 36.989361, 138.797639, '関興寺（かんこうじ）は、新潟県南魚沼市上野にある臨済宗円覚寺派の寺院である。', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/b/b6/Kanjoji.JPG', 'Wikipedia', 'wikipedia'),
  ('十二峠', 'pass', 36.985299, 138.767816, '魚沼スカイラインに接続する峠としてコメントで言及', 'seed_auto', 'tAamuscFw_k', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/%E9%AD%9A%E6%B2%BC%E3%82%B9%E3%82%AB%E3%82%A4%E3%83%A9%E3%82%A4%E3%83%B3_-_panoramio.jpg/960px-%E9%AD%9A%E6%B2%BC%E3%82%B9%E3%82%AB%E3%82%A4%E3%83%A9%E3%82%A4%E3%83%B3_-_panoramio.jpg', 'Yobito KAYANUMA / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('道の駅南魚沼', 'rest', 37.002940, 138.819170, '道の駅南魚沼（みちのえき みなみうおぬま）は、新潟県南魚沼市下一日市にある国道17号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/Michinoeki_MinamiUonuma.JPG/960px-Michinoeki_MinamiUonuma.JPG', 'Wikipedia', 'wikipedia'),
  ('清津峡', 'viewpoint', 36.961572, 138.757364, '観光で立ち寄った日本三大峡谷の景勝地', 'seed_auto', 'v7AJxY8KSR8', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/%E6%B8%85%E6%B4%A5%E5%B3%A1_%E5%86%AC_-_panoramio.jpg/960px-%E6%B8%85%E6%B4%A5%E5%B3%A1_%E5%86%AC_-_panoramio.jpg', 'Arichika Taniguchi / CC BY-SA 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:魚沼スカイライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

