insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('大塚国際美術館', 'other', 34.232528, 134.637722, '大塚国際美術館（おおつかこくさいびじゅつかん, 英語: The Otsuka Museum of Art）は、徳島県鳴門市の鳴門公園内にある、陶板複製画を中心とした美術館。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/The_Otsuka_Museum_of_Art20s3203-B-T.jpg/960px-The_Otsuka_Museum_of_Art20s3203-B-T.jpg', 'Wikipedia', 'wikipedia'),
  ('徳島県立大鳴門橋架橋記念館', 'other', 34.234917, 134.640139, '徳島県立 大鳴門橋架橋記念館（とくしまけんりつ おおなるときょうかきょうきねんかん、英称：Ohnaruto Bridge Crossing Memorial Hall）は、大鳴門橋架橋を記念して徳島県鳴門市鳴門町土佐泊浦に設置された施設であ', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/EDDY02s3872.jpg/960px-EDDY02s3872.jpg', 'Wikipedia', 'wikipedia'),
  ('大毛山', 'viewpoint', 34.224472, 134.619972, '大毛山（おおげやま）は、徳島県鳴門市の大毛島に位置する山である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Narutokita-exit.jpg/960px-Narutokita-exit.jpg', 'Takuwanbento1098 / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('鳴門山', 'viewpoint', 34.237056, 134.640139, '鳴門山（なるとやま）は、徳島県鳴門市の大毛島に位置する山である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Naruto_Strait_near_Kameura_Tourist_Port_2.JPG/960px-Naruto_Strait_near_Kameura_Tourist_Port_2.JPG', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:鳴門スカイライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

