insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('3f9QK5PZDU0', 'https://www.youtube.com/watch?v=3f9QK5PZDU0', '【2026最新道路開通情報】GWに行くべき絶景道路が続々冬季閉鎖解除開通！「東日本・最強ツーリングドライブルート」＊群馬から日帰り一泊で行ける範囲', 'おでかけポコ', 32155, ''),
  ('yr28e1wtED0', 'https://www.youtube.com/watch?v=yr28e1wtED0', '狭すぎる群馬と埼玉の県境。神水ダムと落石多数の御荷鉾スーパー林道｜CT125ハンターカブツーリング', 'ゼキザップ_モトブログ', 10253, '04:40'),
  ('3aul07Wonk0', 'https://www.youtube.com/watch?v=3aul07Wonk0', '[バイク旅#156] 夏だバイクだ林道だ　御荷鉾スーパー林道(舗装路)：林道ツー特集Part1 　峠のうどん屋「藤屋」さんの「天ぷらうどん」はうまいっ！', 'イーザイル', 5133, ''),
  ('fi-2-wq7xY8', 'https://www.youtube.com/watch?v=fi-2-wq7xY8', '幻のデカ盛り！群馬の下仁田カツ丼デススター「れすとらんヒロ」｜シャア専用ハンターカブと孤独のグルメ聖地巡礼ツーリング', 'ゼキザップ_モトブログ', 4953, ''),
  ('duSl5UhIoao', 'https://www.youtube.com/watch?v=duSl5UhIoao', '1泊2日絶景林道とキャンプツーリング｜長野県～群馬県の林道めぐり｜WR250R', 'Ride with me -僕と彼女と週末に-', 4049, '13:21'),
  ('niGIjAkzSws', 'https://www.youtube.com/watch?v=niGIjAkzSws', 'ハンターカブは悪路走行が楽しい！雨上がりの御荷鉾スーパー林道マスツーリングの予定が…集合場所に誰もいなくてショック編', 'ゼキザップ_モトブログ', 3451, ''),
  ('wPVxvWHc0PE', 'https://www.youtube.com/watch?v=wPVxvWHc0PE', '群馬の紅葉穴場スポット紹介！上野村～御荷鉾スーパー林道をモンキー125でツーリング', 'ゼキザップ_モトブログ', 2939, '06:09'),
  ('hkhDmB7QaZ0', 'https://www.youtube.com/watch?v=hkhDmB7QaZ0', 'ハンターカブが可哀そう…雨上がりの御荷鉾スーパー林道で泥だらけになって楽しんだツーリング', 'ゼキザップ_モトブログ', 2658, ''),
  ('3xv4V81N3VU', 'https://www.youtube.com/watch?v=3xv4V81N3VU', '妙義山の紅葉が大迫力！モンキー125で下仁田グルメと走りを満喫ツーリング', 'ゼキザップ_モトブログ', 2426, '00:00'),
  ('7-R-3ahSXjE', 'https://www.youtube.com/watch?v=7-R-3ahSXjE', '【秩父バイク旅#5】美の山公園から秩父を一望してみた。御荷鉾スーパー林道から国道299号線の峠道を経由して絶景スポットへ行くソロツーリング【WR250X】', 'Tsuka Walker', 942, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
