insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('太田川橋', 'other', 34.678144, 137.896353, '太田川を渡る橋', 'seed_auto', 'CbEsJAakRWE', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Otagawa_Bashi_20140823-2.JPG/960px-Otagawa_Bashi_20140823-2.JPG?utm_source=ja.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia', 'wikipedia'),
  ('渚の交流館', 'rest', 34.667391, 137.909626, 'ツーリングの出発地点', 'seed_auto', 'CbEsJAakRWE', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Toyohama%2C_Iwata%2C_Shizuoka_Prefecture_437-1202%2C_Japan_-_panoramio.jpg/960px-Toyohama%2C_Iwata%2C_Shizuoka_Prefecture_437-1202%2C_Japan_-_panoramio.jpg', 'tinbotu / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('遠州大橋', 'viewpoint', 34.662003, 137.786386, '天竜川を渡る大きな橋', 'seed_auto', 'Iqao7g-tEZw', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6a/%E9%81%A0%E5%B7%9E%E5%A4%A7%E6%A9%8B%EF%BC%88%E6%96%B0%E6%8E%9B%E5%A1%9A%E6%A9%8B%EF%BC%89.jpg/960px-%E9%81%A0%E5%B7%9E%E5%A4%A7%E6%A9%8B%EF%BC%88%E6%96%B0%E6%8E%9B%E5%A1%9A%E6%A9%8B%EF%BC%89.jpg?utm_source=ja.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'num:国道150号:静岡'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

