insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('佐多岬', 'viewpoint', 30.997255, 130.659107, '佐多岬ロードパークの先にある本土最南端の絶景スポット', 'seed_auto', '0dfjZJMDbW0', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/%E4%BD%90%E5%A4%9A%E5%B2%AC_-_panoramio_%281%29.jpg/960px-%E4%BD%90%E5%A4%9A%E5%B2%AC_-_panoramio_%281%29.jpg', 'rintarow / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('佐多岬展望台', 'viewpoint', 30.997255, 130.659107, '本土最南端の絶景展望台', 'seed_auto', 'irTBESEuOUY', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/Sata-misaki_ruin_%E4%BD%90%E5%A4%9A%E5%B2%AC%E5%B1%95%E6%9C%9B%E5%8F%B0%E8%B7%A1_%28299830919%29.jpg/960px-Sata-misaki_ruin_%E4%BD%90%E5%A4%9A%E5%B2%AC%E5%B1%95%E6%9C%9B%E5%8F%B0%E8%B7%A1_%28299830919%29.jpg', 'Yamaguchi Yoshiaki from Japan / CC BY-SA 2.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:佐多岬ロードパーク'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('東京ゲートブリッジ', '東京湾にかかる巨大なトラス構造の橋で、東京臨海エリアの煌びやかな夜景とダイナミックな橋梁美を堪能できる開放感あふれる区間です。
