insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('奥入瀬渓流温泉', 'onsen', 40.578860, 140.995000, '奥入瀬渓流温泉（おいらせけいりゅうおんせん）は、青森県十和田市にある温泉郷。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Oirase_Keiryu_Hotel_-_Oirase_Mountain_Stream_-_Towada%2C_Aomori_-_DSC00853.jpg/960px-Oirase_Keiryu_Hotel_-_Oirase_Mountain_Stream_-_Towada%2C_Aomori_-_DSC00853.jpg', 'Wikipedia', 'wikipedia'),
  ('焼山温泉', 'onsen', 40.578920, 140.995080, '焼山温泉（やけやまおんせん）は、青森県十和田市の奥入瀬渓流温泉（旧十和田湖温泉郷）にある温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Aomori_Prefectural_Police_Yakeyama_Police_Box.jpg/960px-Aomori_Prefectural_Police_Yakeyama_Police_Box.jpg', 'mrpbps / CC BY 2.0 / Wikimedia Commons', 'commons'),
  ('子ノ口', 'rest', 40.478838, 140.940727, '', 'seed_auto', 'IaBZ4FX_1Q0', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/JR_Bus_Nenokuchi_Station.jpg/960px-JR_Bus_Nenokuchi_Station.jpg', '掬茶 / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('銚子大滝', 'viewpoint', 40.488436, 140.950525, '', 'seed_auto', 'IaBZ4FX_1Q0', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Oirase_Stream_Waterfall_%E9%8A%9A%E5%AD%90%E5%A4%A7%E6%BB%9D%28%E3%81%A1%E3%82%87%E3%81%86%E3%81%97%E3%81%8A%E3%81%8A%E3%81%9F%E3%81%8D%29.jpg/960px-Oirase_Stream_Waterfall_%E9%8A%9A%E5%AD%90%E5%A4%A7%E6%BB%9D%28%E3%81%A1%E3%82%87%E3%81%86%E3%81%97%E3%81%8A%E3%81%8A%E3%81%9F%E3%81%8D%29.jpg', 'TANAKA Juuyoh (田中十洋) / CC BY 2.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:奥入瀬渓流'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

