insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('IGOUZinIMQY', 'https://www.youtube.com/watch?v=IGOUZinIMQY', '【本栖ツーリング】大型バイクで断念したあの酷道をCL250で挑んできました。【 HONDA CL250 / モトブログ 】', 'ESPRESSO RIDER / エスプレッソライダー ', 40851, '18:19'),
  ('TVQnn0Y2bSo', 'https://www.youtube.com/watch?v=TVQnn0Y2bSo', 'Z900RS 山梨 南部町 そば処ひのき なんぶの湯【ツーリング】', 'RY×バイク旅', 16179, '07:40'),
  ('xOpKsnVHh5w', 'https://www.youtube.com/watch?v=xOpKsnVHh5w', 'Z900RS 静岡 海と富士山で心を整える【ツーリング】', 'RY×バイク旅', 7942, '15:40'),
  ('IhVdNxWtPYg', 'https://www.youtube.com/watch?v=IhVdNxWtPYg', '[バイク旅#118]湖北ビューラインから本栖湖みちの絶景富士山　下部温泉郷からの山越えチャレンジ失敗　鹿に出会って馬鹿丼に挑戦するｗ', 'イーザイル', 1857, ''),
  ('O7XnExP3khc', 'https://www.youtube.com/watch?v=O7XnExP3khc', '秋の山梨・絶景ルート(甲州いろは坂/富士川西部広域農道)！CT125ハンターカブで、ゆるキャン△聖地巡礼ツーリング', 'ゼキザップ_モトブログ', 1787, '01:30'),
  ('IGL64PDzfow', 'https://www.youtube.com/watch?v=IGL64PDzfow', 'ツーリング におススメ！日蓮宗総本山 身延山 久遠寺 ゆるキャン△ リンちゃんのスクーター登場！レブル1100＃旅好きライダーチャンネル＃身延山＃久遠寺＃日蓮宗総本山＃レブル1100＃ゆるキャン△', '旅好きライダーチャンネル', 1430, ''),
  ('NxdNy0kDo8k', 'https://www.youtube.com/watch?v=NxdNy0kDo8k', '【ちょっと残念】富士山の周辺をハーレーでツーリング！バイク/モトブログ', 'イチロクのハーレーちゃんねる', 1215, '05:23'),
  ('KIeWwJe5wIU', 'https://www.youtube.com/watch?v=KIeWwJe5wIU', 'ゆるキャン△ レブル 聖地巡礼  本栖高校 ふもとっぱら 浩庵 キャンプ場＃身延町＃旅好きライダーチャンネル＃レブル＃ゆるキャン△＃聖地巡礼＃本栖高校＃浩庵#ふもとっぱら', '旅好きライダーチャンネル', 463, ''),
  ('BptZ26JRnoU', 'https://www.youtube.com/watch?v=BptZ26JRnoU', 'ハンター＆クロスカブ「カブツーリング 紅葉の本栖・身延」(絶景ツーリングVol.72)', 'ZKライダー', 148, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
