insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('JzWMcH2tHDw', 'https://www.youtube.com/watch?v=JzWMcH2tHDw', '【大阪発！関西ツーリングルート10選！】半日程度で楽しめるお手軽ツーリング【大阪・京都・和歌山・奈良・兵庫】【原付二種OK】', 'サルカブ', 241724, '04:47'),
  ('BktWRNCml0I', 'https://www.youtube.com/watch?v=BktWRNCml0I', '【ジクサー150】日帰り鯖街道ツーリング 木陰の快走路を走る！（神戸～京都～小浜）', 'み山の雑記帳', 37583, ''),
  ('DVHmAcDbCKk', 'https://www.youtube.com/watch?v=DVHmAcDbCKk', '#1【京都・滋賀】梅雨入り前に日帰り450kmツーリング |  鈴鹿スカイライン 〜 美山かやぶきの里 | SV650', 'STOMP', 36430, ''),
  ('_644UNPm_Is', 'https://www.youtube.com/watch?v=_644UNPm_Is', 'スーパーカブ110(JA44)で大阪から京都美山まで200km！真夏の灼熱ツーリング！？[美山かやぶきの里/道の駅 美山ふれあい広場/スプリングスひよし]', 'サルカブ', 21215, ''),
  ('dkNl5Um4uNE', 'https://www.youtube.com/watch?v=dkNl5Um4uNE', '#2【京都・滋賀】梅雨入り前に日帰り450kmツーリング |  メタセコイア並木〜 海津大崎 | SV650', 'STOMP', 13599, ''),
  ('4554-QuFgok', 'https://www.youtube.com/watch?v=4554-QuFgok', '【関西ツーリング聖地】龍神スカイラインの大展望にスーパーカブで行ったら想像以上だった。', 'そそそのバイク旅TV', 2482, ''),
  ('LSgctU9Ld9k', 'https://www.youtube.com/watch?v=LSgctU9Ld9k', '京都 の美しい町 かやぶきの里 美山町 / 出雲大神宮 縁結び 商売繫盛 レブル1100#旅好きライダーチャンネル ＃かやぶきの里＃美山町＃出雲大神宮＃レブル1100＃京都', '旅好きライダーチャンネル', 287, ''),
  ('ySE8rU0WcTQ', 'https://www.youtube.com/watch?v=ySE8rU0WcTQ', '紅葉の快走路　続　北摂から美山へツーリング', 'ゆーでぃームービー', 122, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('丹波マンガン記念館', 'other', 35.199028, 135.650000, '丹波マンガン記念館（たんばマンガンきねんかん）とは、京都市右京区に存在する丹波マンガン鉱山に関する記録を展示したものである。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/%E4%B8%B9%E6%B3%A2%E3%83%9E%E3%83%B3%E3%82%AC%E3%83%B3.jpg/960px-%E4%B8%B9%E6%B3%A2%E3%83%9E%E3%83%B3%E3%82%AC%E3%83%B3.jpg', 'Wikipedia', 'wikipedia'),
  ('福徳寺', 'other', 35.193472, 135.640750, '福徳寺（ふくとくじ）は、京都市右京区京北にある曹洞宗の寺院である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/Fukutoku-ji_%28Kyoto%29%2C_Gate.jpg/960px-Fukutoku-ji_%28Kyoto%29%2C_Gate.jpg', 'Wikipedia', 'wikipedia'),
  ('道の駅ウッディー京北', 'rest', 35.156170, 135.633190, '道の駅ウッディー京北（みちのえき ウッディーけいほく）は、京都府京都市右京区京北周山町上寺田にある国道162号（国道477号重複）の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Michinoeki_WoodyKeihoku.JPG/960px-Michinoeki_WoodyKeihoku.JPG', 'Wikipedia', 'wikipedia'),
  ('道の駅美山ふれあい広場', 'rest', 35.277110, 135.588030, '道の駅美山ふれあい広場（みちのえき みやまふれあいひろば）は、京都府南丹市美山町安掛にある国道162号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/20080816%E9%81%93%E3%81%AE%E9%A7%85%E7%BE%8E%E5%B1%B1%E3%81%B5%E3%82%8C%E3%81%82%E3%81%84%E5%BA%83%E5%A0%B401.jpg/960px-20080816%E9%81%93%E3%81%AE%E9%A7%85%E7%BE%8E%E5%B1%B1%E3%81%B5%E3%82%8C%E3%81%82%E3%81%84%E5%BA%83%E5%A0%B401.jpg', 'Wikipedia', 'wikipedia'),
  ('美山かやぶきの里', 'viewpoint', 35.310520, 135.621637, 'かやぶき屋根の集落が広がる観光スポット', 'seed_auto', 'BktWRNCml0I', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/83/%E3%81%8B%E3%82%84%E3%81%B6%E3%81%8D%E3%81%AE%E9%87%8C%282021-01-02%29_01.jpg/960px-%E3%81%8B%E3%82%84%E3%81%B6%E3%81%8D%E3%81%AE%E9%87%8C%282021-01-02%29_01.jpg', '経済特区 / CC BY-SA 4.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:周山街道'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('国道8号（日本海沿い・糸魚川区間）', '日本海沿いの柏崎市から長岡市にかけて走る幹線道路。信号が少なく海沿いの景色や地元グルメ巡りを楽しめるルートです。
