insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('duLBS9EZt5k', 'https://www.youtube.com/watch?v=duLBS9EZt5k', '#1 【長野・岐阜】GWの予定がダメになったから日帰り500km超えツーリング | SV650', 'STOMP', 54637, ''),
  ('p4vCsqoCPaw', 'https://www.youtube.com/watch?v=p4vCsqoCPaw', '長野の花桃街道と岐阜で初めてのチェアリングを楽しむツーリング | CB1000F', 'STOMP', 15476, ''),
  ('DLneI5_Uzzs', 'https://www.youtube.com/watch?v=DLneI5_Uzzs', '【3/27最新】東秩父村「花桃の郷」＆小川町「桃源郷」お花見見頃ガイド｜駐車場・開花状況・ルート解説【バイクツーリング＆ドライブの行先の参考に】', 'おでかけポコ', 8475, '06:20'),
  ('QMlMZJYyP34', 'https://www.youtube.com/watch?v=QMlMZJYyP34', '4/8撮影【群馬の春の絶景スポットへ】1kmの桜並木と30万株の水仙が満開！からっ風の上武国道を抜けて四万ブルーに吸い込まれる春旅バイクツーリング前編', 'おでかけポコ', 8383, '15:56'),
  ('9BCNmveh2-I', 'https://www.youtube.com/watch?v=9BCNmveh2-I', '長野県&岐阜県「街道ツーリング」阿智村から恵那市にある農村景観日本一の風景を見に、楽しい街道3本を走って行く！', '風鈴ライダー -wind bell rider_motovlog-', 3143, ''),
  ('9dYTwbWb9QA', 'https://www.youtube.com/watch?v=9dYTwbWb9QA', '御岳山の定番の絶景展望台！グロムで弾丸570km', 'sharin-jin', 3002, ''),
  ('zCzPdBbFLSE', 'https://www.youtube.com/watch?v=zCzPdBbFLSE', '御嶽山の裏スカイラインの絶景！はなもも街道！', 'sharin-jin', 2952, '05:15'),
  ('HlBQ1YrUrU0', 'https://www.youtube.com/watch?v=HlBQ1YrUrU0', '長野県「南信州ツーリング」絶景のワインディングロードと日本一の桃源郷に行く！', '風鈴ライダー -wind bell rider_motovlog-', 2916, '')
) as v(video_id, url, title, channel, view_count, ts)
