insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('76pVC13-CFs', 'https://www.youtube.com/watch?v=76pVC13-CFs', '福井の海沿いと山道を楽しむ日帰り460kmのツーリング | CB1000F', 'STOMP', 44202, '03:51'),
  ('F3b_dGDRKjk', 'https://www.youtube.com/watch?v=F3b_dGDRKjk', '【東海・北陸 絶景ドライブ】一度は走りたい絶景ロード14選｜富士山・伊豆・千里浜・伊勢志摩', 'Holiday Ideas', 12693, '06:33'),
  ('69NtoSPeJLM', 'https://www.youtube.com/watch?v=69NtoSPeJLM', '旅の始まり 富山/石川/福井県【北陸編#1(#16)】バイク女子ひとり旅 / ゼファーで日本一周 Motorcycling Around Japan(JP)', 'ともも Travel / 日本一周バイク旅 / Tomomotoblog', 8466, ''),
  ('SqFOAJhbF5s', 'https://www.youtube.com/watch?v=SqFOAJhbF5s', '大阪から２泊３日の北陸（福井・石川）キャンプツーリング', 'Oji〜', 3143, ''),
  ('jS9OnRYKb9k', 'https://www.youtube.com/watch?v=jS9OnRYKb9k', '日本海沿いの絶景の道！  『CB1000F SE 』ソロツーリング2日目', 'NAKAのバイキャンチャンネル', 1913, ''),
  ('LYUgt60mrU0', 'https://www.youtube.com/watch?v=LYUgt60mrU0', '大雨の？しおかぜラインを走り抜け！究極の福井ツーリング【SSTR帰路編】', 'なちの週末バイク旅', 1401, ''),
  ('Q91uS9eZZNk', 'https://www.youtube.com/watch?v=Q91uS9eZZNk', '【北陸海岸編】千里浜なぎさドライブウェイ ここだけ特別の砂浜走行/しおかぜロード 越前海岸/越前そば 辛味大根とのハーモニー /2026GWツーリング ', 'ムーンライダー', 166, '00:54')
) as v(video_id, url, title, channel, view_count, ts)
