insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('フカサワ温泉', 'onsen', 35.636389, 138.535972, 'フカサワ温泉（フカサワおんせん）は、山梨県中巨摩郡昭和町（旧国甲斐国）に存在した温泉、日帰り入浴施設の名。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/%E3%83%95%E3%82%AB%E3%82%B5%E3%83%AF%E6%B8%A9%E6%B3%89.jpg/960px-%E3%83%95%E3%82%AB%E3%82%B5%E3%83%AF%E6%B8%A9%E6%B3%89.jpg', 'Wikipedia', 'wikipedia'),
  ('丸山塚古墳', 'other', 35.593247, 138.580372, '', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/%E4%B8%B8%E5%B1%B1%E5%A1%9A%E5%8F%A4%E5%A2%B3_2008.07.26_-_panoramio_%281%29.jpg/960px-%E4%B8%B8%E5%B1%B1%E5%A1%9A%E5%8F%A4%E5%A2%B3_2008.07.26_-_panoramio_%281%29.jpg', 'alisa_1988_08 / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('大丸山古墳', 'other', 35.592256, 138.583111, '大丸山古墳（おおまるやまこふん）は、山梨県甲府市下曾根にある古墳。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Omaruyama_Kofun%2C_funkyu.jpg/960px-Omaruyama_Kofun%2C_funkyu.jpg', 'Wikipedia', 'wikipedia'),
  ('甲斐銚子塚古墳', 'other', 35.592222, 138.578333, '甲斐銚子塚古墳（かい ちょうしづか こふん）は、山梨県甲府市下曽根町にある前方後円墳。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Kai_Choshizuka_Kofun_zenkei.JPG/960px-Kai_Choshizuka_Kofun_zenkei.JPG', 'Wikipedia', 'wikipedia'),
  ('立石遺跡', 'other', 35.583500, 138.589722, '立石遺跡（たていしいせき）は、山梨県甲府市上向山に所在する旧石器時代初頭から弥生時代、古墳時代にかけての複合遺跡。', 'wikipedia', '', 'https://i.ytimg.com/vi/kLuQjajkUok/hqdefault.jpg', 'YouTube', 'youtube'),
  ('義清神社', 'other', 35.634972, 138.546028, '義清神社（よしきよじんじゃ）は、山梨県中巨摩郡昭和町の神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/Yoshikiyo_Shrine_Syouwa_Town.JPG/960px-Yoshikiyo_Shrine_Syouwa_Town.JPG', 'Wikipedia', 'wikipedia'),
  ('押原公園', 'viewpoint', 35.630556, 138.540000, '押原公園（おしはらこうえん）は山梨県中巨摩郡昭和町にある都市公園（運動公園）である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Kamata_river_habitat_Luciola_cruciata_natural_monument_stone_tablets.JPG/960px-Kamata_river_habitat_Luciola_cruciata_natural_monument_stone_tablets.JPG', 'Sakaori (talk) / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('曽根丘陵公園', 'viewpoint', 35.592222, 138.582500, '山梨県曽根丘陵公園（やまなしけんそねきゅうりょうこうえん）は山梨県甲府市下向山町にある県立の都市公園。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/%E7%94%B2%E6%96%90%E9%A2%A8%E5%9C%9F%E8%A8%98%E3%81%AE%E4%B8%98%E3%81%AE%E9%81%8A%E5%85%B7_-_panoramio.jpg/960px-%E7%94%B2%E6%96%90%E9%A2%A8%E5%9C%9F%E8%A8%98%E3%81%AE%E4%B8%98%E3%81%AE%E9%81%8A%E5%85%B7_-_panoramio.jpg', 'Wikipedia', 'wikipedia'),
  ('精進湖', 'viewpoint', 35.490167, 138.607570, '精進ブルーラインを抜けた先にある富士五湖の1つ', 'seed_auto', 'G2fmLUOWNGU', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/%E7%B2%BE%E9%80%B2%E6%B9%96_-_panoramio_%282%29.jpg/960px-%E7%B2%BE%E9%80%B2%E6%B9%96_-_panoramio_%282%29.jpg', 'funk bass / CC BY 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:精進ブルーライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

