insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('An0RDmDBDL0', 'https://www.youtube.com/watch?v=An0RDmDBDL0', 'いよいよ開通【山王林道(林道奥鬼怒線)】奥日光の紅葉に間に合った！長らく工事通行止めでしたが、工事完了により光徳園地ゲートから川俣温泉ゲートまでの開通日と開通時間を電話で聞いてみました', 'おでかけポコ', 32910, ''),
  ('Zf7y8oNKUUQ', 'https://www.youtube.com/watch?v=Zf7y8oNKUUQ', '【奥日光紅葉2026の参考に】「いろは坂」～黒髪平・明智平・中禅寺湖・華厳の滝・イタリア大使館別荘記念公園・竜頭の滝・戦場ヶ原・光徳園地・湯滝・湯ノ湖・奥日光湯元温泉「金精峠」「山王峠」', 'おでかけポコ', 22302, ''),
  ('LFecZDGtkzo', 'https://www.youtube.com/watch?v=LFecZDGtkzo', '【妻が初めてのいろは坂デビュー】奥日光の秘境と群馬の旬なグルメを満喫するツーリング。納涼スポットもこっそり教えちゃいます。【Rebel1100T/モトブログ】Gold Wing', '突然rider', 14396, ''),
  ('QpHCSGEUtPc', 'https://www.youtube.com/watch?v=QpHCSGEUtPc', '2026奥日光紅葉の参考に「紅葉した山王林道を走って」金精峠～山王峠～川俣温泉～川俣湖～蛇王の滝までの紅葉具合', 'おでかけポコ', 11891, ''),
  ('jSnPPkVYahU', 'https://www.youtube.com/watch?v=jSnPPkVYahU', '2026年【栃木県】真夏に涼しい道路ベスト5 ・絶景スポット・展望地・道路最高地点も紹介！～気象庁データから8月の平均気温を計算！夏のツーリング、ドライブの参考に！', 'おでかけポコ', 5107, ''),
  ('CqsLhbP-8WA', 'https://www.youtube.com/watch?v=CqsLhbP-8WA', '【ソロツーリング】牧場の間を抜ける最高のロードを走ります【奥日光】WR250X 栃木県', 'Tsuka Walker', 4313, ''),
  ('1fAA6RBCBsc', 'https://www.youtube.com/watch?v=1fAA6RBCBsc', '【2022年】首都圏発！圧倒的ゴールデンウィークにおすすめの絶景ツーリングロード５選', '圧倒的バイクチャンネル', 1039, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
