with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('国道1号（東海道・富士バイパス等）', '東京から九州を目指す下道旅の一環として、沼津から豊橋にかけて静岡県を東西に横断する幹線国道区間です。
注意: 長距離の幹線道路で交通量が多く、夜間は寒さや疲労への注意が必要です。 / 長距離走行による疲労、夜間・早朝の寒さ / 夕方の帰宅渋滞あり
（動画 7 本から自動抽出。位置は地図経路による推定）', '静岡県', '道の駅 富士', '興津IC', 'SRID=4326;LINESTRING(138.647340 35.133280, 138.647470 35.133570, 138.648060 35.133400, 138.648090 35.133620, 138.647450 35.133750, 138.646610 35.133350, 138.646070 35.132790, 138.642580 35.131760, 138.641670 35.132500, 138.638850 35.136250, 138.637950 35.137890, 138.634960 35.141300, 138.634420 35.145950, 138.636940 35.147900, 138.636580 35.151390, 138.636720 35.153220, 138.630730 35.152860, 138.629960 35.155570, 138.621450 35.154580, 138.621250 35.154150, 138.621330 35.151430, 138.622100 35.151390, 138.622600 35.149460, 138.623800 35.147840, 138.624490 35.146330, 138.624110 35.142680, 138.624480 35.138200, 138.624240 35.135620, 138.626100 35.131610, 138.626670 35.127190, 138.626580 35.126080, 138.624890 35.125300, 138.623450 35.123590, 138.623170 35.122010, 138.623500 35.118220, 138.622840 35.116830, 138.621570 35.115980, 138.619490 35.115640, 138.602730 35.116040, 138.589780 35.113310, 138.579440 35.112250, 138.576770 35.111780, 138.573510 35.110640, 138.569890 35.107880, 138.567260 35.106320, 138.556820 35.101910, 138.555450 35.100410, 138.553910 35.097550, 138.551470 35.093860, 138.549780 35.090550, 138.548060 35.085830, 138.546470 35.078380, 138.543230 35.073220, 138.542400 35.069660, 138.540900 35.067400, 138.540160 35.064810, 138.537820 35.061870, 138.530520 35.054990, 138.529540 35.054900, 138.526790 35.053180, 138.522410 35.051350, 138.523120 35.050580, 138.527020 35.052590)', 23248, 0.12, true, 'https://www.youtube.com/watch?v=o7lgfIeNKtk', 'しょうたろうモトブログ -Shotaro_Motovlog-', 'seed_auto', 'routed', 'num:国道1号:静岡', 3.05, 1.81, 4.00, 4.00, 3.52, 7)
