insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('二俣城', 'other', 34.862025, 137.808933, '二俣城（ふたまたじょう）は、遠江国豊田郡二俣（静岡県浜松市天竜区二俣町二俣）にあった日本の城（山城）。', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/9/9e/FutamataC_Tenshudai.jpg', 'Wikipedia', 'wikipedia'),
  ('二俣城の戦い', 'other', 34.862030, 137.808930, '二俣城の戦い（ふたまたじょうのたたかい）は、元亀3年（1572年）10月16日から12月19日（正しくは11月30日）にかけて行われた武田信玄軍と徳川家康軍による遠江国北部（現・静岡県）の二俣城攻防戦である。', 'wikipedia', '', 'https://i.ytimg.com/vi/5L3Wcjg7gg8/hqdefault.jpg', 'YouTube', 'youtube'),
  ('本田宗一郎ものづくり伝承館', 'other', 34.866116, 137.814203, 'ホンダの歴史や技術に関する展示がある施設', 'seed_auto', '5L3Wcjg7gg8', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/%E9%A1%98%E6%84%8F%E9%BE%8D_-_panoramio_%281%29.jpg/960px-%E9%A1%98%E6%84%8F%E9%BE%8D_-_panoramio_%281%29.jpg', 'Sato S / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('栄林寺', 'other', 34.863194, 137.816778, '栄林寺（えいりんじ）は、静岡県浜松市天竜区にある曹洞宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Futamata_Ky%C5%8Dd%C5%8D_Center%2C_Former_site_of_K%C5%8Dmy%C5%8D_Electric_Railway_Futamatamachi_station.JPG/960px-Futamata_Ky%C5%8Dd%C5%8D_Center%2C_Former_site_of_K%C5%8Dmy%C5%8D_Electric_Railway_Futamatamachi_station.JPG', 'Twilight2640 / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('清瀧寺', 'other', 34.865306, 137.813472, '清瀧寺（せいりゅうじ）は、静岡県浜松市天竜区にある浄土宗知恩院の末寺。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Seiryu-ji_%28Hamamatsu%29.JPG/960px-Seiryu-ji_%28Hamamatsu%29.JPG', 'Wikipedia', 'wikipedia'),
  ('玄忠寺', 'other', 34.707444, 137.731944, '玄忠寺（げんちゅうじ）は、静岡県浜松市中央区にある浄土宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/Genchu-ji_%28Hamamatsu%29.JPG/960px-Genchu-ji_%28Hamamatsu%29.JPG', 'Wikipedia', 'wikipedia'),
  ('西伝寺', 'other', 34.702528, 137.763111, '西伝寺（せいでんじ）は、静岡県浜松市中央区にある浄土宗の寺院。', 'wikipedia', '', 'https://i.ytimg.com/vi/5L3Wcjg7gg8/hqdefault.jpg', 'YouTube', 'youtube'),
  ('諏訪神社', 'other', 34.865917, 137.813667, '諏訪神社（すわじんじゃ）は、静岡県浜松市天竜区二俣町二俣1111にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/Suwa_Jinja_%28Futamatacho%2C_Tenryu%2C_Hamamatsu%29.JPG/960px-Suwa_Jinja_%28Futamatacho%2C_Tenryu%2C_Hamamatsu%29.JPG', 'Wikipedia', 'wikipedia'),
  ('頭陀寺', 'other', 34.700000, 137.755639, '頭陀寺（ずたじ）は、静岡県浜松市中央区にある高野山真言宗の寺院。', 'wikipedia', '', 'https://i.ytimg.com/vi/5L3Wcjg7gg8/hqdefault.jpg', 'YouTube', 'youtube')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'num:国道152号:静岡'
