select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('栃原岩陰遺跡', 'other', 36.062000, 138.514778, '栃原岩陰遺跡（とちばらいわかげいせき）は、長野県南佐久郡北相木村で1965年に発見された縄文時代草創期・早期の岩陰遺跡である。', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/b/b6/Tochiharaiwakage_cave.jpg', 'Wikipedia', 'wikipedia'),
  ('ぶどう峠', 'pass', 36.064059, 138.642709, '長野県と群馬県境の峠', 'seed_auto', 'AyJeyK-MIZo', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/%E9%95%B7%E9%87%8E%E7%9C%8C%E5%8C%97%E7%9B%B8%E6%9C%A8%E6%9D%91%E3%81%B6%E3%81%A9%E3%81%86%E5%B3%A0_-_panoramio.jpg/960px-%E9%95%B7%E9%87%8E%E7%9C%8C%E5%8C%97%E7%9B%B8%E6%9C%A8%E6%9D%91%E3%81%B6%E3%81%A9%E3%81%86%E5%B3%A0_-_panoramio.jpg', 'mapplefan8 / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('道の駅上野', 'rest', 36.080530, 138.784060, '道の駅上野（みちのえき うえの）は、群馬県多野郡上野村にある国道299号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/Ueno_village_office.jpg/960px-Ueno_village_office.jpg', 'photo: Qurren (talk) Taken with Canon IXY 430F (Digital IXUS 245 HS) / CC BY-SA 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:ぶどう峠'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

