insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('6wdUntSNl5E', 'https://www.youtube.com/watch?v=6wdUntSNl5E', '【男鹿半島バイク旅】やっぱりこの景色が好き…。絶景の寒風山から日本のウユニ塩湖と呼ばれる鵜ノ崎海岸経由で入道崎へ！癒しの絶景を満喫するツーリング。【HONDA Gold Wing/モトブログ】', '突然rider', 21503, '10:00'),
  ('aZWhD6cj-Bk', 'https://www.youtube.com/watch?v=aZWhD6cj-Bk', '【絶景】バイクに乗らないと見られなかった景色。【高画質再アップ】', 'ゆきゆき', 15402, ''),
  ('1hHXYd9J4q0', 'https://www.youtube.com/watch?v=1hHXYd9J4q0', '【東北バイク旅】妻とタンデムで秋田県の男鹿半島を巡る絶景ツーリング！妻に見せたかった大自然の美しい景色や戸賀の人気グルメも満喫しました。【Honda Gold Wing/モトブログ】', '突然rider', 13041, '09:00'),
  ('2WL8S0IXOZI', 'https://www.youtube.com/watch?v=2WL8S0IXOZI', '男鹿半島１週、寒風山【絶景ツーリング】3泊4日東北ぐるり女一人旅『YAMAHA BOLT』ナツゾラ最高かよっ(*ﾟ∀ﾟ)#2/4', 'Black Bolt/boru', 5592, ''),
  ('oD6ghTxoRGw', 'https://www.youtube.com/watch?v=oD6ghTxoRGw', '3分半で東北ツーリング♪♯37', 'AIRU LAND.', 2323, ''),
  ('9UAmC0gq2kg', 'https://www.youtube.com/watch?v=9UAmC0gq2kg', '【東北絶景ツーリング】男鹿半島から青森へ‼️ゴジラ岩とうに丼に感動した一日💨バイクで行く日本一周の旅〜東北編〜PRIDEチャンネル vol.433', 'PRIDE LEGEND', 2321, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
