insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('EzvKwskPVXU', 'https://www.youtube.com/watch?v=EzvKwskPVXU', '【紅葉ツーリング2025年】榛名山×赤城山×奥日光 標高1800mを駆ける 関東絶景バイク旅 400X', 'Moto Lifez', 19507, '13:13'),
  ('LFecZDGtkzo', 'https://www.youtube.com/watch?v=LFecZDGtkzo', '【妻が初めてのいろは坂デビュー】奥日光の秘境と群馬の旬なグルメを満喫するツーリング。納涼スポットもこっそり教えちゃいます。【Rebel1100T/モトブログ】Gold Wing', '突然rider', 14396, ''),
  ('3PsKvaJhwIM', 'https://www.youtube.com/watch?v=3PsKvaJhwIM', 'モンキー125納車3ヶ月で新たな不具合発生…。異音、エンストの次はアイドリング中の発電不足？突然の変化に戸惑う…', 'ゼキザップ_モトブログ', 5087, ''),
  ('qK3bobs4k_E', 'https://www.youtube.com/watch?v=qK3bobs4k_E', '赤城山から奥日光へ【後編】秋にもおすすめ！金精道路・中禅寺湖を巡る約200km周回ツーリング', 'おでかけポコ', 4726, ''),
  ('AMPeFWejYUg', 'https://www.youtube.com/watch?v=AMPeFWejYUg', '【モトブログ】入道雲の下で夏満喫 真夏の群馬 絶景ルートを駆けるツーリング おじさん少年の夏へ帰る', '練り物ちっくーモトブログ', 2491, '26:40'),
  ('3yfNGq2uwtc', 'https://www.youtube.com/watch?v=3yfNGq2uwtc', '群馬・栃木・国道120号旅｜片品村から中禅寺湖へ！バイクでひた走るリアルな走行音だけのツーリング。青空と緑に囲まれた極上の快走路をただ疾走する、純粋なソロ走行没入型動画。【喋り・テロップなし】#266', 'Japan Moto Adventures', 192, '')
