insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('道の駅 さるふつ公園', 'rest', 45.329598, 142.176886, 'ホタテ料理などが楽しめる道の駅', 'seed_auto', '-xEJu76sX4o', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Sarufutsu_Park%2C_Roadside_Station%2C_Hokkaido%2C_Japan.jpg/960px-Sarufutsu_Park%2C_Roadside_Station%2C_Hokkaido%2C_Japan.jpg?utm_source=ja.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia', 'wikipedia'),
  ('宗谷岬', 'viewpoint', 45.511020, 141.943039, '日本最北端の地', 'seed_auto', '-xEJu76sX4o', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/%E5%AE%97%E8%B0%B7%E5%B2%AC%E7%89%A7%E5%A0%B4_-_panoramio.jpg/960px-%E5%AE%97%E8%B0%B7%E5%B2%AC%E7%89%A7%E5%A0%B4_-_panoramio.jpg', 'Yobito KAYANUMA / CC BY-SA 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'num:国道238号:北海'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

