insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('JaBiUuALAUo', 'https://www.youtube.com/watch?v=JaBiUuALAUo', '【能登半島の絶景ロード】北陸ツーリング2025年 白米千枚田・見附島・新湊大橋を巡る400X バイク旅', 'Moto Lifez', 8677, '19:09'),
  ('myrUkBw0Vvo', 'https://www.youtube.com/watch?v=myrUkBw0Vvo', '【冬の北陸】XSR125で走る海と雪山｜富山湾越しに現れる絶景とは…【カフェレーサー】', 'Picchio Channel | ぴっきおちゃんねる', 2440, ''),
  ('-z3qNXEHJVM', 'https://www.youtube.com/watch?v=-z3qNXEHJVM', '【富山サイクリング】海越しに浮かぶ立山連峰が絶景すぎた！富山湾岸サイクリングコース（氷見→富山）', 'じてりん-サイクリングとサイクルウェアの自転車チャンネル', 1862, ''),
  ('ExMWNJAL1CA', 'https://www.youtube.com/watch?v=ExMWNJAL1CA', 'レブルで行くSSTR北陸ツーリングのアフター旅: 絶景とグルメの隠れスポットを発見！', 'TYPE　RebeL タイプ　レブル　気ままにちゃんねる', 1035, '03:58'),
  ('2kbHRUAaWFg', 'https://www.youtube.com/watch?v=2kbHRUAaWFg', '北陸ツーリング2025Day2北陸中央高地を巡る旅の2日目。北アルプスを一望できるスポットを巡り能登半島では復興に少しでも役立ちたく・・最後はこの旅のメインスポット、千里浜なぎさドライブウェイ!!', 'motoVenture 🏍 モトベンチャー  ', 527, '02:09'),
  ('BR-ZN6nrSn8', 'https://www.youtube.com/watch?v=BR-ZN6nrSn8', '【クロスカブ夫婦旅】昭和を思い出す風景が富山には残っていた', 'なちの週末バイク旅', 526, '04:20')
