insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('5a46UywEF_E', 'https://www.youtube.com/watch?v=5a46UywEF_E', '【絶景ドライブ】まるで絵画のような日本の美しい道10選｜一度は走りたい絶景ロード', 'Holiday Ideas', 22484, '01:27'),
  ('XHh97dACF28', 'https://www.youtube.com/watch?v=XHh97dACF28', '【北海道ツーリング2025 #5】旭川→美瑛・富良野→積丹  色彩豊かな美瑛 富良野を走り積丹半島へ！【ジクサー150】 (Day 7)', 'み山の雑記帳', 10556, '05:57'),
  ('HHK-IVuP7TM', 'https://www.youtube.com/watch?v=HHK-IVuP7TM', '【北海道ツーリング2024】#6 北海道5日目 絶景のオロロンライン、美瑛、雪景色の十勝岳', 'NAKAのバイキャンチャンネル', 4335, ''),
  ('LUhzAi-NS3c', 'https://www.youtube.com/watch?v=LUhzAi-NS3c', '北海道ツーリング#13】美しすぎる美瑛の丘！ジェットコースターの道と、まさかの「樽」に泊まる夜', 'Oji〜', 3881, '01:35'),
  ('K7utPCzC_80', 'https://www.youtube.com/watch?v=K7utPCzC_80', '北海道ツーリング2020 夏 Part20「その男適当につき」', 'Cbr400r Takaprilia RS660', 3255, ''),
  ('46EorE-ya7I', 'https://www.youtube.com/watch?v=46EorE-ya7I', '【北海道ツーリング Day6】 美瑛 パッチワークの路・白金青い池　-北海道最終日-', 'NAKAのバイキャンチャンネル', 1119, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
