insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('唐津城', 'other', 33.453539, 129.978194, '唐津城（からつじょう）は、佐賀県唐津市東城内にあった日本の城郭。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/%E5%94%90%E6%B4%A5%E5%9F%8E_-_panoramio.jpg/960px-%E5%94%90%E6%B4%A5%E5%9F%8E_-_panoramio.jpg', 'Wikipedia', 'wikipedia'),
  ('諏訪神社', 'other', 33.448333, 130.038333, '諏訪神社（すわじんじゃ）は佐賀県唐津市（旧東松浦郡浜玉町）にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Suwajinja%2C_Karatsu%2C_Saga.jpg/960px-Suwajinja%2C_Karatsu%2C_Saga.jpg', 'Wikipedia', 'wikipedia'),
  ('鏡山展望台', 'viewpoint', 33.430577, 130.018043, '唐津湾や虹の松原を一望できる絶景スポット', 'seed_auto', '-qGdQaTwQd4', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/%E9%8F%A1%E5%B1%B1%E3%81%8B%E3%82%89%E5%94%90%E6%B4%A5%E5%9F%8E%E3%82%92%E6%9C%9B%E3%82%80_-_panoramio.jpg/960px-%E9%8F%A1%E5%B1%B1%E3%81%8B%E3%82%89%E5%94%90%E6%B4%A5%E5%9F%8E%E3%82%92%E6%9C%9B%E3%82%80_-_panoramio.jpg', '松浦党 / CC BY 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:虹の松原'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

