insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('1YTA6_-DJdI', 'https://www.youtube.com/watch?v=1YTA6_-DJdI', '関東周辺の絶景ツーリングスポット5選！ハンターカブ(原付二種)でも気軽に行けてオススメです^^', 'ゼキザップ_モトブログ', 22992, '08:53'),
  ('9RV8dJRMubE', 'https://www.youtube.com/watch?v=9RV8dJRMubE', '【東北バイク旅】六十里越えの国道252号線を走り日本屈指の秘境区間へ！奥会津と只見から新潟へ越後山脈を見渡す絶景ツーリング。【HONDA Gold Wing/Rebel 1100T/モトブログ】', '突然rider', 22499, ''),
  ('-GNOZHLQkAo', 'https://www.youtube.com/watch?v=-GNOZHLQkAo', '秘境！奥只見をぐるっと周回ツーリング！【Vストローム250SX】', 'へいぞうバイク旅', 8592, ''),
  ('82fxxrRM2CA', 'https://www.youtube.com/watch?v=82fxxrRM2CA', '【東北 絶景ドライブ】一度は走りたい絶景ロード13選｜奥入瀬・八幡平・蔵王・磐梯吾妻', 'Holiday Ideas', 1430, '05:02'),
  ('OeMCpafNhzQ', 'https://www.youtube.com/watch?v=OeMCpafNhzQ', '【新潟・六十里越え】大白川へ続く絶景の山岳快走路！青空と新緑、スノーシェッドを抜ける爽快ルートをバイクで走る｜喋り・テロップ一切なし、リアルなエンジン音と風だけを感じる純粋ツーリング #169', 'Japan Moto Adventures', 143, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
