insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('奥の院', 'other', 34.222981, 135.605723, '視聴者コメントで雰囲気が良いとお勧めされている高野山の聖地', 'seed_auto', 'Cyf9kh1vjLQ', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/%E9%AB%98%E9%87%8E%E5%B1%B1%E5%A5%A5%E3%81%AE%E9%99%A2%E3%81%AB%E3%81%A6_%E7%B9%94%E7%94%B0%E4%BF%A1%E9%95%B7%E3%81%AE%E5%A2%93_Tomb_of_Oda_Nobunaga_2011.8.27_-_panoramio.jpg/960px-%E9%AB%98%E9%87%8E%E5%B1%B1%E5%A5%A5%E3%81%AE%E9%99%A2%E3%81%AB%E3%81%A6_%E7%B9%94%E7%94%B0%E4%BF%A1%E9%95%B7%E3%81%AE%E5%A2%93_Tomb_of_Oda_Nobunaga_2011.8.27_-_panoramio.jpg', 'Nankou Oronain (as36… / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('定福寺', 'other', 34.308917, 135.612722, '定福寺（じょうふくじ）は、和歌山県橋本市賢堂（かしこど）にある高野山真言宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Jyofukuji.jpg/960px-Jyofukuji.jpg', 'Wikipedia', 'wikipedia'),
