insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('厳島神社', 'other', 34.339361, 134.896056, '厳島神社（いつくしまじんじゃ）は、兵庫県洲本市に鎮座する神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Itsukushima-jinja_Sumoto_Awaji_Island_Japan03n.jpg/960px-Itsukushima-jinja_Sumoto_Awaji_Island_Japan03n.jpg', 'Wikipedia', 'wikipedia'),
  ('洲本城', 'other', 34.337703, 134.902875, '洲本城（すもとじょう）は、淡路国津名郡洲本（兵庫県洲本市小路谷）にあった日本の城。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Sumoto_Castle_Awaji_Island_Japan01s.jpg/960px-Sumoto_Castle_Awaji_Island_Japan01s.jpg', 'Wikipedia', 'wikipedia'),
  ('淡路国分寺', 'other', 34.298536, 134.782653, '淡路国分寺（あわじこくぶんじ）は、兵庫県南あわじ市八木国分にある律宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/Awaji_Kokubunji_Temple.JPG/960px-Awaji_Kokubunji_Temple.JPG', 'Wikipedia', 'wikipedia'),
  ('淡路国分寺塔跡', 'other', 34.298181, 134.782861, '', 'wikipedia', '', 'https://i.ytimg.com/vi/g3sx5d03ETo/hqdefault.jpg', 'YouTube', 'youtube'),
  ('護国寺', 'other', 34.270167, 134.737167, '護國寺（ごこくじ）は、兵庫県南あわじ市賀集八幡にある高野山真言宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Gokokuji_Temple_Minamiawaji_City.JPG/960px-Gokokuji_Temple_Minamiawaji_City.JPG', 'Wikipedia', 'wikipedia'),
  ('道の駅福良', 'rest', 34.255640, 134.719250, '道の駅福良（みちのえき ふくら）は、兵庫県南あわじ市福良の福良港にある国道28号の道の駅。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/R028-2020-299.jpg/960px-R028-2020-299.jpg', 'Wikipedia', 'wikipedia'),
  ('大浜海岸', 'viewpoint', 34.341944, 134.902583, '大浜海岸（おおはまかいがん）は兵庫県洲本市にある白砂青松の砂浜海岸。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Ohama_Coast_Awaji_Island_Japan01s3.jpg/960px-Ohama_Coast_Awaji_Island_Japan01s3.jpg', 'Wikipedia', 'wikipedia'),
  ('洲本城跡', 'viewpoint', 34.337702, 134.902893, '天守台からの見晴らしが良い城跡', 'seed_auto', 'TMrIUEOQ8pQ', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/Dusk_over_Sumoto_City.jpg/960px-Dusk_over_Sumoto_City.jpg', 'Stephen Wheeler / CC BY 2.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:南淡路水仙ライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

