  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('小夜戸・大畑花桃街道', 'みどり市東町の渡良瀬川沿いに約1,500本の花桃が咲き誇る春に人気のローカルルート。
注意: 開花期は混雑・渋滞の可能性あり / 花桃の開花時期は混雑や交通規制あり / まつり・見頃期間中は車・歩行者混雑やすれ違い渋滞が発生しやすい / シーズン中は混雑・徐行車両に注意
（動画 5 本から自動抽出。位置は地図経路による推定）', '群馬県', '小夜戸交差点', '大畑花桃の里', 'SRID=4326;LINESTRING(139.329070 36.525720, 139.328980 36.526160, 139.327930 36.526850, 139.325960 36.525230, 139.325240 36.525410, 139.324710 36.525900, 139.324160 36.525800, 139.322500 36.524930, 139.322340 36.523540, 139.318010 36.521860, 139.317470 36.521020, 139.315190 36.519590, 139.314880 36.518380, 139.314690 36.518370, 139.314800 36.518640)', 1950, 0.52, true, 'https://www.youtube.com/watch?v=awoROiIUycs', 'おでかけポコ', 'seed_auto', 'routed', 'name:小夜戸・大畑花桃街道', 5.00, 2.00, 4.00, 2.75, 3.00, 5)
  on conflict (seed_key) do update set description = excluded.description, hint_scenery = excluded.hint_scenery, hint_winding = excluded.hint_winding, hint_surface = excluded.hint_surface, hint_rest = excluded.hint_rest, hint_parking = excluded.hint_parking, mention_count = excluded.mention_count, geom = excluded.geom, length_m = excluded.length_m, curviness = excluded.curviness, updated_at = now()
  returning id)
insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('awoROiIUycs', 'https://www.youtube.com/watch?v=awoROiIUycs', '見頃【赤城千本桜＆花桃街道＆穴場スポット紹介】赤城南面千本桜まつり2026開幕！小夜戸・大畑花桃街道バイクツーリングやドライブで走れるのか？走れないのか？草木ダム桜やわ鐵神戸駅の花桃など最新状況', 'おでかけポコ', 11608, '14:30'),
  ('0TQHYvFXoek', 'https://www.youtube.com/watch?v=0TQHYvFXoek', '偵察編【ローカル花道ルート情報】群馬県桐生市・みどり市一周。3月中旬〜下旬に人気の「花桃街道」「屋敷山ミツマタ群生地」「水沼駅河津桜」を巡る。林道を繋いで走る春の約70キロツーリングドライブルート', 'おでかけポコ', 8008, ''),
  ('R2FNKyQ8RS8', 'https://www.youtube.com/watch?v=R2FNKyQ8RS8', '開花状況＆絶景【渡良瀬渓谷鐡道沿い＋佐野市】春の小夜戸・大畑花桃街道＋神戸駅の花桃＋絶景ロード林道作原沢入線バイクツーリング＆ドライブルート！3月24日撮影', 'おでかけポコ', 7198, '04:15'),
  ('0lzhW7v9LyU', 'https://www.youtube.com/watch?v=0lzhW7v9LyU', '開花状況【花桃街道〜ミツマタ群生地】神戸駅の花桃・小夜戸大畑花桃街道・水沼の河津桜・屋敷山ミツマタ群生地などわたらせ渓谷鐵道沿いを巡るバイクツーリング＆ドライブ！', 'おでかけポコ', 6247, '06:16'),
  ('PGUn7iZUJmo', 'https://www.youtube.com/watch?v=PGUn7iZUJmo', '群馬のマイナー河津桜トンネルと、わたらせ渓谷鐵道沿線の梅と神戸駅の花桃2026｜モンキー125でお花見ツーリング', 'ゼキザップ_モトブログ', 3209, '05:06')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
