insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('2rEPEvro6Mc', 'https://www.youtube.com/watch?v=2rEPEvro6Mc', '鹿児島 指宿スカイラインツーリング', '週刊元少年ライダー', 7347, ''),
  ('fXvjhTKh8ek', 'https://www.youtube.com/watch?v=fXvjhTKh8ek', '【九州一周】愛媛から鹿児島へ500kmかけて絶景スポットをツーリング【MEGURO S1】【愛媛】', 'そそそのバイク旅TV', 4776, ''),
  ('-bxbBb9zpoo', 'https://www.youtube.com/watch?v=-bxbBb9zpoo', '154【九州ツーリング】鹿児島ツーリング　鹿児島のモアイを探して福岡から往復７０２キロ弾丸ツーリング＃モアイ像＃茶ばっけん丘＃指宿モアイ像', '5にゃんずライダー', 1301, ''),
  ('HV8VHfEeXvk', 'https://www.youtube.com/watch?v=HV8VHfEeXvk', '九州ツーリング #55 [鹿児島]360°の眺望！まるで天空の展望台！大野岳きらり＆しろろ展望台／日本本土最南端の駅JR西大山駅／スヌーピー山｜KAWASAKI Ninja1000', 'akichannel', 1042, '02:40')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('掃除山遺跡', 'other', 31.524278, 130.496972, '掃除山遺跡（そうじやまいせき）は、鹿児島県鹿児島市下福元町後迫字掃除山にある縄文時代草創期の遺跡である。', 'wikipedia', '', 'https://i.ytimg.com/vi/2rEPEvro6Mc/hqdefault.jpg', 'YouTube', 'youtube'),
  ('皇徳寺', 'other', 31.555278, 130.498972, '皇徳寺（こうとくじ）は薩摩国谿山郡谷山郷山田村（現 鹿児島県鹿児島市山田町）にあった曹洞宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6a/Koutokujidai_kagoshima-shi-japan-010.jpg/960px-Koutokujidai_kagoshima-shi-japan-010.jpg', 'Wikipedia', 'wikipedia'),
  ('スカイパレット', 'viewpoint', 31.442097, 130.484635, '売店や自販機が無くなったとのコメントあり', 'seed_auto', '2rEPEvro6Mc', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/From_the_Ibusuki_skyline_parkway_%284516796058%29.jpg/960px-From_the_Ibusuki_skyline_parkway_%284516796058%29.jpg', 'KimonBerlin / CC BY-SA 2.0 / Wikimedia Commons', 'commons'),
  ('西谷山', 'viewpoint', 31.523333, 130.507778, '西谷山（にしたにやま）は、鹿児島県鹿児島市の町丁。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Kaiyo_High_School.jpg/960px-Kaiyo_High_School.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:指宿スカイライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
