select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('9uv6dMbN2Sc', 'https://www.youtube.com/watch?v=9uv6dMbN2Sc', '【東北バイク旅】福島に来たら絶対に行くべき道！やっぱり福島三大ラインは凄かった…。裏磐梯にある大自然の絶景と人気の道の駅グルメを満喫しました。【HONDA Gold Wing/モトブログ】', '突然rider', 12049, ''),
  ('7AbO3UzPqqs', 'https://www.youtube.com/watch?v=7AbO3UzPqqs', 'バイクで行くと後悔するかも！？福島の超デカ盛り食堂【漢メシ】', 'ITKライダー', 8778, '04:38'),
  ('BcvCgc7ZelM', 'https://www.youtube.com/watch?v=BcvCgc7ZelM', '【バイク旅】妻とタンデムで4年ぶりの松島基地航空祭へ！制限なしで戻って来たブルーインパルスに感動。訓練飛行や航空機展示も楽しみました。【Honda Gold Wing/モトブログ】', '突然rider', 1708, ''),
  ('94X2cj831fk', 'https://www.youtube.com/watch?v=94X2cj831fk', '母成グリーンライン｜中ノ沢から磐梯熱海バイク旅。どこまでも続く青空の快走路、県道24号を駆け抜ける。喋りなし、ただ響くエンジン音に没入する福島・穴場絶景ロードのソロツーリング。#284', 'Japan Moto Adventures', 189, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('沼尻温泉', 'onsen', 37.618444, 140.227639, '沼尻温泉（ぬまじりおんせん）は、福島県耶麻郡猪苗代町蚕養こがいにある温泉である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/Numajiri_Hot_spa_Source.webp/960px-Numajiri_Hot_spa_Source.webp', 'Wikipedia', 'wikipedia'),
  ('磐梯熱海温泉', 'onsen', 37.481920, 140.270190, '磐梯熱海温泉（ばんだいあたみおんせん）は、福島県郡山市熱海町（旧国陸奥国、明治以降は岩代国）にある温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/%E7%A3%90%E6%A2%AF%E7%86%B1%E6%B5%B7%E6%B8%A9%E6%B3%89%E3%83%BB%E6%BA%90%E6%B3%89%E9%80%9A%E3%82%8A.jpg/960px-%E7%A3%90%E6%A2%AF%E7%86%B1%E6%B5%B7%E6%B8%A9%E6%B3%89%E3%83%BB%E6%BA%90%E6%B3%89%E9%80%9A%E3%82%8A.jpg', 'Wikipedia', 'wikipedia'),
  ('日本きもの文化美術館', 'other', 37.485361, 140.264500, '日本きもの美術館（にほんきものびじゅつかん）は福島県郡山市熱海町熱海にある美術館。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Japan_Kimono_Culture_Museum.JPG/960px-Japan_Kimono_Culture_Museum.JPG', 'Wikipedia', 'wikipedia'),
  ('日本きもの美術館', 'other', 37.485361, 140.264500, '日本きもの美術館（にほんきものびじゅつかん）は福島県郡山市熱海町熱海にある美術館。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/%E3%82%B1%E3%83%A4%E3%82%AD%E3%81%AE%E6%A3%AE%E5%85%A5%E5%8F%A3_-_panoramio.jpg/960px-%E3%82%B1%E3%83%A4%E3%82%AD%E3%81%AE%E6%A3%AE%E5%85%A5%E5%8F%A3_-_panoramio.jpg', 'Duff Figgy / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('高玉城', 'other', 37.498889, 140.278889, '高玉城（たかたまじょう）は、福島県郡山市熱海町高玉にあった日本の城（山城）。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/%E9%AB%98%E7%8E%89%E5%9F%8E%E5%9D%80_-_panoramio.jpg/960px-%E9%AB%98%E7%8E%89%E5%9F%8E%E5%9D%80_-_panoramio.jpg', 'Wikipedia', 'wikipedia'),
  ('母成峠', 'pass', 37.594200, 140.242800, '母成峠（ぼなりとうげ）は、福島県郡山市と猪苗代町の間にある峠。', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/2/2e/Bonari_pass.jpg?utm_source=ja.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', 'Wikipedia', 'wikipedia'),
  ('母成峠の戦い', 'pass', 37.595690, 140.242970, '母成峠の戦い（ぼなりとうげのたたかい、慶応4年8月21日（西暦1868年10月6日））は、会津戦争（戊辰戦争）の戦いの一つ。', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/2/2e/Bonari_pass.jpg', 'Wikipedia', 'wikipedia'),
  ('大峯不動滝', 'viewpoint', 37.479306, 140.267917, '大峯不動滝（おおみねふどうたき）は、福島県郡山市熱海町安子島字真弓山にある滝。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/%E5%A4%A7%E5%B3%AF%E4%B8%8D%E5%8B%95%E6%BB%9D_%E9%83%A1%E5%B1%B1%E5%B8%82_%E5%A4%8F.jpg/960px-%E5%A4%A7%E5%B3%AF%E4%B8%8D%E5%8B%95%E6%BB%9D_%E9%83%A1%E5%B1%B1%E5%B8%82_%E5%A4%8F.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:母成グリーンライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

