insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('安倍神像神社', 'other', 35.328583, 137.826583, '安倍神像神社（あべしんぞうじんじゃ）は、長野県下伊那郡阿南町にある神社。', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/1/14/%E5%AE%89%E5%80%8D%E6%99%8B%E4%B8%89%E5%85%83%E7%B7%8F%E7%90%86%E9%8A%85%E5%83%8F_%E5%AE%89%E5%80%8D%E7%A5%9E%E5%83%8F%E7%A5%9E%E7%A4%BE%E5%A2%83%E5%86%85.jpg', 'Wikipedia', 'wikipedia'),
  ('早稲田神社', 'other', 35.321389, 137.811806, '早稲田神社（わせだじんじゃ）は、長野県下伊那郡阿南町に所在する神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/%E6%97%A9%E7%A8%B2%E7%94%B0%E7%A5%9E%E7%A4%BE_%E6%8B%9D%E6%AE%BF.jpg/960px-%E6%97%A9%E7%A8%B2%E7%94%B0%E7%A5%9E%E7%A4%BE_%E6%8B%9D%E6%AE%BF.jpg', 'Wikipedia', 'wikipedia'),
  ('平岡ダム', 'viewpoint', 35.282500, 137.846667, '平岡ダム（ひらおかダム）は、長野県下伊那郡天龍村平岡地先、天竜川本川に建設されたダムである。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/Hiraoka_Dam.jpg/960px-Hiraoka_Dam.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:長野県道1号飯田富山佐久間線'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

