insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('塩原温泉天皇の間記念公園', 'onsen', 36.967083, 139.835472, '塩原温泉天皇の間記念公園（しおばらおんせん てんのうのまきねんこうえん）とは、栃木県那須塩原市にかつて存在した旧塩原御用邸の建物のうち、最後まで残されていた天皇御座所を近隣に移築保存したものである。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Imperial_Villa_Memorial_Park_%28Nasushiobara%29_01.JPG/960px-Imperial_Villa_Memorial_Park_%28Nasushiobara%29_01.JPG', 'Wikipedia', 'wikipedia'),
  ('塩原温泉郷', 'onsen', 36.968500, 139.823100, '塩原温泉郷（しおばらおんせんきょう）は、栃木県那須塩原市（旧国下野国）塩原地区内の、箒川沿いの谷間を中心に点在する11の温泉の総称（温泉郷）。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Yuppo_no_Sato.JPG/960px-Yuppo_no_Sato.JPG', 'Wikipedia', 'wikipedia'),
  ('塩釜温泉', 'onsen', 36.967810, 139.831720, '塩釜温泉（しおがまおんせん）は、栃木県那須塩原市（旧国下野国）にある塩原温泉郷の一つの温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Shiobara-Shiogama_Onsen_Town.jpg/960px-Shiobara-Shiogama_Onsen_Town.jpg', 'Wikipedia', 'wikipedia'),
  ('板室別邸 SPA 和薬草', 'onsen', 37.059994, 139.927900, '動画で宿泊した那須塩原の温泉宿', 'seed_auto', 'mJpjLdzXpaY', 'https://i.ytimg.com/vi/mJpjLdzXpaY/hqdefault.jpg', 'YouTube', 'youtube'),
  ('畑下温泉', 'onsen', 36.966780, 139.826690, '畑下温泉（はたおりおんせん）は、栃木県那須塩原市（旧国下野国）にある塩原温泉郷の一つの温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Hataori_Onsen_Town.jpg/960px-Hataori_Onsen_Town.jpg', 'Wikipedia', 'wikipedia'),
  ('福渡温泉', 'onsen', 36.964360, 139.837610, '福渡温泉（ふくわたおんせん）は、栃木県那須塩原市（旧国下野国）にある塩原温泉郷の一つの温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Fukuwata_Onsen_Shofuro_Matsuya.jpg/960px-Fukuwata_Onsen_Shofuro_Matsuya.jpg', 'Wikipedia', 'wikipedia'),
  ('門前温泉', 'onsen', 36.969780, 139.821420, '門前温泉（もんぜんおんせん）は、栃木県那須塩原市（旧国下野国）にある塩原温泉郷の一つの温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Shiobara_Monzen_Onsen.JPG/960px-Shiobara_Monzen_Onsen.JPG', 'Wikipedia', 'wikipedia'),
  ('妙雲寺', 'other', 36.970778, 139.821222, '妙雲寺（みょううんじ）は、栃木県那須塩原市塩原にある臨済宗妙心寺派の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/%E7%94%98%E9%9C%B2%E5%B1%B1%E5%A6%99%E9%9B%B2%E5%AF%BA%E5%A4%A7%E9%96%80.jpg/960px-%E7%94%98%E9%9C%B2%E5%B1%B1%E5%A6%99%E9%9B%B2%E5%AF%BA%E5%A4%A7%E9%96%80.jpg', 'Wikipedia', 'wikipedia'),
