insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('川古温泉', 'onsen', 36.758560, 138.885250, '川古温泉（かわふるおんせん）は、群馬県利根郡みなかみ町にある温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Akaya_River_Kawafuru_Onsen.jpg/960px-Akaya_River_Kawafuru_Onsen.jpg', 'Wikipedia', 'wikipedia'),
  ('湯宿温泉', 'onsen', 36.699720, 138.913720, '湯宿温泉（ゆじゅくおんせん）は、群馬県利根郡みなかみ町（旧国上野国）にある温泉。', 'wikipedia', '', 'https://i.ytimg.com/vi/W61wnRplcQ0/hqdefault.jpg', 'YouTube', 'youtube'),
  ('猿ヶ京温泉', 'onsen', 36.730640, 138.892780, '猿ヶ京温泉（さるがきょうおんせん）は、群馬県利根郡みなかみ町猿ヶ京温泉（旧利根郡新治村）にある温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/Lake_Akaya_Sarugakyo_Onsen.jpg/960px-Lake_Akaya_Sarugakyo_Onsen.jpg', 'Wikipedia', 'wikipedia'),
  ('大道峠', 'pass', 36.667500, 138.869444, '大道峠（だいどうとうげ）は、群馬県の利根郡みなかみ町と吾妻郡中之条町の町境にある峠。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/%E7%BE%A4%E9%A6%AC%E7%9C%8C%E4%B8%AD%E4%B9%8B%E6%9D%A1%E7%94%BA%E5%A4%A7%E9%81%93_09.jpg/960px-%E7%BE%A4%E9%A6%AC%E7%9C%8C%E4%B8%AD%E4%B9%8B%E6%9D%A1%E7%94%BA%E5%A4%A7%E9%81%93_09.jpg', 'スティーブ・ミズキ / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('道の駅たくみの里', 'rest', 36.696110, 138.908310, '道の駅たくみの里（みちのえき たくみのさと）は、群馬県利根郡みなかみ町にある群馬県道53号中之条湯河原線の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/Michinoeki_takumi_no_sato.jpg/960px-Michinoeki_takumi_no_sato.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:万沢林道'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

