  ('1RneCvPDdKc', 'https://www.youtube.com/watch?v=1RneCvPDdKc', '【千葉県バイク旅】こんな場所があったとは…。成田にある神秘的な新勝寺と目を疑うような驚きのスポットを巡るツーリング！表参道人気のグルメも満喫しました。【HONDA Gold Wing/モトブログ】', '突然rider', 20700, ''),
  ('5RNP3cSWNmY', 'https://www.youtube.com/watch?v=5RNP3cSWNmY', '【バイク】千葉→茨城南部（神栖）の絶景快走路を巡るツーリング【房総半島】', 'Gutti''s MotoVlog', 7660, ''),
  ('7HzkPB0FNKA', 'https://www.youtube.com/watch?v=7HzkPB0FNKA', '【茨城ツーリング】巨大すぎるぞ！？実は茨城のおすすめツーリングスポットを攻めてきたら…【モトブログ/Z900RS】【牛久大仏】', 'やさおバイクダイアリー【モトブログ】', 717, '')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('手子后神社', 'other', 35.748111, 140.826333, '手子后神社（てごさきじんじゃ）は、茨城県神栖市波崎にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c0/Tegosaki_Shrine_%28Kamisu_City%2C_Ibaraki_Prefecture%29_01.jpg/960px-Tegosaki_Shrine_%28Kamisu_City%2C_Ibaraki_Prefecture%29_01.jpg', 'Wikipedia', 'wikipedia'),
  ('神栖風力発電所', 'other', 35.863800, 140.742405, '', 'seed_auto', '', 'https://i.ytimg.com/vi/1RneCvPDdKc/hqdefault.jpg', 'YouTube', 'youtube'),
  ('1000人画廊', 'viewpoint', 35.895017, 140.726467, '護岸壁画と巨大な風車群が連なる絶景直線道路', 'seed_auto', '5RNP3cSWNmY', 'https://i.ytimg.com/vi/1RneCvPDdKc/hqdefault.jpg', 'YouTube', 'youtube'),
  ('鹿島臨海工業地帯', 'viewpoint', 35.916660, 140.709204, '夜間に立ち寄った工場夜景スポット', 'seed_auto', '5RNP3cSWNmY', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/Colored_RX-8_-_panoramio.jpg/960px-Colored_RX-8_-_panoramio.jpg', 'MC-V / CC BY 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:波崎シーサイドロード'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

