select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('不動寺', 'other', 36.316111, 138.800556, '不動寺（ふどうじ）は、群馬県安中市松井田町松井田にある真言宗豊山派の寺院である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Fudouji_%28Annakashi%29_Nioumon.jpg/960px-Fudouji_%28Annakashi%29_Nioumon.jpg', 'Wikipedia', 'wikipedia'),
  ('妙義神社', 'other', 36.300473, 138.762507, '', 'seed_auto', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/%E5%A6%99%E7%BE%A9%E7%A5%9E%E7%A4%BE_-_panoramio.jpg/960px-%E5%A6%99%E7%BE%A9%E7%A5%9E%E7%A4%BE_-_panoramio.jpg', 'Yoshio Kohara / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('杉ノ木峠', 'pass', 36.261890, 138.759390, '杉ノ木峠（すぎのきとうげ）は、群馬県の富岡市と甘楽郡下仁田町の境にある峠である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9d/%E4%B8%8A%E6%AF%9B%E4%B8%89%E5%B1%B1%E3%83%91%E3%83%8E%E3%83%A9%E3%83%9E%E8%A1%97%E9%81%93_-_panoramio.jpg/960px-%E4%B8%8A%E6%AF%9B%E4%B8%89%E5%B1%B1%E3%83%91%E3%83%8E%E3%83%A9%E3%83%9E%E8%A1%97%E9%81%93_-_panoramio.jpg', 'Yobito KAYANUMA / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('道の駅みょうぎ', 'rest', 36.299670, 138.765970, '道の駅みょうぎ（みちのえき みょうぎ）は、群馬県富岡市にある群馬県道196号上小坂四ツ家妙義線の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Michinoeki_myogi.jpg/960px-Michinoeki_myogi.jpg', 'Wikipedia', 'wikipedia'),
  ('中小坂鉄山', 'viewpoint', 36.228194, 138.768639, '中小坂鉄山（なかおさかてつざん）は、群馬県甘楽郡下仁田町にあった鉄鉱山で、上信電鉄下仁田駅周辺の下仁田町中心部から約2.5キロ北西側の、下仁田方面から長野県佐久市方面へと抜ける中山道のかつての脇往還であり、現在の国道254号沿いに位置してい', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Nakaosakatetuzan3.JPG/960px-Nakaosakatetuzan3.JPG', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:妙義山'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

