insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('光明寺', 'other', 34.875611, 137.818861, '光明寺（こうみょうじ）は、静岡県浜松市天竜区にある曹洞宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/%E5%85%89%E6%98%8E%E5%AF%BA%E3%81%AE%E9%BB%84%E9%87%91%E3%81%AE%E5%A4%A7%E9%BB%92%E5%A4%A9%E5%83%8F%E3%81%AC_-_panoramio.jpg/960px-%E5%85%89%E6%98%8E%E5%AF%BA%E3%81%AE%E9%BB%84%E9%87%91%E3%81%AE%E5%A4%A7%E9%BB%92%E5%A4%A9%E5%83%8F%E3%81%AC_-_panoramio.jpg', 'Sato S / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('光明山古墳', 'other', 34.874417, 137.819111, '光明山古墳（こうみょうさんこふん）は、静岡県浜松市天竜区山東にある古墳。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Komyosan_Kofun%2C_funkyu-1.jpg/960px-Komyosan_Kofun%2C_funkyu-1.jpg', 'Wikipedia', 'wikipedia'),
  ('大生寺', 'other', 34.941444, 137.829778, '大生寺（だいしょうじ）は、静岡県浜松市天竜区にある曹洞宗の寺院。', 'wikipedia', '', 'https://i.ytimg.com/vi/eq15WVz4iNE/hqdefault.jpg', 'YouTube', 'youtube'),
  ('山住神社', 'other', 35.134694, 137.913972, '山住神社（やまずみじんじゃ）は、静岡県浜松市天竜区水窪町山住山に鎮座する神社である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/%E5%B1%B1%E4%BD%8F%E7%A5%9E%E7%A4%BE_%E6%8B%9D%E6%AE%BF.JPG/960px-%E5%B1%B1%E4%BD%8F%E7%A5%9E%E7%A4%BE_%E6%8B%9D%E6%AE%BF.JPG', 'Wikipedia', 'wikipedia'),
  ('高根城', 'other', 35.149444, 137.867222, '高根城（たかねじょう） は、静岡県浜松市天竜区水窪町地頭方にあった日本の城。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/%E9%AB%98%E6%A0%B9%E5%9F%8E%EF%BC%88%E6%B5%9C%E6%9D%BE%E5%B8%82%EF%BC%89.jpg/960px-%E9%AB%98%E6%A0%B9%E5%9F%8E%EF%BC%88%E6%B5%9C%E6%9D%BE%E5%B8%82%EF%BC%89.jpg', 'Wikipedia', 'wikipedia'),
  ('道の駅いっぷく処横川', 'rest', 34.905470, 137.872060, '道の駅いっぷく処横川（みちのえき いっぷくどころよこかわ）は、静岡県浜松市天竜区にある国道362号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Michinoeki_Ippukudokoro-Yokokawa.JPG/960px-Michinoeki_Ippukudokoro-Yokokawa.JPG', 'Wikipedia', 'wikipedia'),
  ('道の駅天竜相津花桃の里', 'rest', 34.911890, 137.815000, '道の駅天竜相津花桃の里（みちのえき てんりゅうそうづはなもものさと）は、静岡県浜松市天竜区にある国道152号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/R152-813.jpg/960px-R152-813.jpg', 'Wikipedia', 'wikipedia'),
  ('布滝', 'viewpoint', 35.141847, 137.880989, 'ヤマビルが特に多い場所としてコメントで言及', 'seed_auto', 'eq15WVz4iNE', 'https://i.ytimg.com/vi/eq15WVz4iNE/hqdefault.jpg', 'YouTube', 'youtube')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:天竜スーパー林道'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

with r as (
