insert into public.road_videos (road_id, video_id, url, title, channel, view_count, timestamp_label)
select r.id, v.video_id, v.url, v.title, v.channel, v.view_count, v.ts from r, (values
  ('LSKkE_YovQo', 'https://www.youtube.com/watch?v=LSKkE_YovQo', '【XLR80】原付二種ツーリング　紀伊半島　東紀州　国道311号　小さなバイクだから出会えた奥熊野の旅　熊野灘　須賀利　尾鷲　九鬼　三重県バイクツーリング', 'photographer関野温の撮影旅', 3273, '01:36'),
  ('wCDpO05mV20', 'https://www.youtube.com/watch?v=wCDpO05mV20', '【バイクで行く快走路 スタンダード】三重県 熊野尾鷲道路 賀田ＩＣ 三木里ＩＣ 国道３１１号 快走 バイク ツーリング K1200GT 南紀', 'Ban Ban', 250, '00:00')
) as v(video_id, url, title, channel, view_count, ts)
on conflict (road_id, video_id) do nothing;
