select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('龍蔵寺', 'other', 36.669361, 139.445472, '龍蔵寺（りゅうぞうじ）は、栃木県日光市足尾町赤倉11-12にある天台宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/Ryuzo-ji_Ashio_ac_%281%29.jpg/960px-Ryuzo-ji_Ashio_ac_%281%29.jpg', 'Wikipedia', 'wikipedia'),
  ('日足トンネル', 'pass', 36.708889, 139.518333, '日足トンネル（にっそくトンネル）は、栃木県日光市の清滝地区と足尾地区を結ぶ国道122号のトンネルであり、1978年（昭和53年）3月30日に開通した。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Nissoku_Tunnel_southwest.jpg/960px-Nissoku_Tunnel_southwest.jpg', 'Wikipedia', 'wikipedia'),
  ('細尾峠', 'pass', 36.710528, 139.514182, '旧日足トンネル旧道にある峠', 'seed_auto', 'HWj0jfNePOA', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/%E7%B4%B0%E5%B0%BE%E5%B3%A0_-_panoramio.jpg/960px-%E7%B4%B0%E5%B0%BE%E5%B3%A0_-_panoramio.jpg', 'Yobito KAYANUMA / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('明智平', 'viewpoint', 36.737239, 139.516250, 'いろは坂の途中にある絶景・観光スポット', 'seed_auto', 'HWj0jfNePOA', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/%E6%98%8E%E6%99%BA%E5%B9%B3_-_panoramio.jpg/960px-%E6%98%8E%E6%99%BA%E5%B9%B3_-_panoramio.jpg', 'harerukana / CC BY-SA 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:細尾峠'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

