  ('雑賀埼灯台', 'viewpoint', 34.188278, 135.140944, '雑賀埼灯台（さいかさきとうだい）、または雑賀崎灯台（さいかざきとうだい）は和歌山県和歌山市和歌浦の雑賀崎にある灯台。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Saikazaki_lighthouse01n3200.jpg/960px-Saikazaki_lighthouse01n3200.jpg', 'Wikipedia', 'wikipedia'),
  ('雑賀崎', 'viewpoint', 34.189560, 135.144372, '斜面に家々が並ぶ「日本のアマルフィ」と呼ばれる絶景スポット', 'seed_auto', 'AVSWhgCJ11Y', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/%E9%9B%91%E8%B3%80%E5%B4%8E%E3%81%AE%E5%A4%95%E9%99%BD_%E3%83%9B%E3%83%86%E3%83%AB%E5%A4%AA%E5%85%AC%E6%9C%9B%E3%81%8B%E3%82%89_-_panoramio.jpg/960px-%E9%9B%91%E8%B3%80%E5%B4%8E%E3%81%AE%E5%A4%95%E9%99%BD_%E3%83%9B%E3%83%86%E3%83%AB%E5%A4%AA%E5%85%AC%E6%9C%9B%E3%81%8B%E3%82%89_-_panoramio.jpg', 'akamitori / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('雑賀崎灯台', 'viewpoint', 34.188362, 135.140959, '視聴者コメントで言及された夕日の名所', 'seed_auto', 'AVSWhgCJ11Y', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/Futago_Jima_%28kapuloan_sa_Hapon%2C_Wakayama-ken%29%2C_on_the_left.jpg/960px-Futago_Jima_%28kapuloan_sa_Hapon%2C_Wakayama-ken%29%2C_on_the_left.jpg', 'Syced / CC0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:加太シーサイドライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

