select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('大久寺', 'other', 35.245744, 139.148356, '大久寺（だいきゅうじ）は、神奈川県小田原市にある日蓮宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/Daikyu-ji_Temple_in_Odawara_city.jpg/960px-Daikyu-ji_Temple_in_Odawara_city.jpg', 'Wikipedia', 'wikipedia'),
  ('妙覚寺', 'other', 35.248011, 139.131125, '妙覚寺（みょうかくじ）は、神奈川県小田原市風祭にある日蓮宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Myokaku-ji_Temple_in_Odawara_city.jpg/960px-Myokaku-ji_Temple_in_Odawara_city.jpg', 'Wikipedia', 'wikipedia'),
  ('居神神社', 'other', 35.247000, 139.148167, '居神神社（いがみじんじゃ）は、神奈川県小田原市の旧小田原宿、板橋口（上方口）近くに鎮座する三浦荒次郎義意公を主祭神に祀る神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/%E5%B1%85%E7%A5%9E%E7%A5%9E%E7%A4%BE%E5%85%A5%E3%82%8A%E5%8F%A3_01.jpg/960px-%E5%B1%85%E7%A5%9E%E7%A5%9E%E7%A4%BE%E5%85%A5%E3%82%8A%E5%8F%A3_01.jpg', 'Wikipedia', 'wikipedia'),
  ('山王神社', 'other', 35.256139, 139.169806, '山王神社（さんのうじんじゃ）は、神奈川県小田原市浜町に所在する神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Sanno_Shrine_in_Odawara_city.jpg/960px-Sanno_Shrine_in_Odawara_city.jpg', 'Wikipedia', 'wikipedia'),
  ('松原神社', 'other', 35.249444, 139.159861, '松原神社（まつばらじんじゃ）は神奈川県小田原市にある神社である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Matshubara_Shrine_in_Odawara_city.jpg/960px-Matshubara_Shrine_in_Odawara_city.jpg', 'Wikipedia', 'wikipedia'),
  ('法船寺', 'other', 35.266056, 139.185086, '法船寺（ほうせんじ）は神奈川県小田原市酒匂（さかわ）二丁目35番地にある日蓮宗の寺。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/Housen-ji_Temple_in_Odawara_city.jpg/960px-Housen-ji_Temple_in_Odawara_city.jpg', 'Wikipedia', 'wikipedia'),
  ('真楽寺', 'other', 35.280300, 139.210011, '眞樂寺（しんらくじ）は、神奈川県小田原市にある真宗大谷派の聖徳太子開闢、親鸞聖人七箇年、覚如上人、蓮如上人御逗留の浄土真宗東西分派以前よりある御旧跡寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/Shinraku-ji_Temple_in_Odawara_city.jpg/960px-Shinraku-ji_Temple_in_Odawara_city.jpg', 'Wikipedia', 'wikipedia'),
  ('蓮昌寺', 'other', 35.245028, 139.156028, '蓮昌寺（れんしょうじ）は神奈川県小田原市にある日蓮宗の寺。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Jouei-ji_Temple_in_Odawara_city.jpg/960px-Jouei-ji_Temple_in_Odawara_city.jpg', 'Wikipedia', 'wikipedia'),
  ('西湘パーキングエリア', 'rest', 35.287184, 139.233551, '海が一望できるパーキングエリア', 'seed_auto', 'Ai29HwuViXo', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Maekawa%2C_Odawara%2C_Kanagawa_Prefecture_256-0813%2C_Japan_-_panoramio_%283%29.jpg/960px-Maekawa%2C_Odawara%2C_Kanagawa_Prefecture_256-0813%2C_Japan_-_panoramio_%283%29.jpg', '運転太郎 / CC BY 3.0 / Wikimedia Commons', 'commons')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:西湘バイパス'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

