select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('悟真寺', 'other', 32.752500, 129.861944, '悟真寺（ごしんじ）は長崎県長崎市にある浄土宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Main_temple_building_of_Goshin-temple.jpg/960px-Main_temple_building_of_Goshin-temple.jpg', 'Wikipedia', 'wikipedia'),
  ('日本二十六聖人記念館', 'other', 32.754706, 129.871725, '日本二十六聖人記念館（にほんにじゅうろくせいじんきねんかん）は、長崎県長崎市にある、日本二十六聖人の顕彰を目的としてカトリック教会によって設立された博物館。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/%E6%97%A5%E6%9C%AC%E4%BA%8C%E5%8D%81%E5%85%AD%E8%81%96%E4%BA%BA%E8%A8%98%E5%BF%B5%E9%A4%A82015.JPG/960px-%E6%97%A5%E6%9C%AC%E4%BA%8C%E5%8D%81%E5%85%AD%E8%81%96%E4%BA%BA%E8%A8%98%E5%BF%B5%E9%A4%A82015.JPG', 'Wikipedia', 'wikipedia'),
  ('本蓮寺', 'other', 32.754139, 129.873750, '本蓮寺（ほんれんじ）は、長崎県長崎市にある日蓮宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Nichiren_statue_at_Honren-ji_Nagasaki.jpg/960px-Nichiren_statue_at_Honren-ji_Nagasaki.jpg', 'Wikipedia', 'wikipedia'),
  ('福済寺', 'other', 32.753308, 129.874972, '福済寺（ふくさいじ）は、長崎県長崎市筑後町にある黄檗宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/The_Kannon_Universal_Temple_Fukusai-ji_entrance_-_panoramio_%283%29.jpg/960px-The_Kannon_Universal_Temple_Fukusai-ji_entrance_-_panoramio_%283%29.jpg', 'Masoud Akbari / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('聖福寺', 'other', 32.753047, 129.877075, '聖福寺（しょうふくじ）は長崎県長崎市にある黄檗宗の仏教寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/NagasakiShofukuji2.jpg/960px-NagasakiShofukuji2.jpg', 'Wikipedia', 'wikipedia'),
  ('観善寺', 'other', 32.752876, 129.876515, '観善寺（かんぜんじ）は、長崎県長崎市玉園町にある浄土真宗本願寺派の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/Kanzenji.jpg/960px-Kanzenji.jpg', 'Wikipedia', 'wikipedia'),
  ('長崎歴史文化博物館', 'other', 32.752833, 129.879500, '長崎歴史文化博物館（ながさきれきしぶんかはくぶつかん、Nagasaki Museum of History and Culture）は、長崎県長崎市立山にある長崎県立および長崎市立の博物館である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Nagasaki_Museum_of_History_and_Culture_overhead_view_20230324.jpg/960px-Nagasaki_Museum_of_History_and_Culture_overhead_view_20230324.jpg', 'Wikipedia', 'wikipedia'),
  ('道の駅夕陽が丘そとめ', 'rest', 32.835890, 129.703720, '道の駅夕陽が丘そとめ（みちのえき ゆうひがおかそとめ）は、長崎県長崎市東出津町にある国道202号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Rs-nagasaki-yuhigaokasotome.jpg/960px-Rs-nagasaki-yuhigaokasotome.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:長崎サンセットロード'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

