insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('新甲子温泉', 'onsen', 37.175530, 140.029220, '新甲子温泉（しんかしおんせん）は、福島県西白河郡西郷村（旧国陸奥国、明治以降は磐城国）にある温泉。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/20081105%E6%96%B0%E7%94%B2%E5%AD%90%E6%B8%A9%E6%B3%89.JPG/960px-20081105%E6%96%B0%E7%94%B2%E5%AD%90%E6%B8%A9%E6%B3%89.JPG', 'Wikipedia', 'wikipedia'),
  ('那須温泉郷', 'onsen', 37.124060, 139.996360, '那須温泉郷（なすおんせんきょう）は、栃木県那須郡（旧国下野国）那須町に散在する温泉の総称（温泉郷）。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/Kita_Onsen_-_panoramio.jpg/960px-Kita_Onsen_-_panoramio.jpg', 'ninpuukamui / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('那須ロープウェイ', 'other', 37.125319, 139.979292, '那須ロープウェイ（なすロープウェイ）は、栃木県那須郡那須町にある那須岳にかかる索道（ロープウェイ）の一つで、那須岳の峰の一つである茶臼岳の山頂付近と山麓を結んでいる。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Tochigi-Mt._Nasu_that_burns_in_autumn-m.jpg/960px-Tochigi-Mt._Nasu_that_burns_in_autumn-m.jpg', 'Wikipedia', 'wikipedia'),
  ('大丸園地駐車場', 'rest', 37.120814, 139.984907, '那須高原線沿いの駐車場・休憩スポット', 'seed_auto', 'jjTxi3hhNUU', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Yumoto%2C_Nasu%2C_Nasu_District%2C_Tochigi_Prefecture_325-0301%2C_Japan_-_panoramio_%285%29.jpg/960px-Yumoto%2C_Nasu%2C_Nasu_District%2C_Tochigi_Prefecture_325-0301%2C_Japan_-_panoramio_%285%29.jpg', 'Fumihiko Ueno / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('那須ロープウェイ山麓駅', 'rest', 37.125422, 139.979287, '那須岳へ登るロープウェイの山麓駅', 'seed_auto', 'jjTxi3hhNUU', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Yumoto%2C_Nasu%2C_Nasu_District%2C_Tochigi_Prefecture_325-0301%2C_Japan_-_panoramio_%285%29.jpg/960px-Yumoto%2C_Nasu%2C_Nasu_District%2C_Tochigi_Prefecture_325-0301%2C_Japan_-_panoramio_%285%29.jpg', 'Fumihiko Ueno / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('つつじ吊橋', 'viewpoint', 37.106127, 140.001479, '高所からの素晴らしい景色を楽しめる巨大な吊橋', 'seed_auto', 'jjTxi3hhNUU', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Yumoto%2C_Nasu%2C_Nasu_District%2C_Tochigi_Prefecture_325-0301%2C_Japan_-_panoramio_%2810%29.jpg/960px-Yumoto%2C_Nasu%2C_Nasu_District%2C_Tochigi_Prefecture_325-0301%2C_Japan_-_panoramio_%2810%29.jpg', 'Fumihiko Ueno / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('座頭ころばし展望台', 'viewpoint', 37.172615, 140.054927, '山々を見渡す絶景の展望台', 'seed_auto', 'jjTxi3hhNUU', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/%E9%98%BF%E6%AD%A6%E9%9A%88%E5%B7%9D%E6%B8%93%E8%B0%B7%E5%B1%95%E6%9C%9B%E5%8F%B0%E3%81%8B%E3%82%89_20131013_-_panoramio.jpg/960px-%E9%98%BF%E6%AD%A6%E9%9A%88%E5%B7%9D%E6%B8%93%E8%B0%B7%E5%B1%95%E6%9C%9B%E5%8F%B0%E3%81%8B%E3%82%89_20131013_-_panoramio.jpg', '690 Noda / CC BY 3.0 / Wikimedia Commons', 'commons'),
  ('白河高原スキー場', 'viewpoint', 37.148333, 140.009444, '白河高原スキー場（しらかわこうげんスキーじょう）とは、福島県西郷村にかつて存在したスキー場である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/Sirakawakougensuki-.jpg/960px-Sirakawakougensuki-.jpg', 'Wikipedia', 'wikipedia'),
  ('那須高原', 'viewpoint', 37.109681, 140.001183, '那須高原（なすこうげん）とは、栃木県北部の那須岳の南側山麓地域を言い、那須岳の標高千数百メートルの地域より東北本線、国道4号が通る標高300m辺りまで、緩やかな斜面が広がる。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/20090321%E9%82%A3%E9%A0%88%E5%B2%B3.jpg/960px-20090321%E9%82%A3%E9%A0%88%E5%B2%B3.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:那須甲子ライン'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

