insert into public.road_spots (road_id, name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source)
select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('上田城', 'other', 36.400000, 138.240000, '上田城（うえだじょう）は、長野県上田市二の丸（旧・信濃国小県郡上田）にあった日本の城。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/Ueda_Castle_Amagafuchi.jpg/960px-Ueda_Castle_Amagafuchi.jpg', 'Wikipedia', 'wikipedia'),
  ('上田城跡公園', 'other', 36.403778, 138.244417, '上田城跡公園（うえだじょうせきこうえん）は、長野県上田市にある、上田城を中心に整備された都市公園（総合公園）である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/Ueda_Castle.JPG/960px-Ueda_Castle.JPG', 'Wikipedia', 'wikipedia'),
  ('丸子城', 'other', 36.317306, 138.263556, '丸子城（まるこじょう）は、長野県上田市上丸子にあった日本の城である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/Watchtower_at_Maruko_Castle.jpg/960px-Watchtower_at_Maruko_Castle.jpg', 'Wikipedia', 'wikipedia'),
  ('信濃国分寺', 'other', 36.383036, 138.271083, '信濃国分寺（しなのこくぶんじ）は、長野県上田市国分（こくぶ）にある天台宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Shinano_Kokubunji%2C_hondou-1.jpg/960px-Shinano_Kokubunji%2C_hondou-1.jpg', 'Wikipedia', 'wikipedia'),
  ('宝蔵寺', 'other', 36.328703, 138.263161, '宝蔵寺（ほうぞうじ）は、長野県上田市にある浄土宗の寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Uchimura_River_Nagano_Japan.jpg/960px-Uchimura_River_Nagano_Japan.jpg', 'Triglav / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('尾澤木彫美術館', 'other', 36.379117, 138.276486, '尾澤木彫美術館（おざわもくちょうびじゅつかん、英語: Ozawa Wooden Sculpture Art Museum）は、長野県上田市に所在する美術館。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Ozawa_Wooden_Sculpture_Art_Museum_1.jpg/960px-Ozawa_Wooden_Sculpture_Art_Museum_1.jpg', 'Wikipedia', 'wikipedia'),
  ('武石ともしび博物館', 'other', 36.287044, 138.230000, '武石ともしび博物館（たけしともしびはくぶつかん）は、長野県上田市にある博物館。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/Takeshi_Tomoshibi_Museum_1.jpg/960px-Takeshi_Tomoshibi_Museum_1.jpg', 'Wikipedia', 'wikipedia'),
  ('スキーゲレンデ頂上', 'viewpoint', 36.220700, 138.172178, '林道を抜けた先にある絶景のゲレンデ頂上でお昼休憩', 'seed_auto', '7y1L1BJvLKk', 'https://i.ytimg.com/vi/7y1L1BJvLKk/hqdefault.jpg', 'YouTube', 'youtube'),
  ('池波正太郎真田太平記館', 'viewpoint', 36.403111, 138.253528, '池波正太郎真田太平記館（いけなみしょうたろうさなだたいへいきかん）とは、長野県上田市にある文学館。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Ikenami_Shotaro_Sanada_Taiheiki_Kan.JPG/960px-Ikenami_Shotaro_Sanada_Taiheiki_Kan.JPG', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:菅の沢林道'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

