  ('ファミリーマート 河野北前船主通り店', 'rest', 35.827137, 136.066840, 'しおかぜライン走行時の休憩スポット', 'seed_auto', 'T4z4gy-8cro', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0d/%E5%9C%9F%E8%94%B5%E5%B1%8B%E6%A0%B9%E9%83%A8%E5%88%86.jpg/960px-%E5%9C%9F%E8%94%B5%E5%B1%8B%E6%A0%B9%E9%83%A8%E5%88%86.jpg', 'Suomi3 / CC0 / Wikimedia Commons', 'commons'),
  ('道の駅河野', 'rest', 35.796690, 136.091940, '道の駅河野（みちのえき こうの）は、福井県南条郡南越前町大谷にある国道8号の道の駅である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Michinoeki_Kono.jpg/960px-Michinoeki_Kono.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:越前しおかぜライン'
