  ('穴守稲荷神社', 'other', 35.550389, 139.749639, '穴守稲荷神社（あなもりいなりじんじゃ）は、東京都大田区羽田にある稲荷神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/%E7%A9%B4%E5%AE%88%E7%A8%B2%E8%8D%B7%E7%A5%9E%E7%A4%BE%E6%AD%A3%E9%9D%A2.jpg/960px-%E7%A9%B4%E5%AE%88%E7%A8%B2%E8%8D%B7%E7%A5%9E%E7%A4%BE%E6%AD%A3%E9%9D%A2.jpg', 'Wikipedia', 'wikipedia'),
  ('羽田空港第1ターミナル', 'other', 35.549535, 139.784319, '', 'seed_auto', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Lufthansa_Boeing_747-8I_D-ABYT_%2845910599305%29.jpg/960px-Lufthansa_Boeing_747-8I_D-ABYT_%2845910599305%29.jpg', 'Melv_L - MACASR / CC BY-SA 2.0 / Wikimedia Commons', 'commons'),
  ('羽田空港第3ターミナル', 'other', 35.543913, 139.768155, '', 'seed_auto', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/2_Chome-6_Hanedak%C5%ABk%C5%8D%2C_%C5%8Cta-ku%2C_T%C5%8Dky%C5%8D-to_144-0041%2C_Japan_-_panoramio_%283%29.jpg/960px-2_Chome-6_Hanedak%C5%ABk%C5%8D%2C_%C5%8Cta-ku%2C_T%C5%8Dky%C5%8D-to_144-0041%2C_Japan_-_panoramio_%283%29.jpg', 'KΛNΛTΛ / CC BY-SA 3.0 / Wikimedia Commons', 'commons'),
  ('羽田航空神社', 'other', 35.553333, 139.781111, '羽田航空神社（はねだこうくうじんじゃ）は、東京都大田区羽田空港の東京国際空港（羽田空港）第1旅客ターミナル内にある神社である。', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/3/3e/%E6%AD%A3%E9%9D%A2%E3%81%8B%E3%82%89%E8%A6%8B%E3%81%9F%E7%BE%BD%E7%94%B0%E8%88%AA%E7%A9%BA%E7%A5%9E%E7%A4%BE.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'name:環八通り'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

