select z.id, s.name, s.kind, s.lat, s.lng, s.note, s.source, s.video_id, s.photo_url, s.photo_credit, s.photo_source from public.zekkei_roads z, (values
  ('みずのき美術館', 'other', 35.014861, 135.577583, 'みずのき美術館(みずのきびじゅつかん)は、京都府亀岡市にある障害者支援施設みずのきの絵画教室（1964年〜2001年）から生まれた作品約２万点の所蔵と展示、そしてアール・ブリュットの考察を基本に据えた美術館である。', 'wikipedia', '', 'https://i.ytimg.com/vi/G344eX3D-FE/hqdefault.jpg', 'YouTube', 'youtube'),
  ('丸岡城', 'other', 35.018722, 135.571778, '丸岡城（まるおかじょう）は、京都府亀岡市余部町古城（旧・丹波国桑田郡）にあった中世の日本の城。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Saiganji_Temple_-_Maruoka_Castle_20190505_01.jpg/960px-Saiganji_Temple_-_Maruoka_Castle_20190505_01.jpg', 'Wikipedia', 'wikipedia'),
  ('亀山城', 'other', 35.013561, 135.581200, '亀山城（かめやまじょう）は、京都府亀岡市荒塚町周辺（旧丹波国桑田郡亀岡）にあった日本の城。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/Kameyama-jo_Tambanokuni_ishigaki.jpg/960px-Kameyama-jo_Tambanokuni_ishigaki.jpg', 'Wikipedia', 'wikipedia'),
  ('春日神社', 'other', 35.078250, 135.218833, '春日神社（かすがじんじゃ）は、兵庫県丹波篠山市黒岡75にある神社。', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/2/27/%E7%AF%A0%E5%B1%B1%E6%98%A5%E6%97%A5%E7%A5%9E%E7%A4%BE%E6%9C%AC%E6%AE%BFsasayama-kasugajinjaPA156109.jpg', 'Wikipedia', 'wikipedia'),
  ('波々伯部神社', 'other', 35.070833, 135.299722, '波々伯部神社（ほほかべじんじゃ、ほうかべじんじゃ）は、兵庫県丹波篠山市波々伯部・宮ノ前にある神社。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/Hohokabe-jinja_Festival_%E6%B3%A2%E3%80%85%E4%BC%AF%E9%83%A8%E7%A5%9E%E7%A4%BE_8%E6%9C%88%E7%AC%AC1%E5%9C%9F%E3%83%BB%E6%97%A5%E6%9B%9C%E6%97%A5%EF%BC%88_%E6%97%A7%E6%9A%A66%E6%9C%8814%E6%97%A5%EF%BC%89%E4%BE%8B%E7%A5%AD%E3%80%8C%E3%81%8A%E3%82%84%E3%81%BE%E8%A1%8C%E4%BA%8B%E3%80%8D_DSCF5368.jpg/960px-Hohokabe-jinja_Festival_%E6%B3%A2%E3%80%85%E4%BC%AF%E9%83%A8%E7%A5%9E%E7%A4%BE_8%E6%9C%88%E7%AC%AC1%E5%9C%9F%E3%83%BB%E6%97%A5%E6%9B%9C%E6%97%A5%EF%BC%88_%E6%97%A7%E6%9A%A66%E6%9C%8814%E6%97%A5%EF%BC%89%E4%BE%8B%E7%A5%AD%E3%80%8C%E3%81%8A%E3%82%84%E3%81%BE%E8%A1%8C%E4%BA%8B%E3%80%8D_DSCF5368.jpg', 'Wikipedia', 'wikipedia'),
  ('金剛寺', 'other', 35.008681, 135.545908, '金剛寺（こんごうじ）は京都府亀岡市曽我部町穴太にある臨済宗天龍寺派の仏教寺院。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/Kongoji_kameoka01s3200.jpg/960px-Kongoji_kameoka01s3200.jpg', 'Wikipedia', 'wikipedia'),
  ('天引峠', 'pass', 35.068753, 135.382254, '', 'seed_auto', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/R372-079.jpg/960px-R372-079.jpg', 'Puchi-masashi / CC BY-SA 4.0 / Wikimedia Commons', 'commons'),
  ('道の駅ガレリアかめおか', 'rest', 35.014889, 135.566333, '道の駅ガレリアかめおか（みちのえき ガレリアかめおか）は、京都府亀岡市余部町（あまるべちょう）にある国道9号の道の駅である。', 'wikipedia', '', 'https://upload.wikimedia.org/wikipedia/commons/2/2b/Garelia_kameoka.jpg', 'Wikipedia', 'wikipedia'),
  ('亀岡運動公園', 'viewpoint', 35.013883, 135.548458, '亀岡運動公園（かめおかうんどうこうえん）は、京都府亀岡市にある運動公園である。', 'wikipedia', '', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/Kameoka_athletic_park_gymnasium.jpg/960px-Kameoka_athletic_park_gymnasium.jpg', 'Wikipedia', 'wikipedia')
) as s(name, kind, lat, lng, note, source, video_id, photo_url, photo_credit, photo_source) where z.seed_key = 'num:国道372号:京'
on conflict (road_id, name) do update set note = excluded.note, kind = excluded.kind, source = excluded.source, photo_url = coalesce(excluded.photo_url, road_spots.photo_url), photo_credit = coalesce(excluded.photo_credit, road_spots.photo_credit), photo_source = coalesce(excluded.photo_source, road_spots.photo_source) where road_spots.source in ('seed_auto', 'wikipedia');

