with r as (
  insert into public.zekkei_roads (name, description, prefecture, start_label, end_label, geom, length_m, curviness, is_seed, youtube_url, youtube_channel, source, geometry_quality, seed_key, hint_scenery, hint_winding, hint_surface, hint_rest, hint_parking, mention_count)
  values ('滝沢展望台ルート（浜松風力発電所 舗装アクセス路）', '視聴者から推奨された舗装ルート。途中の滝沢展望台からは遠州灘と浜松市街が一望できる絶景スポットです。
注意: 舗装路だが勾配がきつく道幅が狭い
（動画 1 本から自動抽出。位置は地図経路による推定）', '静岡県', '滝沢展望台', '浜松風力発電所', 'SRID=4326;LINESTRING(137.714570 34.862240, 137.713950 34.861980, 137.713110 34.860650, 137.712250 34.860610, 137.711800 34.860150, 137.710930 34.859970, 137.710870 34.858930, 137.710630 34.858640, 137.710040 34.858560, 137.709220 34.859160, 137.708340 34.858950, 137.708310 34.858690, 137.708880 34.858140, 137.708110 34.858130, 137.708200 34.857700, 137.705110 34.855020, 137.701170 34.853030, 137.700900 34.852500, 137.699740 34.852110)', 2176, 0.64, true, 'https://www.youtube.com/watch?v=MQPF6VUyQnY', 'さてバイ ーさて、バイクに乗ってどこ行こう?ー', 'seed_auto', 'routed', 'name:滝沢展望台ルート', 5.00, 4.00, 3.00, 2.00, 3.00, 1)
  on conflict (seed_key) do update set description = excluded.description, hint_scenery = excluded.hint_scenery, hint_winding = excluded.hint_winding, hint_surface = excluded.hint_surface, hint_rest = excluded.hint_rest, hint_parking = excluded.hint_parking, mention_count = excluded.mention_count, geom = excluded.geom, length_m = excluded.length_m, curviness = excluded.curviness, updated_at = now()
  returning id)
